export default "encrypted is not None,\\n        )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_configuration(self) -> Self:\\n        \\\"\\\"\\\"Validate without assigning through SQLAlchemy instrumentation.\\\"\\\"\\\"\\n        provider_settings = _validate_provider_settings(self.protocol, self.provider_settings)\\n        _validate_enabled_config(\\n            provider_settings,\\n            enabled=self.enabled,\\n            has_client_secret=self.client_secret_encrypted is not None,\\n        )\\n        return self\\n\\n    @field_validator(\\\"slug\\\")\\n    @classmethod\\n    def validate_slug_field(cls, value: str) -> str:\\n        if not _SSO_SLUG_PATTERN.fullmatch(value):\\n            msg = \\\"SSOConfig.slug must contain only lowercase letters, numbers, and single hyphens\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @field_validator(\\\"client_secret_encrypted\\\")\\n    @classmethod\\n    def validate_client_secret_field(cls, value: str | None) -> str | None:\\n        if value is not None and not is_sso_client_secret_envelope(value):\\n            msg = \\\"client_secret_encrypted must be a versioned SSO secret envelope\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @validates(\\\"slug\\\")\\n    def validate_slug_assignment(self, _key: str, value: str) -> str:\\n        \\\"\\\"\\\"Reject invalid slugs assigned before the first insert.\\\"\\\"\\\"\\n        if not _SSO_SLUG_PATTERN.fullmatch(value):\\n            msg = \\\"SSOConfig.slug must contain only lowercase letters, numbers, and single hyphens\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @validates(\\\"protocol\\\")\\n    def validate_protocol(self, _key: str, value: str) -> str:\\n        \\\"\\\"\\\"Keep protocol aligned with provider_settings on attribute assignment.\\\"\\\"\\\"\\n        # Use __dict__ so we do not assume the counterpart is loaded yet (e.g. DB hydrate).\\n        if not self.__dict__.get(_VALIDATED_UPDATE_FLAG) and \\\"provider_settings\\\" in self.__dict__:\\n            _validate_provider_settings(value, self.__dict__[\\\"provider_settings\\\"])\\n        return value\\n\\n    @validates(\\\"provider_settings\\\")\\n    def validate_provider_settings(\\n        self,\\n        _key: str,\\n        value: SSOProviderSettings | dict[str, Any],\\n    ) -> SSOProviderSettings:\\n        \\\"\\\"\\\"Keep provider_settings aligned with protocol on attribute assignment.\\\"\\\"\\\"\\n        if not self.__dict__.get(_VALIDATED_UPDATE_FLAG) and \\\"protocol\\\" in self.__dict__:\\n            return _validate_provider_settings(self.__dict__[\\\"protocol\\\"], value)\\n        return _PROVIDER_SETTINGS_ADAPTER.validate_python(value)\\n\\n    @validates(\\\"client_secret_encrypted\\\")\\n    def validate_client_secret_envelope(self, _key: str, value: str | None) -> str | None:\\n        \\\"\\\"\\\"Reject plaintext or malformed client secrets on model writes.\\\"\\\"\\\"\\n        if value is not None and not is_sso_client_secret_envelope(value):\\n            msg = \\\"client_secret_encrypted must be a versioned SSO secret envelope\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @validates(\\\"enabled\\\")\\n    def validate_enabled_assignment(self, _key: str, value: bool) -> bool:  # noqa: FBT001\\n        \\\"\\\"\\\"Fail closed when an existing configuration is enabled by assignment.\\\"\\\"\\\"\\n        provider_settings = self.__dict__.get(\\\"provider_settings\\\")\\n        if value and provider_settings is not None and not self.__dict__.get(_VALIDATED_UPDATE_FLAG):\\n            _validate_enabled_config(\\n                provider_settings,\\n                enabled=True,\\n                has_client_secret=self.__dict__.get(\\\"client_secret_encrypted\\\") is not None,\\n            )\\n        return value\\n\\n\\ndef _nonblank_json_string(json_column: sa.Column[Any], key: str) -> sa.ColumnElement[bool]:\\n    value = json_column[key].as_string()\\n    return sa.and_(value.is_not(None), sa.func.length(sa.func.trim(value)) > 0)\\n\\n\\ndef _http_json_url_or_null(json_column: sa.Column[Any], key: str) -> sa.ColumnElement[bool]:\\n    value = json_column[key].as_string()\\n    normalized = sa.func.lower(value)\\n    no_whitespace = sa.and_(\\n        *(sa.func.length(value) == sa.func.length(sa.func.replace(value, character, \\\"\\\")) for character in \\\" \\\\t\\\\r\\\\n\\\")\\n    )\\n    http_url = sa.and_(\\n        normalized.like(\\\"http://%\\\"),\\n        sa.func.length(value) > len(\\\"http://\\\"),\\n        sa.func.substr(value, len(\\\"http://\\\") + 1, 1).not_in((\\\"/\\\", \\\"\\\\\\\\\\\", \\\"?\\\", \\\"#\\\", \\\":\\\")),\\n        no_whitespace,\\n    )\\n    https_url = sa.and_(\\n        normalized.like(\\\"https://%\\\"),\\n        sa.func.length(value) > len(\\\"https://\\\"),\\n        sa.func.substr(value, len(\\\"https://\\\") + 1, 1).not_in((\\\"/\\\", \\\"\\\\\\\\\\\", \\\"?\\\", \\\"#\\\", \\\":\\\")),\\n        no_whitespace,\\n    )\\n    return sa.or_(value.is_(None), http_url, https_url)\\n\\n\\ndef _client_secret_envelope_or_null(value: sa.Column[Any]) -> sa.ColumnElement[bool]:\\n    string_value = sa.type_coerce(value, sa.String())\\n    separator_position = len(_SSO_SECRET_ENVELOPE_HEADER) + _SSO_SECRET_NONCE_LENGTH + 1\\n    minimum_length = separator_position + _SSO_SECRET_MIN_CIPHERTEXT_LENGTH\\n    return sa.or_(\\n        value.is_(None),\\n        sa.and_(\\n            sa.func.substr(string_value, 1, len(_SSO_SECRET_ENVELOPE_HEADER)) == _SSO_SECRET_ENVELOPE_HEADER,\\n            sa.func.substr(string_value, separator_position, 1) == \\\":\\\",\\n            sa.func.length(string_value) >= minimum_length,\\n        ),\\n    )\\n\\n\\ndef _install_sso_config_database_invariants() -> None:\\n    \\\"\\\"\\\"Install portable checks and dialect-specific slug immutability triggers.\\\"\\\"\\\"\\n    table = SSOConfig.__table__\\n    provider_settings = table.c.provider_settings\\n    protocol = table.c.protocol\\n    enabled = table.c.enabled\\n\\n    # conv() marks these as final names so alembic's ck_%(table_name)s_%(constraint_name)s\\n    # convention (applied in alembic/env.py) does not double-prefix them.\\n    table.append_constraint(\\n        CheckConstraint(\\n            sa.and_(\\n                protocol.in_((\\\"oidc\\\", \\\"saml\\\", \\\"ldap\\\")),\\n                provider_settings[\\\"protocol\\\"].as_string().is_not(None),\\n                provider_settings[\\\"protocol\\\"].as_string() == protocol,\\n            ),\\n            name=conv(\\\"ck_sso_config_protocol_consistency\\\"),\\n        )\\n    )\\n    table.append_constraint(\\n        CheckConstraint(\\n            sa.or_(\\n                enabled.is_(False),\\n                protocol.in_((\\\"saml\\\", \\\"ldap\\\")),\\n                sa.and_(\\n                    protocol == \\\"oidc\\\",\\n                    table.c.client_secret_encrypted.is_not(None),\\n                    _nonblank_json_string(provider_settings, \\\"client_id\\\"),\\n                    sa.or_(\\n                        _nonblank_json_string(provider_settings, \\\"discovery_url\\\"),\\n                        sa.and_(\\n                            _nonblank_json_string(provider_settings, \\\"authorization_endpoint\\\"),\\n                            _nonblank_json_string(provider_settings, \\\"token_endpoint\\\"),\\n                            _nonblank_json_string(provider_settings, \\\"jwks_uri\\\"),\\n                        ),\\n                    ),\\n                    *(_http_json_url_or_null(provider_settings, key) for key in _OIDC_REMOTE_URL_FIELDS),\\n                ),\\n            ),\\n            name=conv(\\\"ck_sso_config_enabled_complete\\\"),\\n        )\\n    )\\n    table.append_constraint(\\n        CheckConstraint(\\n            _client_secret_envelope_or_null(table.c.client_secret_encrypted),\\n            name=conv(\\\"ck_sso_config_client_secret_envelope\\\"),\\n        )\\n    )\\n\\n    sqlite_trigger = sa.DDL(\\n        \\\"\\\"\\\"\\n        CREATE TRIGGER trg_sso_config_slug_immutable\\n        BEFORE UPDATE OF slug ON sso_config\\n        FOR EACH ROW\\n        WHEN OLD.slug IS NOT NULL AND NEW.slug IS NOT OLD.slug\\n        BEGIN\\n            SELECT RAISE(ABORT, 'SSOConfig.slug is immutable after insert');\\n        END\\n        \\\"\\\"\\\"\\n    ).execute_if(dialect=\\\"sqlite\\\")\\n    postgres_trigger_function = sa.DDL(\\n        \\\"\\\"\\\"\\n        CREATE OR REPLACE FUNCTION prevent_sso_config_slug_update()\\n        RETURNS trigger AS $$\\n        BEGIN\\n            IF OLD.slug IS NOT NULL AND NEW.slug IS DISTINCT FROM OLD.slug THEN\\n                RAISE EXCEPTION 'SSOConfig.slug is immutable after insert';\\n            END IF;\\n            RETURN NEW;\\n        END;\\n        $$ LANGUAGE plpgsql\\n        \\\"\\\"\\\"\\n    ).execute_if(dialect=\\\"postgresql\\\")\\n    postgres_trigger = sa.DDL(\\n        \\\"\\\"\\\"\\n        CREATE TRIGGER trg_sso_config_slug_immutable\\n        BEFORE UPDATE OF slug ON sso_config\\n        FOR EACH ROW EXECUTE FUNCTION prevent_sso_config_slug_update()\\n        \\\"\\\"\\\"\\n    ).execute_if(dialect=\\\"postgresql\\\")\\n    drop_postgres_function = sa.DDL(\\\"DROP FUNCTION IF EXISTS prevent_sso_config_slug_update()\\\").execute_if(\\n        dialect=\\\"postgresql\\\"\\n    )\\n    sa.event.listen(table, \\\"after_create\\\", sqlite_trigger)\\n    sa.event.listen(table, \\\"after_create\\\", postgres_trigger_function)\\n    sa.event.listen(table, \\\"after_create\\\", postgres_trigger)\\n    sa.event.listen(table, \\\"after_drop\\\", drop_postgres_function)\\n\\n\\n_install_sso_config_database_invariants()\\n\\n\\nclass SSOConfigCreate(SQLModel):\\n    \\\"\\\"\\\"Validated external input for creating an SSO configuration.\\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"forbid\\\")\\n\\n    display_name: str\\n    protocol: Literal[\\\"oidc\\\"] = \\\"oidc\\\"\\n    enabled: bool = False\\n    sort_order: int = 0\\n    client_secret: SecretStr | None = Field(default=None, exclude=True, repr=False)\\n    provider_settings: SSOProviderSettings = Field(default_factory=OIDCProviderSettings)\\n    email_claim: str = \\\"email\\\"\\n    username_claim: str = \\\"preferred_username\\\"\\n    user_id_claim: str = \\\"sub\\\"\\n\\n    @field_validator(\\\"client_secret\\\")\\n    @classmethod\\n    def validate_client_secret(cls, value: SecretStr | None) -> SecretStr | None:\\n        if value is not None and not value.get_secret_value().strip():\\n            msg = \\\"SSO client secret must not be blank\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_configuration(self) -> Self:\\n        provider_settings = _validate_provider_settings(self.protocol, self.provider_settings)\\n        _validate_enabled_config(\\n            provider_settings,\\n            enabled=self.enabled,\\n            has_client_secret=self.client_secret is not None,\\n        )\\n        return self\\n\\n    def to_model(\\n        self,\\n        settings_service: Any | None = None,\\n        *,\\n        actor_id: UUIDstr | None = None,\\n    ) -> SSOConfig:\\n        \\\"\\\"\\\"Build the persistence model, encrypting plaintext before it reaches the table.\\\"\\\"\\\"\\n        from langflow.services.database.models.auth.sso_secret import encrypt_sso_client_secret\\n\\n        values = self.model_dump(exclude={\\\"client_secret\\\"})\\n        if self.client_secret is not None:\\n            values[\\\"client_secret_encrypted\\\"] = encrypt_sso_client_secret(\\n                self.client_secret.get_secret_value(),\\n                settings_service,\\n            )\\n        values[\\\"created_by\\\"] = actor_id\\n        values[\\\"updated_by\\\"] = actor_id\\n        return SSOConfig(**values)\\n\\n\\nclass SSOConfigRead(SQLModel):\\n    \\\"\\\"\\\"Secret-free representation of a persisted SSO configuration.\\\"\\\"\\\"\\n\\n    model_config = ConfigDict(from_attributes=True)\\n\\n    id: UUIDstr\\n    slug: str\\n    display_name: str\\n    protocol: str\\n    enabled: bool\\n    sort_order: int\\n    provider_settings: SSOProviderSettings\\n    email_claim: str\\n    username_claim: str\\n    user_id_claim: str\\n    created_at: datetime\\n    updated_at: datetime\\n    created_by: UUIDstr | None\\n    updated_by: UUIDstr | None\\n\\n\\nclass SSOConfigUpdate(SQLModel):\\n    \\\"\\\"\\\"Validated partial update input for an SSO configuration.\\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"forbid\\\")\\n\\n    display_name: str | None = None\\n    protocol: Literal[\\\"oidc\\\"] | None = None\\n    enabled: bool | None = None\\n    sort_order: int | None = None\\n    client_secret: SecretStr | None = Field(default=None, exclude=True, repr=False)\\n    provider_settings: SSOProviderSettings | None = None\\n    email_claim: str | None = None\\n    username_claim: str | None = None\\n    user_id_claim: str | None = None\\n\\n    @field_validator(\\\"client_secret\\\")\\n    @classmethod\\n    def validate_client_secret(cls, value: SecretStr | None) -> SecretStr | None:\\n        if value is not None and not value.get_secret_value().strip():\\n            msg = \\\"SSO client secret must not be blank\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    def apply_to(\\n        self,\\n        config: SSOConfig,\\n        settings_service: Any | None = None,\\n        *,\\n        actor_id: UUIDstr | None = None,\\n    ) -> SSOConfig:\\n        \\\"\\\"\\\"Validate the merged state and apply this update to a persistence model.\\\"\\\"\\\"\\n        from langflow.services.database.models.auth.sso_secret import encrypt_sso_client_secret\\n\\n        values = self.model_dump(exclude_unset=True, exclude={\\\"client_secret\\\"})\\n        if \\\"provider_settings\\\" in self.model_fields_set:\\n            values[\\\"provider_settings\\\"] = self.provider_settings\\n        required_fields = {\\n            \\\"display_name\\\",\\n            \\\"protocol\\\",\\n            \\\"enabled\\\",\\n            \\\"sort_order\\\",\\n            \\\"provider_settings\\\",\\n            \\\"email_claim\\\",\\n            \\\"username_claim\\\",\\n            \\\"user_id_claim\\\",\\n        }\\n        null_fields = sorted(field for field in required_fields if field in values and values[field] is None)\\n        if null_fields:\\n            msg = f\\\"SSO configuration fields cannot be null: {', '.join(null_fields)}\\\"\\n            raise ValueError(msg)\\n\\n        protocol = values.get(\\\"protocol\\\", config.protocol)\\n        provider_settings = _validate_provider_settings(\\n            protocol,\\n            values.get(\\\"provider_settings\\\", config.provider_settings),\\n        )\\n        enabled = values.get(\\\"enabled\\\", config.enabled)\\n\\n        encrypted_secret = config.client_secret_encrypted\\n        if \\\"client_secret\\\" in self.model_fields_set:\\n            encrypted_secret = (\\n                encrypt_sso_client_secret(self.client_secret.get_secret_value(), settings_service)\\n                if self.client_secret is not None\\n                else None\\n            )\\n        _validate_enabled_config(\\n            provider_settings,\\n            enabled=enabled,\\n            has_client_secret=encrypted_secret is not None,\\n        )\\n\\n        # Apply dependencies before ``enabled`` so assignment-time validation\\n        # observes the already-validated merged state instead of the old,\\n        # potentially incomplete configuration.\\n        enabled_was_set = \\\"enabled\\\" in values\\n        enabled_value = values.pop(\\\"enabled\\\") if enabled_was_set else config.enabled\\n        config.__dict__[_VALIDATED_UPDATE_FLAG] = True\\n        try:\\n            for field_name, value in values.items():\\n                setattr(config, field_name, value)\\n            if \\\"client_secret\\\" in self.model_fields_set:\\n                config.client_secret_encrypted = encrypted_secret\\n            if enabled_was_set:\\n                config.enabled = enabled_value\\n        finally:\\n            config.__dict__.pop(_VALIDATED_UPDATE_FLAG, None)\\n\\n        # Assert the persisted object matches the state validated above; the\\n        # before-update hook repeats this check at flush time as defense in depth.\\n        _validate_enabled_config(\\n            _validate_provider_settings(config.protocol, config.provider_settings),\\n            enabled=config.enabled,\\n            has_client_secret=config.client_secret_encrypted is not None,\\n        )\\n        if actor_id is not None:\\n            config.updated_by = actor_id\\n        return config\\n\\n\\nclass SSOSettings(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Singleton instance-level SSO policy settings.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"sso_settings\\\"\\n    __table_args__ = (CheckConstraint(\\\"id = 1\\\", name=conv(\\\"ck_sso_settings_singleton\\\")),)\\n\\n    id: int = Field(default=1, primary_key=True)\\n    enforce_sso: bool = Field(default=False)\\n\\n\\n@sa.event.listens_for(SSOConfig, \\\"before_update\\\")\\ndef _prevent_sso_config_slug_update(\\n    _mapper: sa.orm.Mapper[SSOConfig],\\n    _connection: sa.Connection,\\n    target: SSOConfig,\\n) -> None:\\n    \\\"\\\"\\\"Keep the connection identifier immutable after persistence.\\\"\\\"\\\"\\n    if sa.inspect(target).attrs.slug.history.has_changes():\\n        msg = \\\"SSOConfig.slug is immutable after insert\\\"\\n        raise ValueError(msg)\\n    _validate_enabled_config(\\n        _validate_provider_settings(target.protocol, target.provider_settings),\\n        enabled=target.enabled,\\n        has_client_secret=target.client_secret_encrypted is not None,\\n    )\\n\\n\\n@sa.event.listens_for(SSOConfig, \\\"before_insert\\\")\\ndef _validate_sso_config_before_insert(\\n    _mapper: sa.orm.Mapper[SSOConfig],\\n    _connection: sa.Connection,\\n    target: SSOConfig,\\n) -> None:\\n    \\\"\\\"\\\"Validate cross-column invariants before ORM inserts.\\\"\\\"\\\"\\n    _validate_enabled_config(\\n        _validate_provider_settings(target.protocol, target.provider_settings),\\n        enabled=target.enabled,\\n        has_client_secret=target.client_secret_encrypted is not None,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/auth/sso_secret.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"22b80b2033f6105aca57cb5e008649ac030ff567fd2521f16f4927779bae0738\",\"content\":\"\\\"\\\"\\\"Versioned at-rest encryption contract for SSO client secrets.\\n\\nThe ``sso_config.client_secret_encrypted`` column stores only envelopes emitted\\nby :func:`encrypt_sso_client_secret`; SSO read paths must never serialize or\\notherwise return that column.\\n\\nEnvelope v1 is::\\n\\n    lf-sso:v1:hkdf-sha256-v1:aes-256-gcm:<nonce-b64url>:<ciphertext-b64url>\\n\\n``ciphertext`` includes the 128-bit GCM authentication tag. The 256-bit AES key\\nis derived from the existing ``LANGFLOW_SECRET_KEY`` (``AuthSettings.SECRET_KEY``)\\nwith HKDF-SHA256, a fixed domain-separation salt, and the distinct\\n``langflow/sso/client-secret/encryption`` info label. No additional setting or\\nenvironment variable is required.\\n\\nKey/format rotation procedure:\\n\\n1. Add a new envelope/KDF version while retaining decryption support for v1.\\n2. Re-encrypt every non-null column value internally, using the old version to\\n   decrypt and the new version to encrypt. Never expose plaintext through a read\\n   response or log.\\n3. Verify no old-version envelopes remain, then remove the old decryptor in a\\n   later release. A future KMS-backed key therefore changes envelope handling,\\n   not the database schema.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nimport binascii\\nimport os\\nfrom typing import TYPE_CHECKING\\n\\nfrom cryptography.exceptions import InvalidTag\\nfrom cryptography.hazmat.primitives import hashes\\nfrom cryptography.hazmat.primitives.ciphers.aead import AESGCM\\nfrom cryptography.hazmat.primitives.kdf.hkdf import HKDF\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n_ENVELOPE_VERSION = \\\"v1\\\"\\n_KDF_VERSION = \\\"hkdf-sha256-v1\\\"\\n_ALGORITHM = \\\"aes-256-gcm\\\"\\n_PREFIX = \\\"lf-sso\\\"\\n_HEADER = f\\\"{_PREFIX}:{_ENVELOPE_VERSION}:{_KDF_VERSION}:{_ALGORITHM}\\\"\\n_AAD = _HEADER.encode()\\n_HKDF_SALT = b\\\"langflow/sso/client-secret/hkdf-salt/v1\\\"\\n_HKDF_INFO = b\\\"langflow/sso/client-secret/encryption\\\"\\n_NONCE_BYTES = 12\\n_TAG_BYTES = 16\\n_ENVELOPE_PARTS = 6\\n_HEADER_PARTS = 4\\n_BASE64URL_ALPHABET = frozenset(\\\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_\\\")\\n\\n\\nclass SSOSecretError(ValueError):\\n    \\\"\\\"\\\"Raised when an SSO secret cannot be encoded or decoded safely.\\\"\\\"\\\"\\n\\n\\ndef _master_key(settings_service: SettingsService | None) -> bytes:\\n    if settings_service is None:\\n        from langflow.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n\\n    secret_key = settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n    if not secret_key:\\n        msg = \\\"LANGFLOW_SECRET_KEY is required for SSO secret encryption\\\"\\n        raise SSOSecretError(msg)\\n    return secret_key.encode()\\n\\n\\ndef _derive_key(settings_service: SettingsService | None) -> bytes:\\n    return HKDF(\\n        algorithm=hashes.SHA256(),\\n        length=32,\\n        salt=_HKDF_SALT,\\n        info=_HKDF_INFO,\\n    ).derive(_master_key(settings_service))\\n\\n\\ndef _encode(value: bytes) -> str:\\n    return base64.urlsafe_b64encode(value).rstrip(b\\\"=\\\").decode()\\n\\n\\ndef _decode(value: str) -> bytes:\\n    if not value or any(character not in _BASE64URL_ALPHABET for character in value):\\n        msg = \\\"Invalid base64url data in SSO secret envelope\\\"\\n        raise SSOSecretError(msg)\\n    padding = \\\"=\\\" * (-len(value) % 4)\\n    try:\\n        return base64.b64decode(value + padding, altchars=b\\\"-_\\\", validate=True)\\n    except (binascii.Error, ValueError) as exc:\\n        msg = \\\"Invalid base64url data in SSO secret envelope\\\"\\n        raise SSOSecretError(msg) from exc\\n\\n\\ndef _parse_envelope(envelope: str) -> tuple[bytes, bytes]:\\n    parts = envelope.split(\\\":\\\")\\n    if len(parts) != _ENVELOPE_PARTS or \\\":\\\".join(parts[:_HEADER_PARTS]) != _HEADER:\\n        msg = \\\"Unsupported SSO client-secret envelope or key-derivation version\\\"\\n        raise SSOSecretError(msg)\\n\\n    nonce = _decode(parts[4])\\n    ciphertext = _decode(parts[5])\\n    if len(nonce) != _NONCE_BYTES or len(ciphertext) < _TAG_BYTES:\\n        msg = \\\"Invalid SSO client-secret envelope payload\\\"\\n        raise SSOSecretError(msg)\\n    return nonce, ciphertext\\n\\n\\ndef is_sso_client_secret_envelope(value: object) -> bool:\\n    \\\"\\\"\\\"Return whether a value is a structurally valid current-version envelope.\\\"\\\"\\\"\\n    if not isinstance(value, str):\\n        return False\\n    try:\\n        _parse_envelope(value)\\n    except SSOSecretError:\\n        return False\\n    return True\\n\\n\\ndef encrypt_sso_client_secret(\\n    client_secret: str,\\n    settings_service: SettingsService | None = None,\\n) -> str:\\n    \\\"\\\"\\\"Encrypt an SSO client secret into the current versioned envelope.\\\"\\\"\\\"\\n    if not isinstance(client_secret, str):\\n        msg = \\\"SSO client secret must be a string\\\"\\n        raise TypeError(msg)\\n    if not client_secret.strip():\\n        msg = \\\"SSO client secret must not be blank\\\"\\n        raise SSOSecretError(msg)\\n\\n    nonce = os.urandom(_NONCE_BYTES)\\n    ciphertext = AESGCM(_derive_key(settings_service)).encrypt(nonce, client_secret.encode(), _AAD)\\n    return f\\\"{_HEADER}:{_encode(nonce)}:{_encode(ciphertext)}\\\"\\n\\n\\ndef decrypt_sso_client_secret(\\n    envelope: str,\\n    settings_service: SettingsService | None = None,\\n) -> str:\\n    \\\"\\\"\\\"Decrypt a supported SSO client-secret envelope.\\\"\\\"\\\"\\n    if not isinstance(envelope, str):\\n        msg = \\\"SSO client-secret envelope must be a string\\\"\\n        raise TypeError(msg)\\n\\n    nonce, ciphertext = _parse_envelope(envelope)\\n\\n    try:\\n        plaintext = AESGCM(_derive_key(settings_service)).decrypt(nonce, ciphertext, _AAD)\\n    except InvalidTag as exc:\\n        msg = \\\"Unable to decrypt SSO client secret with LANGFLOW_SECRET_KEY\\\"\\n        raise SSOSecretError(msg) from exc\\n\\n    try:\\n        return plaintext.decode()\\n    except UnicodeDecodeError as exc:\\n        msg = \\\"Decrypted SSO client secret is not valid UTF-8\\\"\\n        raise SSOSecretError(msg) from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"05f4a58ad65729ae759c6882e04502944191f778c810b9a04958ca468ea1ef39\",\"content\":\"import orjson\\n\\n\\ndef orjson_dumps(v, *, default=None, sort_keys=False, indent_2=True):\\n    option = orjson.OPT_SORT_KEYS if sort_keys else None\\n    if indent_2:\\n        # orjson.dumps returns bytes, to match standard json.dumps we need to decode\\n        # option\\n        # To modify how data is serialized, specify option. Each option is an integer constant in orjson.\\n        # To specify multiple options, mask them together, e.g., option=orjson.OPT_STRICT_INTEGER | orjson.OPT_NAIVE_UTC\\n        if option is None:\\n            option = orjson.OPT_INDENT_2\\n        else:\\n            option |= orjson.OPT_INDENT_2\\n    if default is None:\\n        return orjson.dumps(v, option=option).decode()\\n    return orjson.dumps(v, default=default, option=option).decode()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/catalog_policy/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"99f69bdf0cd660eb5ab84dedb710d2b288763002e10b39f0753bb9a4a73e9c2f\",\"content\":\"from .model import CatalogPolicyMode, CatalogPolicyRule, CatalogPolicyScope, CatalogResourceKind\\n\\n__all__ = [\\n    \\\"CatalogPolicyMode\\\",\\n    \\\"CatalogPolicyRule\\\",\\n    \\\"CatalogPolicyScope\\\",\\n    \\\"CatalogResourceKind\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/catalog_policy/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ec00287ad33a6d0940f779da9ac4ae54000c931035dd3ca9143564d041ad12ea\",\"content\":\"\\\"\\\"\\\"Catalog-governance policy storage.\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom uuid import uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import CheckConstraint, Column, ForeignKey, Index, text\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\nfrom sqlmodel.sql.sqltypes import AutoString\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\n\\nclass CatalogResourceKind(str, Enum):\\n    \\\"\\\"\\\"Kinds of catalog resources that can be governed.\\\"\\\"\\\"\\n\\n    COMPONENT = \\\"component\\\"\\n    TEMPLATE = \\\"template\\\"\\n\\n\\nclass CatalogPolicyMode(str, Enum):\\n    \\\"\\\"\\\"Catalog policy modes.\\n\\n    P1 reads and writes only ``BLOCK`` rules. ``ALLOW`` is a schema reservation\\n    for a future allowlist phase and has no P1 resolution semantics.\\n    \\\"\\\"\\\"\\n\\n    BLOCK = \\\"block\\\"\\n    ALLOW = \\\"allow\\\"\\n\\n\\nclass CatalogPolicyScope(str, Enum):\\n    \\\"\\\"\\\"Policy scopes.\\n\\n    P1 reads and writes only ``GLOBAL`` rules. Organization and workspace\\n    values reserve the existing authorization domain shape for a later\\n    scoped-policy phase and have no P1 resolution semantics.\\n    \\\"\\\"\\\"\\n\\n    GLOBAL = \\\"global\\\"\\n    ORG = \\\"org\\\"\\n    WORKSPACE = \\\"workspace\\\"\\n\\n\\ndef _enum_values_sql(enum_type: type[Enum]) -> str:\\n    \\\"\\\"\\\"Return safely quoted SQL literals for a closed internal string enum.\\\"\\\"\\\"\\n    return \\\", \\\".join(f\\\"'{member.value}'\\\" for member in enum_type)\\n\\n\\n_RESOURCE_KIND_CHECK = f\\\"resource_kind IN ({_enum_values_sql(CatalogResourceKind)})\\\"\\n_MODE_CHECK = f\\\"mode IN ({_enum_values_sql(CatalogPolicyMode)})\\\"\\n_SCOPE_CHECK = f\\\"scope IN ({_enum_values_sql(CatalogPolicyScope)})\\\"\\n_SCOPED_VALUES_SQL = \\\", \\\".join(f\\\"'{scope.value}'\\\" for scope in (CatalogPolicyScope.ORG, CatalogPolicyScope.WORKSPACE))\\n_SCOPE_DOMAIN_CHECK = (\\n    f\\\"(scope = '{CatalogPolicyScope.GLOBAL.value}' AND domain_id IS NULL) \\\"\\n    f\\\"OR (scope IN ({_SCOPED_VALUES_SQL}) AND domain_id IS NOT NULL)\\\"\\n)\\n\\n\\ndef _tz_aware_now() -> datetime:\\n    \\\"\\\"\\\"Return the current UTC timestamp for in-memory model defaults.\\\"\\\"\\\"\\n    return datetime.now(timezone.utc)\\n\\n\\nclass CatalogPolicyRule(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"A catalog rule keyed by an exact, case-sensitive resource identifier.\\n\\n    The P1 service considers only global block rules; reserved allow/scoped rows\\n    are ignored until a future phase defines their resolution semantics. The\\n    unique indexes prevent contradictory modes for the same resource and\\n    domain, while intentionally allowing distinct resources in one scope.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"catalog_policy_rule\\\"\\n    __table_args__ = (\\n        CheckConstraint(\\n            _RESOURCE_KIND_CHECK,\\n            name=conv(\\\"ck_catalog_policy_rule_resource_kind\\\"),\\n        ),\\n        CheckConstraint(\\n            _MODE_CHECK,\\n            name=conv(\\\"ck_catalog_policy_rule_mode\\\"),\\n        ),\\n        CheckConstraint(\\n            _SCOPE_CHECK,\\n            name=conv(\\\"ck_catalog_policy_rule_scope\\\"),\\n        ),\\n        CheckConstraint(\\n            _SCOPE_DOMAIN_CHECK,\\n            name=conv(\\\"ck_catalog_policy_rule_scope_domain_consistency\\\"),\\n        ),\\n        Index(\\n            \\\"uq_catalog_policy_rule_scoped\\\",\\n            \\\"resource_kind\\\",\\n            \\\"resource_key\\\",\\n            \\\"scope\\\",\\n            \\\"domain_id\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"domain_id IS NOT NULL\\\"),\\n            sqlite_where=text(\\\"domain_id IS NOT NULL\\\"),\\n        ),\\n        Index(\\n            \\\"uq_catalog_policy_rule_unscoped\\\",\\n            \\\"resource_kind\\\",\\n            \\\"resource_key\\\",\\n            \\\"scope\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"domain_id IS NULL\\\"),\\n            sqlite_where=text(\\\"domain_id IS NULL\\\"),\\n        ),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    resource_kind: str\\n    resource_key: str\\n    mode: str = Field(\\n        default=CatalogPolicyMode.BLOCK.value,\\n        sa_column=Column(AutoString(), nullable=False, server_default=sa.text(\\\"'block'\\\")),\\n    )\\n    scope: str = Field(\\n        default=CatalogPolicyScope.GLOBAL.value,\\n        sa_column=Column(AutoString(), nullable=False, server_default=sa.text(\\\"'global'\\\")),\\n    )\\n    domain_id: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), nullable=True),\\n    )\\n    created_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n    created_at: datetime = Field(\\n        default_factory=_tz_aware_now,\\n        sa_column=Column(sa.DateTime(timezone=True), nullable=False, server_default=sa.func.now()),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=_tz_aware_now,\\n        sa_column=Column(\\n            sa.DateTime(timezone=True),\\n            nullable=False,\\n            server_default=sa.func.now(),\\n            onupdate=sa.func.now(),\\n        ),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3a5fa8259c102a8ed875ffb566def5bcc5facac98e7f7f081c4fda52d7836e2\",\"content\":\"from .model import Deployment, DeploymentRead\\n\\n__all__ = [\\\"Deployment\\\", \\\"DeploymentRead\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3399c7b9c413a23e6e61f8ff925f1060dffd12a4f27625711539e2242fba8d3a\",\"content\":\"from __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any, TypeVar\\n\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy import Select, column, values\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import col, delete, func, select, update\\n\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_deployment_immutable_fields\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.database.utils import parse_uuid\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n    from uuid import UUID\\n\\n    from lfx.services.adapters.deployment.schema import DeploymentType\\n    from lfx.services.authorization.base import ResourceVisibilityScope\\n    from sqlalchemy.sql.selectable import CTE\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nclass UnconfirmedDeleteRowcount:\\n    \\\"\\\"\\\"Sentinel returned when a DELETE's affected-row count cannot be confirmed.\\n\\n    Identity-compare with ``is UNCONFIRMED_DELETE_ROWCOUNT``. Distinct from\\n    ``0`` (driver reported that zero rows matched).\\n\\n    Emitted when ``result.rowcount`` is not a non-negative ``int``:\\n\\n    * ``-1`` \u2014 PEP 249 / SQLAlchemy signal that rowcount could not be\\n      determined (e.g. some RETURNING / executemany shapes).\\n    * ``None`` \u2014 same undetermined-rowcount meaning (PEP 249 also allows\\n      ``None`` instead of ``-1``). Also seen from test doubles that leave the\\n      attribute unset. SQLAlchemy's ``CursorResult.rowcount`` is typed as\\n      ``int`` and documents ``-1``.\\n    \\\"\\\"\\\"\\n\\n\\nUNCONFIRMED_DELETE_ROWCOUNT = UnconfirmedDeleteRowcount()\\n\\n\\nasync def _interpret_delete_rowcount(delete_rowcount: object, *, context: str) -> int | UnconfirmedDeleteRowcount:\\n    \\\"\\\"\\\"Return a confirmed non-negative rowcount, or ``UNCONFIRMED_DELETE_ROWCOUNT``.\\\"\\\"\\\"\\n    if not isinstance(delete_rowcount, int) or delete_rowcount < 0:\\n        await logger.aerror(\\n            \\\"DELETE rowcount unconfirmed (%r, %s) \u2014 expected a non-negative int; \\\"\\n            \\\"PEP 249 uses -1 (or None) when rowcount cannot be determined\\\",\\n            delete_rowcount,\\n            context,\\n        )\\n        return UNCONFIRMED_DELETE_ROWCOUNT\\n    return delete_rowcount\\n\\n\\n# Preserves the concrete statement type (scalar count select vs. multi-column\\n# page select) through the authz scoping helper below.\\nStmtT = TypeVar(\\\"StmtT\\\", bound=Select[Any])\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass DeploymentMetadataUpdate:\\n    langflow_db_row: Deployment\\n    display_name: str\\n    description: str | None\\n\\n    def __post_init__(self) -> None:\\n        _raise_if_blank(self.display_name, \\\"display_name\\\")\\n\\n\\ndef _raise_if_blank(value: str, field_name: str) -> str:\\n    \\\"\\\"\\\"Return *value* unchanged, or raise if it is blank.\\\"\\\"\\\"\\n    if not value.strip():\\n        msg = f\\\"{field_name} must not be empty\\\"\\n        raise ValueError(msg)\\n    return value\\n\\n\\ndef _strip_or_raise(value: str, field_name: str) -> str:\\n    \\\"\\\"\\\"Return *value* stripped of whitespace, or raise if blank.\\\"\\\"\\\"\\n    stripped = value.strip()\\n    if not stripped:\\n        msg = f\\\"{field_name} must not be empty\\\"\\n        raise ValueError(msg)\\n    return stripped\\n\\n\\nasync def create_deployment(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    project_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    resource_key: str,\\n    deployment_type: DeploymentType,\\n    display_name: str,\\n    description: str | None = None,\\n) -> Deployment:\\n    resource_key_s = _strip_or_raise(resource_key, \\\"resource_key\\\")\\n    display_name_s = _raise_if_blank(display_name, \\\"display_name\\\")\\n\\n    row = Deployment(\\n        user_id=user_id,\\n        project_id=project_id,\\n        deployment_provider_account_id=deployment_provider_account_id,\\n        resource_key=resource_key_s,\\n        display_name=display_name_s,\\n        deployment_type=deployment_type,\\n        description=description,\\n    )\\n    db.add(row)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        await db.rollback()\\n        await logger.aerror(\\\"IntegrityError creating deployment: %s\\\", exc)\\n        msg = (\\n            \\\"Deployment conflicts with an existing record \\\"\\n            f\\\"(resource_key={resource_key!r}, display_name={display_name_s!r})\\\"\\n        )\\n        raise ValueError(msg) from exc\\n    await db.refresh(row)\\n    return row\\n\\n\\nasync def create_deployment_from_model(\\n    db: AsyncSession,\\n    *,\\n    deployment: Deployment,\\n) -> Deployment:\\n    return await create_deployment(\\n        db,\\n        user_id=deployment.user_id,\\n        project_id=deployment.project_id,\\n        deployment_provider_account_id=deployment.deployment_provider_account_id,\\n        resource_key=deployment.resource_key,\\n        display_name=deployment.display_name,\\n        deployment_type=deployment.deployment_type,\\n        description=deployment.description,\\n    )\\n\\n\\nasync def get_deployment_by_resource_key(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    resource_key: str,\\n) -> Deployment | None:\\n    stmt = select(Deployment).where(\\n        Deployment.user_id == user_id,\\n        Deployment.deployment_provider_account_id == deployment_provider_account_id,\\n        Deployment.resource_key == resource_key.strip(),\\n    )\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def get_deployment(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID | str,\\n) -> Deployment | None:\\n    \\\"\\\"\\\"Load a deployment by id, with share-aware fetch when supported.\\n\\n    When the registered authorization service supports cross-user fetch\\n    (authorization plugin), the deployment is loaded by id alone and the route's\\n    ``ensure_deployment_permission`` decides whether the caller may see it.\\n    Otherwise the query stays owner-scoped so the OSS pass-through default\\n    cannot widen visibility.\\n    \\\"\\\"\\\"\\n    from langflow.services.authorization.fetch import authorized_or_owner_scoped\\n\\n    deployment_uuid = parse_uuid(deployment_id, field_name=\\\"deployment_id\\\")\\n    return await authorized_or_owner_scoped(\\n        db,\\n        Deployment,\\n        id_column=Deployment.id,\\n        resource_id=deployment_uuid,\\n        owner_column=Deployment.user_id,\\n        owner_id=user_id,\\n    )\\n\\n\\n_UNSET = object()\\n\\n\\nasync def update_deployment(\\n    db: AsyncSession,\\n    *,\\n    deployment: Deployment,\\n    display_name: str | None = None,\\n    project_id: UUID | None = None,\\n    deployment_type: DeploymentType | object = _UNSET,\\n    description: str | None | object = _UNSET,\\n) -> Deployment:\\n    next_project_id = project_id if project_id is not None else deployment.project_id\\n    next_deployment_type = deployment.deployment_type if deployment_type is _UNSET else deployment_type\\n    ensure_deployment_immutable_fields(\\n        old_project_id=deployment.project_id,\\n        new_project_id=next_project_id,\\n        old_deployment_type=deployment.deployment_type,\\n        new_deployment_type=next_deployment_type,\\n        old_resource_key=deployment.resource_key,\\n        new_resource_key=deployment.resource_key,\\n        old_provider_account_id=deployment.deployment_provider_account_id,\\n        new_provider_account_id=deployment.deployment_provider_account_id,\\n    )\\n\\n    if display_name is not None:\\n        deployment.display_name = _raise_if_blank(display_name, \\\"display_name\\\")\\n    if project_id is not None:\\n        deployment.project_id = project_id\\n    if deployment_type is not _UNSET:\\n        deployment.deployment_type = deployment_type  # type: ignore[assignment]\\n    if description is not _UNSET:\\n        deployment.description = description  # type: ignore[assignment]\\n    deployment.updated_at = datetime.now(timezone.utc)\\n    db.add(deployment)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        await db.rollback()\\n        await logger.aerror(\\\"IntegrityError updating deployment id=%s: %s\\\", deployment.id, exc)\\n        msg = \\\"Deployment update conflicts with an existing record\\\"\\n        raise ValueError(msg) from exc\\n    await db.refresh(deployment)\\n    return deployment\\n\\n\\nasync def update_deployment_metadata(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment: Deployment,\\n    display_name: str,\\n    description: str | None,\\n) -> Deployment:\\n    \\\"\\\"\\\"Update provider-owned metadata without changing local audit fields.\\\"\\\"\\\"\\n    owner_id = deployment.user_id\\n    if user_id != owner_id:\\n        msg = f\\\"user_id must match the deployment owner for provider metadata sync (expected {owner_id}, got {user_id})\\\"\\n        raise ValueError(msg)\\n\\n    update_item = DeploymentMetadataUpdate(\\n        langflow_db_row=deployment,\\n        display_name=_raise_if_blank(display_name, \\\"display_name\\\"),\\n        description=description,\\n    )\\n    if not _deployment_metadata_has_changed(update_item):\\n        return deployment\\n\\n    stmt = (\\n        update(Deployment)\\n        .where(\\n            Deployment.user_id == owner_id,\\n            Deployment.id == deployment.id,\\n        )\\n        .values(\\n            display_name=update_item.display_name,\\n            description=update_item.description,\\n            # Provider metadata sync should not look like a local edit.\\n            updated_at=Deployment.updated_at,\\n        )\\n        .returning(Deployment)\\n        .execution_options(populate_existing=True)\\n    )\\n    # Consume RETURNING rows so populate_existing refreshes the loaded Deployment instance.\\n    if (await db.exec(stmt)).first() is None:\\n        msg = f\\\"Deployment not found. (id={deployment.id})\\\"\\n        raise ValueError(msg)\\n    return deployment\\n\\n\\ndef _deployment_metadata_changed_fields(update_item: DeploymentMetadataUpdate) -> list[str]:\\n    langflow_data = update_item.langflow_db_row\\n    changed_fields: list[str] = []\\n    if update_item.display_name != langflow_data.display_name:\\n        changed_fields.append(\\\"display_name\\\")\\n    if update_item.description != langflow_data.description:\\n        changed_fields.append(\\\"description\\\")\\n    return changed_fields\\n\\n\\ndef _deployment_metadata_has_changed(update_item: DeploymentMetadataUpdate) -> bool:\\n    return bool(_deployment_metadata_changed_fields(update_item))\\n\\n\\ndef _deployment_metadata_updates_cte(\\n    updates: Sequence[DeploymentMetadataUpdate],\\n) -> CTE:\\n    return (\\n        values(\\n            column(\\\"id\\\", Deployment.__table__.c.id.type),\\n            column(\\\"user_id\\\", Deployment.__table__.c.user_id.type),\\n            column(\\\"display_name\\\", Deployment.__table__.c.display_name.type),\\n            column(\\\"description\\\", Deployment.__table__.c.description.type),\\n        )\\n        .data(\\n            [\\n                (\\n                    item.langflow_db_row.id,\\n                    item.langflow_db_row.user_id,\\n                    item.display_name,\\n                    item.description,\\n                )\\n                for item in updates\\n            ],\\n        )\\n        .cte(\\\"metadata_updates\\\")\\n    )\\n\\n\\nasync def update_deployment_metadata_batch(\\n    db: AsyncSession,\\n    *,\\n    deployment_updates: Sequence[DeploymentMetadataUpdate],\\n) -> None:\\n    \\\"\\\"\\\"Update provider-owned metadata for multiple deployment rows in one statement.\\n\\n    Each update row is matched on ``(id, user_id)`` so shared-deployment list/get\\n    sync writes in the deployment owner's namespace, not the actor's.\\n    \\\"\\\"\\\"\\n    updates = [item for item in deployment_updates if _deployment_metadata_has_changed(item)]\\n    if not updates:\\n        return\\n\\n    metadata_updates = _deployment_metadata_updates_cte(updates)\\n    stmt = (\\n        update(Deployment)\\n        .where(\\n            Deployment.id == metadata_updates.c.id,\\n            Deployment.user_id == metadata_updates.c.user_id,\\n        )\\n        .values(\\n            display_name=metadata_updates.c.display_name,\\n            description=metadata_updates.c.description,\\n            # TODO: add a new synced_at column\\n            # to differentiate between provider metadata sync and local updates.\\n            # For now, explicitly preserve original updated_at value\\n            # so that onupdate does not replace it.\\n            updated_at=Deployment.updated_at,\\n        )\\n        .returning(Deployment)\\n        .execution_options(populate_existing=True)\\n    )\\n    # Consume RETURNING rows so populate_existing refreshes loaded Deployment instances\\n    # and callers see the updated values when re-reading the orm objects in the same session.\\n    (await db.exec(stmt)).all()\\n\\n\\nasync def _scope_to_owner_or_allowed(\\n    stmt: StmtT,\\n    *,\\n    user_id: UUID,\\n    allowed_ids: list[UUID] | None,\\n    visibility_scope: ResourceVisibilityScope | None = None,\\n) -> StmtT:\\n    \\\"\\\"\\\"Scope a deployment query to owner rows plus concrete or domain grants.\\n\\n    ``allowed_ids`` meanings are distinct \u2014 do not treat ``None`` and ``[]`` as\\n    interchangeable:\\n\\n    * ``None`` with no structured scope \u2014 no SQL prefilter. The OSS path remains\\n      owner-only.\\n    * A list \u2014 concrete prefilter; delegates to\\n      :func:`langflow.services.authorization.apply_owned_or_visible_prefilter`,\\n      which owns the owner-override vs visible-ids-only decision (``[]`` +\\n      override off \u2192 no rows).\\n\\n    ``visibility_scope`` represents concrete, workspace, project, or global\\n    grants without expanding wildcards to resource UUIDs and follows the same\\n    scoped-API-key owner-override rule. Centralizing this predicate ensures the\\n    page and count queries cannot drift. Imports stay lazy to avoid\\n    authorization/database import cycles.\\n    \\\"\\\"\\\"\\n    if visibility_scope is None and allowed_ids is None:\\n        return stmt.where(Deployment.user_id == user_id)\\n\\n    from langflow.services.authorization.listing import (\\n        apply_owned_or_visible_prefilter,\\n        apply_owned_or_visible_scope_prefilter,\\n    )\\n\\n    if visibility_scope is None:\\n        return await apply_owned_or_visible_prefilter(\\n            stmt,\\n            id_column=Deployment.id,\\n            owner_clause=Deployment.user_id == user_id,\\n            visible_ids=allowed_ids or (),\\n        )\\n\\n    from langflow.services.database.models.folder.model import Folder\\n\\n    # ``Deployment.workspace_id`` was introduced as denormalized plumbing and\\n    # is absent on legacy rows (and on rows created through the current CRUD\\n    # helper). Resolve the workspace from the authoritative project relation so\\n    # Default-workspace access cannot absorb deployments whose project belongs\\n    # to an explicit workspace.\\n    project_workspace = (\\n        select(Folder.workspace_id).where(Folder.id == Deployment.project_id).correlate(Deployment).scalar_subquery()\\n    )\\n    return await apply_owned_or_visible_scope_prefilter(\\n        stmt,\\n        id_column=Deployment.id,\\n        owner_clause=Deployment.user_id == user_id,\\n        workspace_expression=project_workspace,\\n        project_column=Deployment.project_id,\\n        visibility=visibility_scope,\\n    )\\n\\n\\nasync def has_visible_deployment_for_provider(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    visibility_scope: ResourceVisibilityScope,\\n) -> bool:\\n    \\\"\\\"\\\"Return whether this provider owns a deployment visible to the caller.\\n\\n    Cross-user deployment listing must resolve a foreign provider account to\\n    select its adapter, but loading an arbitrary account by UUID creates an\\n    existence oracle. Bind that relaxed lookup to the same owner/visibility\\n    predicate used by the page and count queries, scoped to the requested\\n    provider, before any provider metadata is loaded.\\n    \\\"\\\"\\\"\\n    stmt = select(Deployment.id).where(Deployment.deployment_provider_account_id == deployment_provider_account_id)\\n    stmt = await _scope_to_owner_or_allowed(\\n        stmt,\\n        user_id=user_id,\\n        allowed_ids=None,\\n        visibility_scope=visibility_scope,\\n    )\\n    return (await db.exec(stmt.limit(1))).first() is not None\\n\\n\\nasync def list_deployments_page(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    offset: int,\\n    limit: int,\\n    row_owner_id: UUID | None = None,\\n    flow_version_ids: list[UUID] | None = None,\\n    project_id: UUID | None = None,\\n    allowed_ids: list[UUID] | None = None,\\n    visibility_scope: ResourceVisibilityScope | None = None,\\n) -> list[tuple[Deployment, int, list[tuple[UUID, str | None]]]]:\\n    \\\"\\\"\\\"Return a page of deployments with attachment counts and matched attachments.\\n\\n    The third tuple element contains ``(flow_version_id, provider_snapshot_id)``\\n    pairs for attachments that matched the ``flow_version_ids`` filter (empty\\n    list when no filter is active).\\n\\n    ``visibility_scope`` is the preferred DB-layer authorization prefilter;\\n    ``allowed_ids`` remains its concrete-ID compatibility form. With neither,\\n    the page is owner-scoped exactly as before.\\n\\n    ``user_id`` is the listing actor for the ownership half of the prefilter.\\n    ``row_owner_id`` scopes attachment counts and filters to the provider-account\\n    owner on shared listings; owner-only callers may omit it.\\n    \\\"\\\"\\\"\\n    if offset < 0:\\n        msg = \\\"offset must be greater than or equal to 0\\\"\\n        raise ValueError(msg)\\n    if limit <= 0:\\n        msg = \\\"limit must be greater than 0\\\"\\n        raise ValueError(msg)\\n    attachment_owner_id = row_owner_id or user_id\\n    attachment_counts_subquery = (\\n        select(\\n            col(FlowVersionDeploymentAttachment.deployment_id).label(\\\"deployment_id\\\"),\\n            func.count(func.distinct(FlowVersionDeploymentAttachment.flow_version_id)).label(\\\"attached_count\\\"),\\n        )\\n        # Join FlowVersion so stale attachment rows with missing version parent\\n        # do not inflate attached_count in deployment list responses.\\n        .join(\\n            FlowVersion,\\n            FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n        )\\n        .where(FlowVersionDeploymentAttachment.user_id == attachment_owner_id)\\n        .group_by(FlowVersionDeploymentAttachment.deployment_id)\\n        .subquery()\\n    )\\n    stmt = (\\n        select(\\n            Deployment,\\n            func.coalesce(attachment_counts_subquery.c.attached_count, 0).label(\\\"attached_count\\\"),\\n        )\\n        .outerjoin(attachment_counts_subquery, attachment_counts_subquery.c.deployment_id == Deployment.id)\\n        .where(Deployment.deployment_provider_account_id == deployment_provider_account_id)\\n    )\\n    stmt = await _scope_to_owner_or_allowed(\\n        stmt,\\n        user_id=user_id,\\n        allowed_ids=allowed_ids,\\n        visibility_scope=visibility_scope,\\n    )\\n    if project_id is not None:\\n        stmt = stmt.where(Deployment.project_id == project_id)\\n    if flow_version_ids:\\n        matched_deployments_subquery = (\\n            select(FlowVersionDeploymentAttachment.deployment_id)\\n            .where(\\n                FlowVersionDeploymentAttachment.user_id == attachment_owner_id,\\n                col(FlowVersionDeploymentAttachment.flow_version_id).in_(flow_version_ids),\\n            )\\n            .group_by(FlowVersionDeploymentAttachment.deployment_id)\\n            .subquery()\\n        )\\n        stmt = stmt.join(\\n            matched_deployments_subquery,\\n            matched_deployments_subquery.c.deployment_id == Deployment.id,\\n        )\\n    stmt = stmt.order_by(col(Deployment.created_at).desc(), col(Deployment.id).desc()).offset(offset).limit(limit)\\n    rows = (await db.exec(stmt)).all()\\n    deployment_rows = [(deployment, int(attached_count or 0)) for deployment, attached_count in rows]\\n    if not flow_version_ids or not deployment_rows:\\n        return [(deployment, attached_count, []) for deployment, attached_count in deployment_rows]\\n\\n    deployment_ids = [deployment.id for deployment, _ in deployment_rows]\\n    matched_rows = (\\n        await db.exec(\\n            select(\\n                FlowVersionDeploymentAttachment.deployment_id,\\n                FlowVersionDeploymentAttachment.flow_version_id,\\n                FlowVersionDeploymentAttachment.provider_snapshot_id,\\n            ).where(\\n                FlowVersionDeploymentAttachment.user_id == attachment_owner_id,\\n                col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n                col(FlowVersionDeploymentAttachment.flow_version_id).in_(flow_version_ids),\\n            )\\n        )\\n    ).all()\\n    matched_by_deployment: dict[UUID, list[tuple[UUID, str | None]]] = {}\\n    for deployment_id, flow_version_id, provider_snapshot_id in matched_rows:\\n        entries = matched_by_deployment.setdefault(deployment_id, [])\\n        pair = (flow_version_id, provider_snapshot_id)\\n        if pair not in entries:\\n            entries.append(pair)\\n\\n    return [\\n        (\\n            deployment,\\n            attached_count,\\n            matched_by_deployment.get(deployment.id, []),\\n        )\\n        for deployment, attached_count in deployment_rows\\n    ]\\n\\n\\nasync def list_deployments_for_flows_with_provider_info(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_ids: list[UUID],\\n    provider_account_id: UUID | None = None,\\n) -> list[tuple[Deployment, str]]:\\n    \\\"\\\"\\\"Return distinct deployments linked to any flow in *flow_ids* with provider key.\\\"\\\"\\\"\\n    if not flow_ids:\\n        return []\\n\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    deployment_ids_subquery = (\\n        select(FlowVersionDeploymentAttachment.deployment_id)\\n        .join(\\n            FlowVersion,\\n            FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n        )\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersion.flow_id.in_(flow_ids),\\n        )\\n        .distinct()\\n        .subquery()\\n    )\\n\\n    stmt = (\\n        select(Deployment, DeploymentProviderAccount.provider_key)\\n        .join(deployment_ids_subquery, deployment_ids_subquery.c.deployment_id == Deployment.id)\\n        .join(\\n            DeploymentProviderAccount,\\n            DeploymentProviderAccount.id == Deployment.deployment_provider_account_id,\\n        )\\n        .where(Deployment.user_id == user_id)\\n        .order_by(\\n            Deployment.deployment_provider_account_id,\\n            DeploymentProviderAccount.provider_key,\\n            Deployment.id,\\n        )\\n    )\\n    if provider_account_id is not None:\\n        stmt = stmt.where(Deployment.deployment_provider_account_id == provider_account_id)\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def list_project_deployments_with_provider_info(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    project_id: UUID,\\n    provider_account_id: UUID | None = None,\\n) -> list[tuple[Deployment, str]]:\\n    \\\"\\\"\\\"Return project deployments with provider key for provider-scoped sync.\\\"\\\"\\\"\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n\\n    stmt = (\\n        select(Deployment, DeploymentProviderAccount.provider_key)\\n        .join(\\n            DeploymentProviderAccount,\\n            DeploymentProviderAccount.id == Deployment.deployment_provider_account_id,\\n        )\\n        .where(\\n            Deployment.user_id == user_id,\\n            Deployment.project_id == project_id,\\n        )\\n        .order_by(\\n            Deployment.deployment_provider_account_id,\\n            DeploymentProviderAccount.provider_key,\\n            Deployment.id,\\n        )\\n    )\\n    if provider_account_id is not None:\\n        stmt = stmt.where(Deployment.deployment_provider_account_id == provider_account_id)\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def count_deployments_by_provider(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    row_owner_id: UUID | None = None,\\n    flow_version_ids: list[UUID] | None = None,\\n    project_id: UUID | None = None,\\n    allowed_ids: list[UUID] | None = None,\\n    visibility_scope: ResourceVisibilityScope | None = None,\\n) -> int:\\n    \\\"\\\"\\\"Count deployments for a provider account.\\n\\n    Authorization arguments mirror ``list_deployments_page`` so pagination\\n    totals use exactly the same owner-plus-visible predicate as the page.\\n    ``row_owner_id`` scopes attachment filters to the provider-account owner on\\n    shared listings; owner-only callers may omit it.\\n    \\\"\\\"\\\"\\n    attachment_owner_id = row_owner_id or user_id\\n    stmt = select(func.count(Deployment.id)).where(\\n        Deployment.deployment_provider_account_id == deployment_provider_account_id,\\n    )\\n    stmt = await _scope_to_owner_or_allowed(\\n        stmt,\\n        user_id=user_id,\\n        allowed_ids=allowed_ids,\\n        visibility_scope=visibility_scope,\\n    )\\n    if project_id is not None:\\n        stmt = stmt.where(Deployment.project_id == project_id)\\n    if flow_version_ids:\\n        matched_deployments_subquery = (\\n            select(FlowVersionDeploymentAttachment.deployment_id)\\n            .where(\\n                FlowVersionDeploymentAttachment.user_id == attachment_owner_id,\\n                col(FlowVersionDeploymentAttachment.flow_version_id).in_(flow_version_ids),\\n            )\\n            .group_by(FlowVersionDeploymentAttachment.deployment_id)\\n            .subquery()\\n        )\\n        stmt = stmt.join(\\n            matched_deployments_subquery,\\n            matched_deployments_subquery.c.deployment_id == Deployment.id,\\n        )\\n    return int((await db.exec(stmt)).one() or 0)\\n\\n\\nasync def delete_deployment_by_resource_key(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_provider_account_id: UUID,\\n    resource_key: str,\\n) -> int | UnconfirmedDeleteRowcount:\\n    resource_key_s = resource_key.strip()\\n    # Delete attachment rows explicitly before deleting the deployment.\\n    # This keeps behavior correct even when DB-level FK cascades are disabled\\n    # (for example, SQLite with foreign_keys=OFF), avoiding orphan attachments.\\n    deployment_id = (\\n        await db.exec(\\n            select(Deployment.id).where(\\n                Deployment.user_id == user_id,\\n                Deployment.deployment_provider_account_id == deployment_provider_account_id,\\n                Deployment.resource_key == resource_key_s,\\n            )\\n        )\\n    ).first()\\n    if deployment_id is not None:\\n        await db.exec(\\n            delete(FlowVersionDeploymentAttachment).where(\\n                FlowVersionDeploymentAttachment.user_id == user_id,\\n                FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n            )\\n        )\\n\\n    stmt = delete(Deployment).where(\\n        Deployment.user_id == user_id,\\n        Deployment.deployment_provider_account_id == deployment_provider_account_id,\\n        Deployment.resource_key == resource_key_s,\\n    )\\n    result = await db.exec(stmt)\\n    return await _interpret_delete_rowcount(result.rowcount, context=f\\\"resource_key={resource_key_s!r}\\\")\\n\\n\\nasync def delete_deployment_by_id(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID | str,\\n) -> int | UnconfirmedDeleteRowcount:\\n    deployment_uuid = parse_uuid(deployment_id, field_name=\\\"deployment_id\\\")\\n    # Delete attachment rows explicitly before deleting the deployment.\\n    # This keeps behavior correct even when DB-level FK cascades are disabled\\n    # (for example, SQLite with foreign_keys=OFF), avoiding orphan attachments.\\n    await db.exec(\\n        delete(FlowVersionDeploymentAttachment).where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.deployment_id == deployment_uuid,\\n        )\\n    )\\n\\n    stmt = delete(Deployment).where(\\n        Deployment.user_id == user_id,\\n        Deployment.id == deployment_uuid,\\n    )\\n    result = await db.exec(stmt)\\n    return await _interpret_delete_rowcount(result.rowcount, context=f\\\"deployment_id={deployment_uuid}\\\")\\n\\n\\nasync def delete_deployments_by_ids(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_ids: list[UUID],\\n) -> int | UnconfirmedDeleteRowcount:\\n    \\\"\\\"\\\"Delete multiple deployments (and their attachments) in two batched statements.\\\"\\\"\\\"\\n    if not deployment_ids:\\n        return 0\\n    # Delete attachment rows explicitly before deleting the deployments, mirroring\\n    # delete_deployment_by_id so behavior stays correct when DB-level FK cascades\\n    # are disabled (for example, SQLite with foreign_keys=OFF).\\n    await db.exec(\\n        delete(FlowVersionDeploymentAttachment).where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n        )\\n    )\\n\\n    stmt = delete(Deployment).where(\\n        Deployment.user_id == user_id,\\n        col(Deployment.id).in_(deployment_ids),\\n    )\\n    result = await db.exec(stmt)\\n    return await _interpret_delete_rowcount(result.rowcount, context=f\\\"deployment_ids={deployment_ids}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0fd37308eaead1ba93a6f8a40ef6b39d6763fed98667bf3c817369cc643ff720\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\n_GUARD_FRIENDLY_DETAILS: dict[str, str] = {\\n    \\\"FLOW_HAS_DEPLOYED_VERSIONS\\\": (\\n        \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n        \\\"Please remove its versions from deployments first.\\\"\\n    ),\\n    \\\"PROJECT_HAS_DEPLOYMENTS\\\": (\\n        \\\"This project cannot be deleted because it has deployments. Please delete its deployments first.\\\"\\n    ),\\n    \\\"FLOW_DEPLOYED_IN_PROJECT\\\": (\\n        \\\"This flow cannot be moved to another project until its versions \\\"\\n        \\\"are removed from deployments in its current project.\\\"\\n    ),\\n    \\\"DEPLOYMENT_PROJECT_MOVE\\\": (\\n        \\\"This deployment cannot be moved to a different project. Re-create it in the target project instead.\\\"\\n    ),\\n    \\\"DEPLOYMENT_TYPE_UPDATE\\\": (\\\"The deployment type cannot be modified.\\\"),\\n    \\\"DEPLOYMENT_RESOURCE_KEY_UPDATE\\\": (\\n        \\\"This deployment resource key cannot be modified on an existing deployment. Re-create it instead.\\\"\\n    ),\\n    \\\"DEPLOYMENT_PROVIDER_ACCOUNT_MOVE\\\": (\\n        \\\"This deployment cannot be moved to a different provider account. Re-create it under the \\\"\\n        \\\"target provider account.\\\"\\n    ),\\n    \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\": (\\n        \\\"This deployment provider account identity cannot be modified. Re-create the account instead.\\\"\\n    ),\\n    \\\"CROSS_PROJECT_ATTACHMENT\\\": \\\"Flow versions can only be in deployments in the same project.\\\",\\n}\\n\\n\\nclass DeploymentGuardError(Exception):\\n    \\\"\\\"\\\"Raised when a deployment guard blocks an operation.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        code: str,\\n        technical_detail: str,\\n        detail: str,\\n    ):\\n        self.code = code\\n        self.technical_detail = technical_detail\\n        self.detail = detail\\n        super().__init__(detail)\\n\\n\\n_UNKNOWN_GUARD_FALLBACK_DETAIL = \\\"Operation blocked by deployment guard ({code}).\\\"\\n\\n\\ndef get_friendly_guard_detail(code: str) -> str:\\n    \\\"\\\"\\\"Map a guard code to the API-facing detail text.\\\"\\\"\\\"\\n    return _GUARD_FRIENDLY_DETAILS.get(code, _UNKNOWN_GUARD_FALLBACK_DETAIL.format(code=code))\\n\\n\\ndef parse_deployment_guard_error(exc: BaseException) -> DeploymentGuardError | None:\\n    \\\"\\\"\\\"Return ``exc`` when it is a ``DeploymentGuardError``; otherwise ``None``.\\n\\n    Guard failures must be raised explicitly as ``DeploymentGuardError`` by the\\n    operation that enforces the guard.\\n    \\\"\\\"\\\"\\n    return exc if isinstance(exc, DeploymentGuardError) else None\\n\\n\\ndef raise_if_deployment_guard_error_or_skip(exc: BaseException) -> None:\\n    \\\"\\\"\\\"Raise ``DeploymentGuardError`` when ``exc`` is one; otherwise do nothing.\\\"\\\"\\\"\\n    if not isinstance(exc, DeploymentGuardError):\\n        return\\n\\n    raise exc\\n\\n\\nasync def araise_if_deployment_guard_error_or_skip(\\n    exc: BaseException,\\n    *,\\n    log_message: str | None = None,\\n    remap: Callable[[DeploymentGuardError], DeploymentGuardError] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Raise ``DeploymentGuardError`` and optionally log/remap it; otherwise do nothing.\\\"\\\"\\\"\\n    if not isinstance(exc, DeploymentGuardError):\\n        return\\n\\n    guard_error = remap(exc) if remap is not None else exc\\n\\n    if log_message is not None:\\n        await logger.adebug(\\n            \\\"%s code=%s technical_detail=%s\\\",\\n            log_message,\\n            guard_error.code,\\n            guard_error.technical_detail,\\n        )\\n\\n    if guard_error is exc:\\n        raise exc\\n    raise guard_error from exc\\n\\n\\ndef remap_flow_guard_for_project_delete(exc: DeploymentGuardError) -> DeploymentGuardError:\\n    \\\"\\\"\\\"Map flow-scoped guard code to a project-scoped code for project deletes.\\\"\\\"\\\"\\n    if exc.code != \\\"FLOW_HAS_DEPLOYED_VERSIONS\\\":\\n        return exc\\n\\n    return DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=(f\\\"DELETE folder blocked while deleting project flows: {exc.technical_detail}\\\"),\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0634af317bc7099805067314c3871a0c35319455842eca2f09155ea824d9aba\",\"content\":\"\\\"\\\"\\\"Application-level delete guards for deployment-linked resources.\\n\\nThese checks are used by flow/project delete paths to fail fast with a friendly\\n``DeploymentGuardError`` when dependent deployment links still exist.\\n\\nConcurrency note:\\nThese are pre-delete existence checks (check-then-delete) implemented as\\nseparate statements, not as one DB-enforced invariant. A different transaction\\ncan commit new dependent rows between the check and the later delete/flush.\\nCallers should treat these guards as\\nbest-effort protection and combine them with bounded retry/sync behavior.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import col, delete, select\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    DeploymentGuardError,\\n    get_friendly_guard_detail,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\n\\n\\nasync def check_flow_has_deployed_versions(db: AsyncSession, *, flow_id: UUID) -> None:\\n    \\\"\\\"\\\"Raise when the flow still has flow versions attached to deployments.\\n\\n    This is an app-level pre-delete guard. It intentionally checks for the\\n    existence of at least one *live* deployment attachment and raises a\\n    friendly guard error.\\n\\n    If legacy/orphan attachment rows exist (for example from environments where\\n    SQLite foreign key cascades were not enforced), this guard prunes them for\\n    the target flow so they don't permanently block deletion.\\n    \\\"\\\"\\\"\\n    # Prune stale orphan attachments first via a single DELETE-with-subquery.\\n    # Doing the write before any SELECT means the connection takes a writer\\n    # lock straight away on SQLite and avoids the SHARED -> RESERVED upgrade\\n    # trap that can surface as `OperationalError: database is locked`.\\n    stale_subquery = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n        .outerjoin(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .where(\\n            FlowVersion.flow_id == flow_id,\\n            Deployment.id.is_(None),  # deployment no longer exists\\n        )\\n        .scalar_subquery()\\n    )\\n    pruned_result = await db.exec(\\n        delete(FlowVersionDeploymentAttachment).where(col(FlowVersionDeploymentAttachment.id).in_(stale_subquery))\\n    )\\n    # log the raw value verbatim so any driver oddity is visible in operator logs\\n    # rather than silently masked by coercion.\\n    pruned_rowcount = pruned_result.rowcount\\n    await logger.ainfo(\\n        \\\"Orphan deployment attachment prune for flow %s completed (rowcount=%r)\\\",\\n        flow_id,\\n        pruned_rowcount,\\n    )\\n\\n    attached = (\\n        await db.exec(\\n            select(FlowVersionDeploymentAttachment.id)\\n            .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n            .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n            .where(FlowVersion.flow_id == flow_id)\\n            .limit(1)\\n        )\\n    ).first()\\n    if attached is not None:\\n        # We're about to raise, so the orphan prune above may be rolled back\\n        # depending on how the caller manages its transaction (e.g. the retry\\n        # wrapper runs us inside a SAVEPOINT). Surface that explicitly so\\n        # operators aren't surprised when orphan rows persist after a blocked\\n        # delete attempt.\\n        await logger.awarning(\\n            \\\"Orphan deployment attachment prune for flow %s may be rolled back by the caller's \\\"\\n            \\\"transaction because live attachments still exist (pruned rowcount=%r)\\\",\\n            flow_id,\\n            pruned_rowcount,\\n        )\\n        raise DeploymentGuardError(\\n            code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n            technical_detail=(\\n                \\\"DELETE flow_version blocked: dependent rows exist in flow_version_deployment_attachment \\\"\\n                \\\"for the target flow.\\\"\\n            ),\\n            detail=get_friendly_guard_detail(\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\"),\\n        )\\n\\n\\nasync def check_project_has_deployments(db: AsyncSession, *, project_id: UUID) -> None:\\n    \\\"\\\"\\\"Raise when the project still has deployments.\\n\\n    This is an app-level pre-delete guard. It intentionally checks for the\\n    existence of at least one deployment and raises a friendly guard error.\\n    \\\"\\\"\\\"\\n    has_deployments = (await db.exec(select(Deployment.id).where(Deployment.project_id == project_id).limit(1))).first()\\n    if has_deployments is None:\\n        return\\n\\n    raise DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=\\\"DELETE folder blocked: dependent rows exist in deployment for the target project.\\\",\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5013d2b1f6335f89573c7425fde2d443f6a88fe55c360c42e200dda875526e08\",\"content\":\"from datetime import datetime\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom pydantic import field_validator\\nfrom sqlalchemy import Enum as SQLEnum\\nfrom sqlalchemy import ForeignKey, UniqueConstraint\\nfrom sqlmodel import Column, DateTime, Field, Relationship, SQLModel, func\\n\\nfrom langflow.schema.serialize import UUIDstr\\nfrom langflow.services.database.utils import validate_non_empty_string, validate_non_empty_string_preserve_value\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n    from langflow.services.database.models.folder.model import Folder\\n    from langflow.services.database.models.user.model import User\\n\\n\\nclass Deployment(SQLModel, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"deployment\\\"\\n    __table_args__ = (\\n        UniqueConstraint(\\n            \\\"deployment_provider_account_id\\\", \\\"resource_key\\\", name=\\\"uq_deployment_resource_key_in_provider\\\"\\n        ),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    resource_key: str = Field(index=True)\\n    user_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True)\\n    )\\n    # \\\"project\\\" is represented by a Folder row in the existing schema.\\n    project_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"folder.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True)\\n    )\\n    deployment_provider_account_id: UUIDstr = Field(\\n        sa_column=Column(\\n            sa.Uuid(), ForeignKey(\\\"deployment_provider_account.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True\\n        )\\n    )\\n    workspace_id: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), nullable=True, index=True),\\n    )\\n    # TODO: Add DB-level length enforcement for provider-synced display_name and description.\\n    # nullable=True at the DB level to keep schema compatibility during migration transitions;\\n    # application-layer validation still treats display_name as required.\\n    display_name: str = Field(\\n        sa_column=Column(sa.String(), nullable=True),\\n        description=\\\"Deployment name synced from the provider.\\\",\\n    )\\n    description: str | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Text(), nullable=True),\\n    )\\n    # ``DeploymentType`` is imported from LFX\\n    # (``lfx.services.adapters.deployment.schema``).  The DB-level\\n    # ``deployment_type_enum`` constraint is defined by a Langflow alembic\\n    # migration, **not** by LFX code.  This decoupling is intentional:\\n    #\\n    # LFX adds a new member  -> INSERT/UPDATE with the new value is rejected\\n    #                           by the DB until a Langflow migration adds it\\n    #                           to the enum type.  Langflow explicitly opts\\n    #                           in to new deployment types.\\n    #\\n    # LFX renames a value    -> Existing rows are unaffected (the DB stores\\n    #                           the old string).  Python deserialization via\\n    #                           ``DeploymentType(value)`` will raise\\n    #                           ``ValueError`` on read until the migration\\n    #                           and enum are reconciled.\\n    #\\n    # LFX removes a member   -> Same as rename: stored rows retain the\\n    #                           deleted string, but Python reads break.\\n    #                           The DB constraint still lists the old value,\\n    #                           so no data loss occurs.\\n    #\\n    # In all mutation scenarios the DB data remains intact; only the\\n    # application layer breaks until a coordinated migration is applied.\\n    #\\n    # To add a new value to ``deployment_type_enum``:\\n    #   1. Add the member to ``DeploymentType`` in LFX (or confirm it exists).\\n    #   2. Create a Langflow alembic migration that runs:\\n    #        op.execute(\\\"ALTER TYPE deployment_type_enum ADD VALUE '<new>'\\\")\\n    #      For SQLite (dev/test) this is a no-op; the CHECK constraint is\\n    #      recreated automatically by ``batch_alter_table``.\\n    #   3. Deploy the migration before any code writes the new value.\\n    #\\n    # Removing or renaming a value is **strongly discouraged**.  Existing\\n    # rows reference the old string; renaming silently breaks every read\\n    # of those rows (``DeploymentType(value)`` raises ``ValueError``).\\n    # If absolutely necessary:\\n    #   1. Create a migration that (a) updates existing rows to the\\n    #      replacement value, then (b) recreates the enum type without\\n    #      the old value (PostgreSQL requires CREATE TYPE \u2026 / ALTER COLUMN\\n    #      \u2026 TYPE \u2026 USING \u2026; SQLite uses ``batch_alter_table``).\\n    #   2. Update or remove the member in the Python enum.\\n    #   3. Coordinate with LFX \u2014 adapters and callers may still reference\\n    #      the old value.\\n    #\\n    # nullable=True at the DB level to satisfy the EXPAND-phase migration\\n    # validator; application-layer code treats this as required.\\n    deployment_type: DeploymentType = Field(\\n        sa_column=Column(\\n            SQLEnum(\\n                DeploymentType,\\n                name=\\\"deployment_type_enum\\\",\\n                values_callable=lambda enum: [member.value for member in enum],\\n            ),\\n            nullable=True,\\n            index=True,\\n        ),\\n    )\\n    created_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=False),\\n    )\\n    updated_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False),\\n    )\\n\\n    user: \\\"User\\\" = Relationship(back_populates=\\\"deployments\\\")\\n    deployment_provider_account: \\\"DeploymentProviderAccount\\\" = Relationship(back_populates=\\\"deployments\\\")\\n    folder: \\\"Folder\\\" = Relationship(back_populates=\\\"deployments\\\")\\n\\n    @field_validator(\\\"display_name\\\", \\\"resource_key\\\")\\n    @classmethod\\n    def validate_non_empty(cls, v: str, info: object) -> str:\\n        validators = {\\n            \\\"display_name\\\": validate_non_empty_string_preserve_value,\\n            \\\"resource_key\\\": validate_non_empty_string,\\n        }\\n        validator = validators.get(getattr(info, \\\"field_name\\\", None), validate_non_empty_string)\\n        return validator(v, info)\\n\\n\\nclass DeploymentRead(SQLModel):\\n    id: UUID\\n    resource_key: str\\n    user_id: UUID\\n    project_id: UUID\\n    deployment_provider_account_id: UUID\\n    display_name: str\\n    description: str | None = None\\n    deployment_type: DeploymentType\\n    created_at: datetime\\n    updated_at: datetime\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment/orm_guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3e70ee81ee12ed21b15c6634faf22478c48929006fbd1abb4fa6132f62e92441\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    DeploymentGuardError,\\n    get_friendly_guard_detail,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.services.adapters.deployment.schema import DeploymentType\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\n\\n\\ndef _raise_flow_deployed_in_project() -> None:\\n    raise DeploymentGuardError(\\n        code=\\\"FLOW_DEPLOYED_IN_PROJECT\\\",\\n        technical_detail=(\\n            \\\"UPDATE flow.folder_id blocked: versions of this flow remain attached \\\"\\n            \\\"to deployments in the current project scope.\\\"\\n        ),\\n        detail=get_friendly_guard_detail(\\\"FLOW_DEPLOYED_IN_PROJECT\\\"),\\n    )\\n\\n\\nasync def ensure_flow_move_allowed(\\n    db: AsyncSession,\\n    *,\\n    flow_id: UUID,\\n    old_folder_id: UUID | None,\\n    new_folder_id: UUID | None,\\n) -> None:\\n    \\\"\\\"\\\"Block moving a deployed flow out of its current project scope.\\\"\\\"\\\"\\n    if old_folder_id == new_folder_id:\\n        return\\n\\n    attached_in_old_project = (\\n        await db.exec(\\n            select(FlowVersionDeploymentAttachment.id)\\n            .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n            .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n            .where(\\n                FlowVersion.flow_id == flow_id,\\n                Deployment.project_id == old_folder_id,\\n            )\\n            .limit(1)\\n        )\\n    ).first()\\n    if attached_in_old_project is None:\\n        return\\n\\n    _raise_flow_deployed_in_project()\\n\\n\\nasync def ensure_flow_moves_allowed(\\n    db: AsyncSession,\\n    *,\\n    flow_folder_pairs: list[tuple[UUID, UUID | None]],\\n    new_folder_id: UUID | None,\\n) -> None:\\n    \\\"\\\"\\\"Validate a batch of flow folder moves before a bulk update.\\n\\n    Groups flows by source folder and issues one query per group,\\n    so the typical single-source-folder case runs a single SELECT.\\n    \\\"\\\"\\\"\\n    candidates = [(fid, ofid) for fid, ofid in flow_folder_pairs if ofid != new_folder_id]\\n    if not candidates:\\n        return\\n\\n    by_folder: dict[UUID | None, list[UUID]] = {}\\n    for flow_id, old_folder_id in candidates:\\n        by_folder.setdefault(old_folder_id, []).append(flow_id)\\n\\n    for old_folder_id, flow_ids in by_folder.items():\\n        blocked = (\\n            await db.exec(\\n                select(FlowVersion.flow_id)\\n                .join(\\n                    FlowVersionDeploymentAttachment,\\n                    FlowVersionDeploymentAttachment.flow_version_id == FlowVersion.id,\\n                )\\n                .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n                .where(\\n                    col(FlowVersion.flow_id).in_(flow_ids),\\n                    Deployment.project_id == old_folder_id,\\n                )\\n                .limit(1)\\n            )\\n        ).first()\\n        if blocked is not None:\\n            _raise_flow_deployed_in_project()\\n\\n\\ndef ensure_deployment_immutable_fields(\\n    *,\\n    old_project_id: UUID,\\n    new_project_id: UUID,\\n    old_deployment_type: DeploymentType,\\n    new_deployment_type: DeploymentType,\\n    old_resource_key: str,\\n    new_resource_key: str,\\n    old_provider_account_id: UUID,\\n    new_provider_account_id: UUID,\\n) -> None:\\n    \\\"\\\"\\\"Block immutable deployment identity/scope field updates.\\\"\\\"\\\"\\n    if old_project_id != new_project_id:\\n        raise DeploymentGuardError(\\n            code=\\\"DEPLOYMENT_PROJECT_MOVE\\\",\\n            technical_detail=(\\n                \\\"UPDATE deployment.project_id blocked: project scope is immutable for existing deployments.\\\"\\n            ),\\n            detail=get_friendly_guard_detail(\\\"DEPLOYMENT_PROJECT_MOVE\\\"),\\n        )\\n\\n    if old_deployment_type != new_deployment_type:\\n        raise DeploymentGuardError(\\n            code=\\\"DEPLOYMENT_TYPE_UPDATE\\\",\\n            technical_detail=\\\"Cannot modify deployment type on an existing deployment.\\\",\\n            detail=get_friendly_guard_detail(\\\"DEPLOYMENT_TYPE_UPDATE\\\"),\\n        )\\n\\n    if old_resource_key != new_resource_key:\\n        raise DeploymentGuardError(\\n            code=\\\"DEPLOYMENT_RESOURCE_KEY_UPDATE\\\",\\n            technical_detail=\\\"Cannot modify deployment resource key on an existing deployment.\\\",\\n            detail=get_friendly_guard_detail(\\\"DEPLOYMENT_RESOURCE_KEY_UPDATE\\\"),\\n        )\\n\\n    if old_provider_account_id != new_provider_account_id:\\n        raise DeploymentGuardError(\\n            code=\\\"DEPLOYMENT_PROVIDER_ACCOUNT_MOVE\\\",\\n            technical_detail=(\\n                \\\"UPDATE deployment.deployment_provider_account_id blocked: provider account scope is immutable.\\\"\\n            ),\\n            detail=get_friendly_guard_detail(\\\"DEPLOYMENT_PROVIDER_ACCOUNT_MOVE\\\"),\\n        )\\n\\n\\ndef ensure_provider_account_identity_immutable(\\n    *,\\n    old_provider_key: DeploymentProviderKey,\\n    new_provider_key: DeploymentProviderKey,\\n    old_provider_tenant_id: str | None,\\n    new_provider_tenant_id: str | None,\\n    old_provider_url: str,\\n    new_provider_url: str,\\n) -> None:\\n    \\\"\\\"\\\"Block updates to immutable deployment provider account identity fields.\\\"\\\"\\\"\\n    if (\\n        old_provider_key == new_provider_key\\n        and old_provider_tenant_id == new_provider_tenant_id\\n        and old_provider_url == new_provider_url\\n    ):\\n        return\\n\\n    raise DeploymentGuardError(\\n        code=\\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\",\\n        technical_detail=(\\n            \\\"UPDATE deployment_provider_account blocked: provider_key, provider_tenant_id, \\\"\\n            \\\"and provider_url are immutable.\\\"\\n        ),\\n        detail=get_friendly_guard_detail(\\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\"),\\n    )\\n\\n\\nasync def ensure_attachment_project_match(\\n    db: AsyncSession,\\n    *,\\n    flow_version_id: UUID,\\n    deployment_id: UUID,\\n) -> None:\\n    \\\"\\\"\\\"Block cross-project flow-version deployment attachments.\\n\\n    Note:\\n        This guard compares project scopes only. If both lookups resolve to\\n        ``None`` (for example, both records are missing), the equality check\\n        passes and this guard returns. Entity existence is still enforced by\\n        downstream FK/constraint checks on flush/commit.\\n    \\\"\\\"\\\"\\n    flow_project_id = (\\n        await db.exec(\\n            select(Flow.folder_id)\\n            .select_from(FlowVersion)\\n            .join(Flow, Flow.id == FlowVersion.flow_id)\\n            .where(FlowVersion.id == flow_version_id)\\n            .limit(1)\\n        )\\n    ).first()\\n    deployment_project_id = (\\n        await db.exec(select(Deployment.project_id).where(Deployment.id == deployment_id).limit(1))\\n    ).first()\\n\\n    if flow_project_id == deployment_project_id:\\n        return\\n\\n    raise DeploymentGuardError(\\n        code=\\\"CROSS_PROJECT_ATTACHMENT\\\",\\n        technical_detail=(\\n            \\\"INSERT flow_version_deployment_attachment blocked: flow project scope does not match \\\"\\n            \\\"deployment project scope.\\\"\\n        ),\\n        detail=get_friendly_guard_detail(\\\"CROSS_PROJECT_ATTACHMENT\\\"),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment_provider_account/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"79eec5c141a7e24d2f0334ee75e8a5eef57f0a32ca81580a9d4dd7fa71a9130e\",\"content\":\"from .model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderAccountRead,\\n)\\nfrom .schemas import DeploymentProviderKey\\n\\n__all__ = [\\n    \\\"DeploymentProviderAccount\\\",\\n    \\\"DeploymentProviderAccountRead\\\",\\n    \\\"DeploymentProviderKey\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment_provider_account/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ef2f28c27088ea7ef2b2b8e1f2a530f8bd55e72a2765d927fc40067b403e8309\",\"content\":\"from __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\n\\nfrom cryptography.fernet import InvalidToken\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_provider_account_identity_immutable\\nfrom langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\nfrom langflow.services.database.utils import normalize_string_or_none, parse_uuid\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_UNSET = object()\\n\\n\\ndef _strip_or_raise(value: str, field_name: str) -> str:\\n    \\\"\\\"\\\"Return *value* stripped of whitespace, or raise if blank.\\\"\\\"\\\"\\n    stripped = value.strip()\\n    if not stripped:\\n        msg = f\\\"{field_name} must not be empty\\\"\\n        raise ValueError(msg)\\n    return stripped\\n\\n\\ndef _encrypt_api_key(raw: str) -> str:\\n    \\\"\\\"\\\"Encrypt an API key, raising ``RuntimeError`` on failure.\\\"\\\"\\\"\\n    stripped = raw.strip()\\n    if not stripped:\\n        msg = \\\"api_key must not be empty\\\"\\n        raise ValueError(msg)\\n    try:\\n        return auth_utils.encrypt_api_key(stripped)\\n    except (ValueError, InvalidToken, TypeError, AttributeError) as e:\\n        msg = \\\"Failed to encrypt API key -- check server encryption configuration\\\"\\n        raise RuntimeError(msg) from e\\n\\n\\ndef _coerce_provider_key(value: str | DeploymentProviderKey) -> DeploymentProviderKey:\\n    if isinstance(value, DeploymentProviderKey):\\n        return value\\n    normalized = _strip_or_raise(value, \\\"provider_key\\\")\\n    try:\\n        return DeploymentProviderKey(normalized)\\n    except ValueError as exc:\\n        msg = f\\\"Unsupported provider_key: {normalized}\\\"\\n        raise ValueError(msg) from exc\\n\\n\\nasync def get_provider_account_by_id(\\n    db: AsyncSession,\\n    *,\\n    provider_id: UUID | str,\\n    user_id: UUID | str,\\n) -> DeploymentProviderAccount | None:\\n    provider_uuid = parse_uuid(provider_id, field_name=\\\"provider_id\\\")\\n    user_uuid = parse_uuid(user_id, field_name=\\\"user_id\\\")\\n\\n    stmt = select(DeploymentProviderAccount).where(\\n        DeploymentProviderAccount.id == provider_uuid,\\n        DeploymentProviderAccount.user_id == user_uuid,\\n    )\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def get_provider_account_by_id_unscoped(\\n    db: AsyncSession,\\n    *,\\n    provider_id: UUID | str,\\n) -> DeploymentProviderAccount | None:\\n    \\\"\\\"\\\"Load a provider account by id without an owner scope.\\n\\n    Reserved for the deployment-list authz prefilter path: a caller granted READ\\n    on a *shared* deployment under another user's provider account needs that\\n    account's ``provider_key`` (to resolve the adapter/mapper) even though they do\\n    not own the account. Row-level access is still decided by the\\n    ``(owner \u2295 visible)`` SQL union in ``list_deployments_synced`` plus\\n    ``ensure_deployment_permission`` \u2014 this only widens which ``provider_key`` may\\n    be read, never which deployment rows surface. The list response carries no\\n    provider secrets (only ``provider_key`` is used). Do NOT use on owner-scoped\\n    paths; prefer ``get_provider_account_by_id`` there.\\n    \\\"\\\"\\\"\\n    provider_uuid = parse_uuid(provider_id, field_name=\\\"provider_id\\\")\\n    stmt = select(DeploymentProviderAccount).where(DeploymentProviderAccount.id == provider_uuid)\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def list_provider_accounts(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID | str,\\n    offset: int = 0,\\n    limit: int | None = None,\\n) -> list[DeploymentProviderAccount]:\\n    user_uuid = parse_uuid(user_id, field_name=\\\"user_id\\\")\\n    stmt = (\\n        select(DeploymentProviderAccount)\\n        .where(DeploymentProviderAccount.user_id == user_uuid)\\n        .order_by(col(DeploymentProviderAccount.created_at).desc())\\n        .offset(offset)\\n    )\\n    if limit is not None:\\n        stmt = stmt.limit(limit)\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def count_provider_accounts(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID | str,\\n) -> int:\\n    from sqlmodel import func\\n\\n    user_uuid = parse_uuid(user_id, field_name=\\\"user_id\\\")\\n    stmt = select(func.count(DeploymentProviderAccount.id)).where(\\n        DeploymentProviderAccount.user_id == user_uuid,\\n    )\\n    return int((await db.exec(stmt)).one() or 0)\\n\\n\\nasync def create_provider_account(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID | str,\\n    name: str,\\n    provider_tenant_id: str | None,\\n    provider_key: str | DeploymentProviderKey,\\n    provider_url: str,\\n    api_key: str,\\n) -> DeploymentProviderAccount:\\n    return await _create_provider_account_internal(\\n        db=db,\\n        user_id=user_id,\\n        name=name,\\n        provider_tenant_id=provider_tenant_id,\\n        provider_key=provider_key,\\n        provider_url=provider_url,\\n        api_key=api_key,\\n    )\\n\\n\\nasync def create_provider_account_from_model(\\n    db: AsyncSession,\\n    *,\\n    provider_account: DeploymentProviderAccount,\\n) -> DeploymentProviderAccount:\\n    return await _create_provider_account_internal(\\n        db=db,\\n        user_id=provider_account.user_id,\\n        name=provider_account.name,\\n        provider_tenant_id=provider_account.provider_tenant_id,\\n        provider_key=provider_account.provider_key,\\n        provider_url=provider_account.provider_url,\\n        api_key=provider_account.api_key,\\n    )\\n\\n\\nasync def _create_provider_account_internal(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID | str,\\n    name: str,\\n    provider_tenant_id: str | None,\\n    provider_key: str | DeploymentProviderKey,\\n    provider_url: str,\\n    api_key: str,\\n) -> DeploymentProviderAccount:\\n    user_uuid = parse_uuid(user_id, field_name=\\\"user_id\\\")\\n\\n    # The model has its own field validators, but pre-checking here gives\\n    # clearer errors and avoids constructing the object.\\n    name_s = _strip_or_raise(name, \\\"name\\\")\\n    provider_key_enum = _coerce_provider_key(provider_key)\\n    provider_url_s = _strip_or_raise(provider_url, \\\"provider_url\\\")\\n\\n    now = datetime.now(timezone.utc)\\n    try:\\n        encrypted_key = _encrypt_api_key(api_key)\\n    except RuntimeError:\\n        await logger.aerror(\\n            \\\"Encryption failed creating provider account (user_id=%s, provider_url=%s)\\\",\\n            user_id,\\n            provider_url,\\n        )\\n        raise\\n    provider_account = DeploymentProviderAccount(\\n        user_id=user_uuid,\\n        name=name_s,\\n        provider_tenant_id=normalize_string_or_none(provider_tenant_id),\\n        provider_key=provider_key_enum,\\n        provider_url=provider_url_s,\\n        api_key=encrypted_key,\\n        created_at=now,\\n        updated_at=now,\\n    )\\n    db.add(provider_account)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        await db.rollback()\\n        await logger.aerror(\\n            \\\"IntegrityError creating provider account (user_id=%s, name=%s, provider_url=%s, provider_tenant_id=%s)\\\",\\n            user_uuid,\\n            name_s,\\n            provider_url_s,\\n            provider_tenant_id,\\n        )\\n        msg = (\\n            f\\\"Provider account already exists \\\"\\n            f\\\"(name={name!r}, provider_url={provider_url!r}, provider_tenant_id={provider_tenant_id!r})\\\"\\n        )\\n        raise ValueError(msg) from exc\\n    await db.refresh(provider_account)\\n    return provider_account\\n\\n\\nasync def update_provider_account(\\n    db: AsyncSession,\\n    *,\\n    provider_account: DeploymentProviderAccount,\\n    name: str | None = None,\\n    provider_tenant_id: str | None = _UNSET,  # type: ignore[assignment]\\n    provider_key: str | DeploymentProviderKey | None = None,\\n    provider_url: str | None = None,\\n    api_key: str | None = None,\\n) -> DeploymentProviderAccount:\\n    requested_provider_key = (\\n        _coerce_provider_key(provider_key) if provider_key is not None else provider_account.provider_key\\n    )\\n    requested_provider_tenant_id = (\\n        normalize_string_or_none(provider_tenant_id)\\n        if provider_tenant_id is not _UNSET\\n        else provider_account.provider_tenant_id\\n    )\\n    requested_provider_url = (\\n        _strip_or_raise(provider_url, \\\"provider_url\\\") if provider_url is not None else provider_account.provider_url\\n    )\\n    ensure_provider_account_identity_immutable(\\n        old_provider_key=provider_account.provider_key,\\n        new_provider_key=requested_provider_key,\\n        old_provider_tenant_id=provider_account.provider_tenant_id,\\n        new_provider_tenant_id=requested_provider_tenant_id,\\n        old_provider_url=provider_account.provider_url,\\n        new_provider_url=requested_provider_url,\\n    )\\n\\n    if name is not None:\\n        provider_account.name = _strip_or_raise(name, \\\"name\\\")\\n    if provider_tenant_id is not _UNSET:\\n        provider_account.provider_tenant_id = normalize_string_or_none(provider_tenant_id)  # type: ignore[arg-type]\\n    if provider_key is not None:\\n        provider_account.provider_key = _coerce_provider_key(provider_key)\\n    if provider_url is not None:\\n        provider_account.provider_url = _strip_or_raise(provider_url, \\\"provider_url\\\")\\n    if api_key is not None:\\n        try:\\n            provider_account.api_key = _encrypt_api_key(api_key)\\n        except RuntimeError:\\n            await logger.aerror(\\n                \\\"Encryption failed updating provider account id=%s\\\",\\n                provider_account.id,\\n            )\\n            raise\\n    provider_account.updated_at = datetime.now(timezone.utc)\\n    db.add(provider_account)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        await db.rollback()\\n        await logger.aerror(\\\"IntegrityError updating provider account id=%s\\\", provider_account.id)\\n        msg = \\\"Provider account update conflicts with an existing record\\\"\\n        raise ValueError(msg) from exc\\n    await db.refresh(provider_account)\\n    return provider_account\\n\\n\\nasync def delete_provider_account(\\n    db: AsyncSession,\\n    *,\\n    provider_account: DeploymentProviderAccount,\\n) -> None:\\n    await db.delete(provider_account)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        await db.rollback()\\n        await logger.aerror(\\\"Failed to delete provider account id=%s\\\", provider_account.id)\\n        msg = f\\\"Failed to delete provider account id={provider_account.id}\\\"\\n        raise ValueError(msg) from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment_provider_account/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aa5f207e3244cdf20c063dc2cd2cea07e13bdf0bc0e327630233e1870a25f819\",\"content\":\"from datetime import datetime\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom pydantic import field_validator, model_validator\\nfrom sqlalchemy import Enum as SQLEnum\\nfrom sqlalchemy import ForeignKey, UniqueConstraint\\nfrom sqlmodel import Column, DateTime, Field, Relationship, SQLModel, func\\nfrom typing_extensions import Self\\n\\nfrom langflow.schema.serialize import UUIDstr\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\nfrom langflow.services.database.models.deployment_provider_account.utils import (\\n    validate_provider_url,\\n    validate_tenant_url_consistency,\\n)\\nfrom langflow.services.database.utils import (\\n    normalize_string_or_none,\\n    validate_non_empty_string,\\n)\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.user.model import User\\n\\n\\nclass DeploymentProviderAccount(SQLModel, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"deployment_provider_account\\\"\\n    __table_args__ = (\\n        UniqueConstraint(\\n            \\\"user_id\\\",\\n            \\\"provider_url\\\",\\n            \\\"provider_tenant_id\\\",\\n            name=\\\"uq_deployment_provider_account_user_url_tenant\\\",\\n        ),\\n        UniqueConstraint(\\n            \\\"user_id\\\",\\n            \\\"provider_key\\\",\\n            \\\"name\\\",\\n            name=\\\"uq_deployment_provider_account_provider_name\\\",\\n        ),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True)\\n    )\\n    # provider_tenant_id participates in a unique constraint. When NULL,\\n    # SQL-standard databases (PostgreSQL, SQLite) treat NULL != NULL in unique\\n    # constraints, so multiple rows with the same (user_id, provider_url) are\\n    # allowed when provider_tenant_id is NULL.  This is intentional: a provider\\n    # may not require a tenant/organization identifier.\\n    provider_tenant_id: str | None = Field(default=None, index=True)\\n    # The DB-level ``deployment_provider_key_enum`` constraint is defined\\n    # by a Langflow alembic migration.  The enum is Langflow-owned (see\\n    # ``DeploymentProviderKey`` above); LFX uses plain strings for adapter\\n    # registry keys and does not reference this enum.\\n    #\\n    # To add a new value to ``deployment_provider_key_enum``:\\n    #   1. Add the member to ``DeploymentProviderKey`` in this module.\\n    #   2. Register the corresponding adapter in LFX and mapper in Langflow.\\n    #   3. Create a Langflow alembic migration that runs:\\n    #        op.execute(\\n    #            \\\"ALTER TYPE deployment_provider_key_enum ADD VALUE '<new>'\\\"\\n    #        )\\n    #      For SQLite (dev/test) this is a no-op; the CHECK constraint is\\n    #      recreated automatically by ``batch_alter_table``.\\n    #   4. Deploy the migration before any code writes the new value.\\n    #\\n    # Removing or renaming a value is **strongly discouraged**.  Existing\\n    # rows reference the old string; renaming silently breaks every read\\n    # of those rows and invalidates any provider accounts using that key.\\n    # If absolutely necessary:\\n    #   1. Create a migration that (a) updates existing rows to the\\n    #      replacement value, then (b) recreates the enum type without\\n    #      the old value (PostgreSQL requires CREATE TYPE \u2026 / ALTER COLUMN\\n    #      \u2026 TYPE \u2026 USING \u2026; SQLite uses ``batch_alter_table``).\\n    #   2. Update or remove the member in ``DeploymentProviderKey``.\\n    #   3. Update the adapter registry key and mapper registration to\\n    #      match the new value.\\n    provider_key: DeploymentProviderKey = Field(\\n        sa_column=Column(\\n            SQLEnum(\\n                DeploymentProviderKey,\\n                name=\\\"deployment_provider_key_enum\\\",\\n                values_callable=lambda enum: [member.value for member in enum],\\n            ),\\n            nullable=False,\\n            index=True,\\n        ),\\n    )\\n    name: str = Field(\\n        description=\\\"User-chosen display name, unique per user within a provider_key (e.g. 'staging', 'prod').\\\"\\n    )\\n    provider_url: str = Field(description=\\\"Provider service URL used for deployment crud in the account.\\\")\\n    # MUST be stored encrypted; the CRUD layer encrypts via auth_utils before writing\\n    # and the Read schema intentionally excludes this field.\\n    api_key: str = Field(description=\\\"Provider credential material. Stored encrypted; never returned in API responses.\\\")\\n    created_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=False),\\n    )\\n    updated_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False),\\n    )\\n\\n    user: \\\"User\\\" = Relationship(back_populates=\\\"deployment_provider_accounts\\\")\\n    deployments: list[\\\"Deployment\\\"] = Relationship(\\n        back_populates=\\\"deployment_provider_account\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete, delete-orphan\\\"},\\n    )\\n\\n    @field_validator(\\\"provider_tenant_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def normalize_tenant_id(cls, v: str | None) -> str | None:\\n        return normalize_string_or_none(v)\\n\\n    @field_validator(\\\"name\\\", \\\"api_key\\\")\\n    @classmethod\\n    def validate_non_empty(cls, v: str, info: object) -> str:\\n        return validate_non_empty_string(v, info)\\n\\n    @field_validator(\\\"provider_url\\\")\\n    @classmethod\\n    def validate_url(cls, v: str, info: object) -> str:\\n        return validate_provider_url(v, info)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_tenant_consistency(self) -> Self:\\n        validate_tenant_url_consistency(self.provider_url, self.provider_tenant_id, self.provider_key)\\n        return self\\n\\n\\nclass DeploymentProviderAccountRead(SQLModel):\\n    id: UUID\\n    user_id: UUID\\n    name: str\\n    provider_tenant_id: str | None = None\\n    provider_key: DeploymentProviderKey\\n    provider_url: str\\n    created_at: datetime\\n    updated_at: datetime\\n    # api_key intentionally omitted -- stored encrypted, never serialize credentials to API responses\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment_provider_account/schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f0341edb94d85a5f59495c05594843fc67ef4dfee75898541ac0312b990da00\",\"content\":\"\\\"\\\"\\\"Schemas for the deployment_provider_account package.\\n\\nKept separate from ``model.py`` so that modules like ``utils.py`` can\\nimport these types without pulling in SQLModel / SQLAlchemy and without\\ncreating circular dependencies.\\n\\\"\\\"\\\"\\n\\nfrom enum import Enum\\n\\n\\nclass DeploymentProviderKey(str, Enum):\\n    \\\"\\\"\\\"Deployment provider identifiers recognised by Langflow.\\n\\n    Each member value must match the adapter registry key used by\\n    ``get_deployment_adapter(adapter_key)`` in LFX and the corresponding\\n    mapper registration in the Langflow mapper registry.\\n    \\\"\\\"\\\"\\n\\n    WATSONX_ORCHESTRATE = \\\"watsonx-orchestrate\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/deployment_provider_account/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4af4f5d15c3225edc30436e0657766fb9fa2aeea739d5479ec04b0d699da272d\",\"content\":\"\\\"\\\"\\\"Validation helpers for deployment provider account fields.\\n\\nURL validation enforces two things:\\n\\n1. **Structure** \u2014 :func:`validate_provider_url` ensures the URL is well-formed,\\n   uses HTTPS, contains no embedded credentials, and is normalised.  This runs\\n   as a Pydantic field validator on every URL, regardless of provider.\\n\\n2. **Hostname allowlist** \u2014 :func:`check_provider_url_allowed` restricts the URL\\n   hostname to domains known to belong to the given provider (e.g. ``*.ibm.com``\\n   for WatsonX Orchestrate).  Providers that are not registered in the allowlist\\n   are rejected (closed-by-default).  The check is called from the API route\\n   *before* ``verify_credentials`` so that a spoofed endpoint is blocked before\\n   any credential exchange occurs.\\n\\nTenant/URL consistency\\n----------------------\\n:func:`extract_tenant_from_url` derives the provider tenant identifier from\\na URL using per-provider extraction logic.  :func:`validate_tenant_url_consistency`\\nverifies that a stored ``provider_tenant_id`` matches what the URL implies.\\nBoth are used by the ``DeploymentProviderAccount`` model validator and the\\ndeployment mapper layer.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom urllib.parse import urlparse, urlunparse\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\n\\n_ALLOWED_URL_SCHEMES = frozenset({\\\"https\\\"})\\n_MAX_URL_LENGTH = 2048\\n\\n\\ndef validate_provider_url(v: str, info: object | None = None, *, field_name: str | None = None) -> str:\\n    \\\"\\\"\\\"Validate and normalize a provider URL.\\n\\n    Enforces HTTPS-only, rejects embedded credentials, validates the URL\\n    structure, and normalises scheme + host to lowercase.\\n\\n    *info* is the Pydantic ``ValidationInfo`` passed by field validators.\\n    When calling outside a Pydantic context, pass *field_name* directly\\n    instead.\\n    \\\"\\\"\\\"\\n    field = field_name or getattr(info, \\\"field_name\\\", None) or \\\"Field\\\"\\n    stripped = v.strip()\\n    if not stripped:\\n        msg = f\\\"{field} must not be empty\\\"\\n        raise ValueError(msg)\\n\\n    if len(stripped) > _MAX_URL_LENGTH:\\n        msg = f\\\"{field} exceeds maximum length of {_MAX_URL_LENGTH}\\\"\\n        raise ValueError(msg)\\n\\n    parsed = urlparse(stripped)\\n\\n    if parsed.scheme.lower() not in _ALLOWED_URL_SCHEMES:\\n        msg = f\\\"{field} must use the https scheme\\\"\\n        raise ValueError(msg)\\n\\n    if parsed.username is not None or parsed.password is not None:\\n        msg = f\\\"{field} must not contain user credentials\\\"\\n        raise ValueError(msg)\\n\\n    hostname = parsed.hostname\\n    if not hostname:\\n        msg = f\\\"{field} must contain a valid hostname\\\"\\n        raise ValueError(msg)\\n\\n    scheme = parsed.scheme.lower()\\n    netloc = parsed.netloc.lower()\\n    path = parsed.path.rstrip(\\\"/\\\") or \\\"/\\\"\\n    return urlunparse((scheme, netloc, path, parsed.params, parsed.query, parsed.fragment))\\n\\n\\ndef validate_provider_url_optional(v: str | None, info: object) -> str | None:\\n    \\\"\\\"\\\"Like :func:`validate_provider_url` but allows ``None`` (skip).\\\"\\\"\\\"\\n    if v is None:\\n        return None\\n    return validate_provider_url(v, info)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Per-provider hostname allowlist\\n# ---------------------------------------------------------------------------\\n# Each tuple contains hostname suffixes that the provider is known to operate\\n# under.  A URL whose hostname ends with any listed suffix is accepted; all\\n# others are rejected.\\n#\\n# When onboarding a new provider, add an entry here BEFORE the provider can\\n# be used \u2014 the check is closed-by-default.\\n\\n_PROVIDER_HOSTNAME_ALLOWLIST: dict[DeploymentProviderKey, tuple[str, ...]] = {\\n    # https://www.ibm.com/docs/en/watsonx/watson-orchestrate/base?topic=api-getting-endpoint\\n    DeploymentProviderKey.WATSONX_ORCHESTRATE: (\\\".ibm.com\\\",),  # note: on-prem is not supported\\n}\\n\\n\\ndef check_provider_url_allowed(url: str, provider_key: str | DeploymentProviderKey) -> None:\\n    \\\"\\\"\\\"Raise ``ValueError`` if *url* hostname is not allowed for *provider_key*.\\n\\n    Every provider must have an entry in the allowlist.  If a provider key\\n    is not registered, the URL is rejected (closed-by-default).\\n    \\\"\\\"\\\"\\n    key = DeploymentProviderKey(provider_key)\\n    suffixes = _PROVIDER_HOSTNAME_ALLOWLIST.get(key)\\n    if suffixes is None:\\n        msg = f\\\"No hostname allowlist configured for provider '{key.value}'\\\"\\n        raise ValueError(msg)\\n\\n    hostname = urlparse(url).hostname or \\\"\\\"\\n    if any(hostname == s.lstrip(\\\".\\\") or hostname.endswith(s) for s in suffixes):\\n        return\\n\\n    msg = f\\\"URL hostname '{hostname}' is not allowed for provider '{key.value}'\\\"\\n    raise ValueError(msg)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Per-provider tenant extraction from URL\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _extract_wxo_tenant_from_url(url: str) -> str | None:\\n    \\\"\\\"\\\"Extract the tenant/instance id from a WXO URL path.\\n\\n    WXO URLs end with ``/instances/{tenant_id}`` \u2014 the tenant must be the\\n    **last** path segment.  Returns ``None`` if the URL does not match this\\n    pattern (no ``instances`` segment, nothing after it, or extra trailing\\n    segments).\\n\\n    See https://www.ibm.com/docs/en/watsonx/watson-orchestrate/base?topic=api-getting-endpoint\\n    \\\"\\\"\\\"\\n    parsed = urlparse(url)\\n    path_segments = [segment for segment in parsed.path.split(\\\"/\\\") if segment]\\n    try:\\n        instances_index = path_segments.index(\\\"instances\\\")\\n    except ValueError:\\n        return None\\n    tenant_index = instances_index + 1\\n    if tenant_index >= len(path_segments):\\n        return None\\n    # Tenant must be the terminal segment \u2014 reject URLs like /instances/not-an-id/random-path\\n    if tenant_index != len(path_segments) - 1:\\n        return None\\n    return path_segments[tenant_index].strip() or None\\n\\n\\n_PROVIDER_TENANT_EXTRACTORS: dict[DeploymentProviderKey, Callable[[str], str | None]] = {\\n    DeploymentProviderKey.WATSONX_ORCHESTRATE: _extract_wxo_tenant_from_url,\\n}\\n\\n\\ndef extract_tenant_from_url(provider_url: str, provider_key: str | DeploymentProviderKey) -> str | None:\\n    \\\"\\\"\\\"Derive the provider tenant identifier from a URL.\\n\\n    Uses the per-provider extractor registered in\\n    ``_PROVIDER_TENANT_EXTRACTORS``.  Returns ``None`` for providers without\\n    a registered extractor (tenant is not embedded in the URL).\\n    \\\"\\\"\\\"\\n    key = DeploymentProviderKey(provider_key)\\n    extractor = _PROVIDER_TENANT_EXTRACTORS.get(key)\\n    if extractor is None:\\n        return None\\n    return extractor(provider_url)\\n\\n\\ndef validate_tenant_url_consistency(\\n    provider_url: str,\\n    provider_tenant_id: str | None,\\n    provider_key: str | DeploymentProviderKey,\\n) -> None:\\n    \\\"\\\"\\\"Raise ``ValueError`` if *provider_tenant_id* contradicts the URL.\\n\\n    If the URL implies a tenant (via the per-provider extractor) and\\n    *provider_tenant_id* is set to a **different** value, the pair is\\n    inconsistent and must be rejected.  When either value is ``None``\\n    the check passes \u2014 the mapper is responsible for derivation.\\n    \\\"\\\"\\\"\\n    url_tenant = extract_tenant_from_url(provider_url, provider_key)\\n    if url_tenant is None or provider_tenant_id is None:\\n        return\\n    if url_tenant != provider_tenant_id:\\n        msg = (\\n            f\\\"provider_tenant_id '{provider_tenant_id}' does not match \\\"\\n            f\\\"the tenant '{url_tenant}' embedded in provider_url\\\"\\n        )\\n        raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/file/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d55bd1d1b16b55e0dffa55705d66b6613d276ce9ef91dc426dc31c48038d94fb\",\"content\":\"from .model import File\\n\\n__all__ = [\\n    \\\"File\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/file/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0127254bb0d2ff2f9f8bb4dd662e1d0d637ad548c4ae8d5b54bfe0dbcde84f53\",\"content\":\"from uuid import UUID\\n\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.file.model import File\\n\\n\\nasync def get_file_by_id(db: AsyncSession, file_id: UUID) -> File | None:\\n    if isinstance(file_id, str):\\n        file_id = UUID(file_id)\\n    stmt = select(File).where(File.id == file_id)\\n\\n    return (await db.exec(stmt)).first()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/file/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"145c1e093a0a3ef95806d83b8ee812db7ead69f09203be8bd896e8863b799094\",\"content\":\"from datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import ForeignKey\\nfrom sqlmodel import Column, Field, Relationship, SQLModel, UniqueConstraint\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User\\n\\n\\nclass File(SQLModel, table=True):  # type: ignore[call-arg]\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUID = Field(sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False))\\n    user: \\\"User\\\" = Relationship(back_populates=\\\"files\\\")\\n    name: str = Field(nullable=False)\\n    path: str = Field(nullable=False)\\n    size: int = Field(nullable=False)\\n    provider: str | None = Field(default=None)\\n    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    updated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n\\n    __table_args__ = (UniqueConstraint(\\\"name\\\", \\\"user_id\\\"),)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"409f1b0423957e9b0e2135e237dd9def205d45d4bd6a9a9eb6c86ffa38c35659\",\"content\":\"from .model import Flow, FlowCreate, FlowRead, FlowUpdate\\n\\n__all__ = [\\\"Flow\\\", \\\"FlowCreate\\\", \\\"FlowRead\\\", \\\"FlowUpdate\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow/guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f9e8380fe2305180016703510cd90a48827a18fd208d08bf3828346d758f5b59\",\"content\":\"\\\"\\\"\\\"Application-level guards for locked flow mutations.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Mapping\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.models.flow.model import Flow\\n\\nLOCKED_FLOW_DETAIL = \\\"Flow is locked. Unlock it before making changes.\\\"\\n\\n\\nclass LockedFlowError(RuntimeError):\\n    \\\"\\\"\\\"Raised when a mutation targets a locked flow.\\\"\\\"\\\"\\n\\n\\nasync def lock_flow_for_update(session: AsyncSession, flow: Flow) -> None:\\n    \\\"\\\"\\\"Refresh *flow* while holding its database row lock until transaction end.\\\"\\\"\\\"\\n    await session.refresh(flow, with_for_update=True)\\n\\n\\ndef ensure_flow_unlocked(flow: Flow) -> None:\\n    \\\"\\\"\\\"Raise when *flow* is currently locked.\\\"\\\"\\\"\\n    if getattr(flow, \\\"locked\\\", False) is True:\\n        raise LockedFlowError(LOCKED_FLOW_DETAIL)\\n\\n\\ndef ensure_flow_update_allowed(flow: Flow, update_data: Mapping[str, Any]) -> None:\\n    \\\"\\\"\\\"Allow updates to unlocked flows and safe updates to locked flows.\\n\\n    API clients commonly send the full current flow when toggling the lock. We\\n    therefore compare payload values with the persisted row and allow no-op\\n    requests or requests where ``locked=False`` is the only effective change.\\n    \\\"\\\"\\\"\\n    if getattr(flow, \\\"locked\\\", False) is not True:\\n        return\\n\\n    changed_fields = {\\n        field_name for field_name, new_value in update_data.items() if getattr(flow, field_name, None) != new_value\\n    }\\n    if not changed_fields or (changed_fields == {\\\"locked\\\"} and update_data.get(\\\"locked\\\") is False):\\n        return\\n\\n    raise LockedFlowError(LOCKED_FLOW_DETAIL)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cf94abf394b9081f1420943fd8a6c347d6af8fecf2d6a64e23f23fe9a2231b98\",\"content\":\"# Path: src/backend/langflow/services/database/models/flow/model.py\\n\\nimport re\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING, Optional\\nfrom uuid import UUID, uuid4\\n\\nimport emoji\\nfrom emoji import purely_emoji\\nfrom lfx.log.logger import logger\\nfrom pydantic import BaseModel, ValidationInfo, field_serializer, field_validator\\nfrom sqlalchemy import Boolean, Text, UniqueConstraint, false, text\\nfrom sqlalchemy import Enum as SQLEnum\\nfrom sqlmodel import JSON, Column, Field, Relationship, SQLModel\\n\\nfrom langflow.schema.data import Data\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.folder.model import Folder\\n    from langflow.services.database.models.user.model import User\\n\\nHEX_COLOR_LENGTH = 7\\n\\n_ENDPOINT_NAME_RE = re.compile(r\\\"^[a-zA-Z0-9_-]+$\\\")\\n\\n\\ndef _validate_endpoint_name_value(v: str | None) -> str | None:\\n    \\\"\\\"\\\"Validate that an endpoint name contains only safe URL characters.\\n\\n    Raises ``ValueError`` on invalid input \u2014 callers at the HTTP layer\\n    should catch and translate to an appropriate HTTP response.\\n    \\\"\\\"\\\"\\n    if v is not None:\\n        if not isinstance(v, str):\\n            msg = \\\"Endpoint name must be a string\\\"\\n            raise ValueError(msg)\\n        if not _ENDPOINT_NAME_RE.match(v):\\n            msg = \\\"Endpoint name must contain only letters, numbers, hyphens, and underscores\\\"\\n            raise ValueError(msg)\\n    return v\\n\\n\\nclass AccessTypeEnum(str, Enum):\\n    PRIVATE = \\\"PRIVATE\\\"\\n    PUBLIC = \\\"PUBLIC\\\"\\n\\n\\nclass FlowType(str, Enum):\\n    # Extensible: new kinds can be added without a breaking change. Lowercase\\n    # values so the stored string matches the wire value (see values_callable).\\n    WORKFLOW = \\\"workflow\\\"\\n    AGENT = \\\"agent\\\"\\n\\n\\nclass FlowBase(SQLModel):\\n    # Supresses warnings during migrations\\n    __mapper_args__ = {\\\"confirm_deleted_rows\\\": False}\\n\\n    name: str = Field(index=True)\\n    description: str | None = Field(default=None, sa_column=Column(Text, index=True, nullable=True))\\n    icon: str | None = Field(default=None, nullable=True)\\n    icon_bg_color: str | None = Field(default=None, nullable=True)\\n    gradient: str | None = Field(default=None, nullable=True)\\n    data: dict | None = Field(default=None, nullable=True)\\n    is_component: bool | None = Field(default=False, nullable=True)\\n    updated_at: datetime | None = Field(default_factory=lambda: datetime.now(timezone.utc), nullable=True)\\n    webhook: bool | None = Field(default=False, nullable=True, description=\\\"Can be used on the webhook endpoint\\\")\\n    endpoint_name: str | None = Field(default=None, nullable=True, index=True)\\n    tags: list[str] | None = None\\n    locked: bool | None = Field(default=False, nullable=True)\\n    mcp_enabled: bool | None = Field(default=False, nullable=True, description=\\\"Can be exposed in the MCP server\\\")\\n    action_name: str | None = Field(\\n        default=None, nullable=True, description=\\\"The name of the action associated with the flow\\\"\\n    )\\n    action_description: str | None = Field(\\n        default=None,\\n        sa_column=Column(Text, nullable=True),\\n        description=\\\"The description of the action associated with the flow\\\",\\n    )\\n    access_type: AccessTypeEnum = Field(\\n        default=AccessTypeEnum.PRIVATE,\\n        sa_column=Column(\\n            SQLEnum(\\n                AccessTypeEnum,\\n                name=\\\"access_type_enum\\\",\\n                values_callable=lambda enum: [member.value for member in enum],\\n            ),\\n            nullable=False,\\n            server_default=text(\\\"'PRIVATE'\\\"),\\n        ),\\n    )\\n    flow_type: FlowType = Field(\\n        default=FlowType.WORKFLOW,\\n        sa_column=Column(\\n            SQLEnum(\\n                FlowType,\\n                name=\\\"flow_type_enum\\\",\\n                values_callable=lambda enum: [member.value for member in enum],\\n            ),\\n            nullable=False,\\n            server_default=text(\\\"'workflow'\\\"),\\n        ),\\n        description=\\\"Whether the flow is a plain workflow or an agent (publishable over A2A)\\\",\\n    )\\n    a2a_enabled: bool | None = Field(\\n        default=False,\\n        sa_column=Column(Boolean, nullable=True, server_default=false()),\\n        description=\\\"Can be exposed as an A2A agent (only meaningful when flow_type=agent)\\\",\\n    )\\n    a2a_card_overrides: dict | None = Field(\\n        default=None,\\n        sa_column=Column(JSON, nullable=True),\\n        description=\\\"User overrides for the generated A2A agent card (skill description, examples, tags)\\\",\\n    )\\n\\n    @field_validator(\\\"endpoint_name\\\")\\n    @classmethod\\n    def validate_endpoint_name(cls, v):\\n        return _validate_endpoint_name_value(v)\\n\\n    @field_validator(\\\"icon_bg_color\\\")\\n    @classmethod\\n    def validate_icon_bg_color(cls, v):\\n        if v is not None and not isinstance(v, str):\\n            msg = \\\"Icon background color must be a string\\\"\\n            raise ValueError(msg)\\n        # validate that is is a hex color\\n        if v and not v.startswith(\\\"#\\\"):\\n            msg = \\\"Icon background color must start with #\\\"\\n            raise ValueError(msg)\\n\\n        # validate that it is a valid hex color\\n        if v and len(v) != HEX_COLOR_LENGTH:\\n            msg = \\\"Icon background color must be 7 characters long\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n    @field_validator(\\\"icon\\\")\\n    @classmethod\\n    def validate_icon_atr(cls, v):\\n        #   const emojiRegex = /\\\\p{Emoji}/u;\\n        # const isEmoji = emojiRegex.test(data?.node?.icon!);\\n        # emoji pattern in Python\\n        if v is None:\\n            return v\\n        # we are going to use the emoji library to validate the emoji\\n        # emojis can be defined using the :emoji_name: syntax\\n\\n        if not v.startswith(\\\":\\\") and not v.endswith(\\\":\\\"):\\n            return v\\n        if not v.startswith(\\\":\\\") or not v.endswith(\\\":\\\"):\\n            # emoji should have both starting and ending colons\\n            # so if one of them is missing, we will raise\\n            msg = f\\\"Invalid emoji. {v} is not a valid emoji.\\\"\\n            raise ValueError(msg)\\n\\n        emoji_value = emoji.emojize(v, variant=\\\"emoji_type\\\")\\n        if v == emoji_value:\\n            logger.warning(\\\"Invalid emoji. %s is not a valid emoji.\\\", v)\\n        icon = emoji_value\\n\\n        if purely_emoji(icon):\\n            # this is indeed an emoji\\n            return icon\\n        # otherwise it should be a valid lucide icon\\n        if v is not None and not isinstance(v, str):\\n            msg = \\\"Icon must be a string\\\"\\n            raise ValueError(msg)\\n        # is should be lowercase and contain only letters and hyphens\\n        if v and not v.islower():\\n            msg = \\\"Icon must be lowercase\\\"\\n            raise ValueError(msg)\\n        if v and not v.replace(\\\"-\\\", \\\"\\\").isalpha():\\n            msg = \\\"Icon must contain only letters and hyphens\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n    @field_validator(\\\"data\\\")\\n    @classmethod\\n    def validate_json(cls, v):\\n        if not v:\\n            return v\\n        if not isinstance(v, dict):\\n            msg = \\\"Flow must be a valid JSON\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n\\n        # data must contain nodes and edges\\n        if \\\"nodes\\\" not in v:\\n            msg = \\\"Flow must have nodes\\\"\\n            raise ValueError(msg)\\n        if \\\"edges\\\" not in v:\\n            msg = \\\"Flow must have edges\\\"\\n            raise ValueError(msg)\\n\\n        return v\\n\\n    # updated_at can be serialized to JSON\\n    @field_serializer(\\\"updated_at\\\")\\n    def serialize_datetime(self, value):\\n        if isinstance(value, datetime):\\n            # I'm getting 2024-05-29T17:57:17.631346\\n            # and I want 2024-05-29T17:57:17-05:00\\n            value = value.replace(microsecond=0)\\n            if value.tzinfo is None:\\n                value = value.replace(tzinfo=timezone.utc)\\n            return value.isoformat()\\n        return value\\n\\n    @field_validator(\\\"updated_at\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_dt(cls, v):\\n        if v is None:\\n            return v\\n        if isinstance(v, datetime):\\n            return v\\n\\n        return datetime.fromisoformat(v)\\n\\n\\nclass Flow(FlowBase, table=True):  # type: ignore[call-arg]\\n    id: UUID = Field(default_factory=uuid4, primary_key=True, unique=True)\\n    data: dict | None = Field(default=None, sa_column=Column(JSON))\\n    user_id: UUID | None = Field(index=True, foreign_key=\\\"user.id\\\", nullable=True)\\n    user: \\\"User\\\" = Relationship(back_populates=\\\"flows\\\")\\n    icon: str | None = Field(default=None, nullable=True)\\n    tags: list[str] | None = Field(sa_column=Column(JSON), default=[])\\n    locked: bool | None = Field(default=False, nullable=True)\\n    folder_id: UUID | None = Field(default=None, foreign_key=\\\"folder.id\\\", nullable=True, index=True)\\n    workspace_id: UUID | None = Field(default=None, nullable=True, index=True)\\n    fs_path: str | None = Field(default=None, nullable=True)\\n    folder: Optional[\\\"Folder\\\"] = Relationship(back_populates=\\\"flows\\\")\\n\\n    def to_data(self):\\n        serialized = self.model_dump()\\n        data = {\\n            \\\"id\\\": serialized.pop(\\\"id\\\"),\\n            \\\"data\\\": serialized.pop(\\\"data\\\"),\\n            \\\"name\\\": serialized.pop(\\\"name\\\"),\\n            \\\"description\\\": serialized.pop(\\\"description\\\"),\\n            \\\"updated_at\\\": serialized.pop(\\\"updated_at\\\"),\\n            \\\"folder_id\\\": serialized.pop(\\\"folder_id\\\"),\\n        }\\n        return Data(data=data)\\n\\n    __table_args__ = (\\n        UniqueConstraint(\\\"user_id\\\", \\\"name\\\", name=\\\"unique_flow_name\\\"),\\n        UniqueConstraint(\\\"user_id\\\", \\\"endpoint_name\\\", name=\\\"unique_flow_endpoint_name\\\"),\\n    )\\n\\n\\nclass FlowCreate(FlowBase):\\n    # Optional stable ID.  When present on upload, the flow is upserted\\n    # (created with that ID, or updated if the ID already belongs to the\\n    # current user).  Flows without an id get a generated UUID \u2014 backward\\n    # compatible with all existing import paths.\\n    id: UUID | None = None\\n    user_id: UUID | None = None\\n    folder_id: UUID | None = None\\n    workspace_id: UUID | None = None\\n    fs_path: str | None = None\\n\\n\\nclass FlowRead(FlowBase):\\n    id: UUID\\n    user_id: UUID | None = Field()\\n    folder_id: UUID | None = Field()\\n    workspace_id: UUID | None = Field(default=None)\\n    tags: list[str] | None = Field(None, description=\\\"The tags of the flow\\\")\\n    name_key: str | None = Field(None, description=\\\"Stable i18n key derived from the original English name\\\")\\n\\n\\nclass FlowHeader(BaseModel):\\n    \\\"\\\"\\\"Model representing a header for a flow - Without the data.\\\"\\\"\\\"\\n\\n    id: UUID = Field(description=\\\"Unique identifier for the flow\\\")\\n    name: str = Field(description=\\\"The name of the flow\\\")\\n    folder_id: UUID | None = Field(\\n        None,\\n        description=\\\"The ID of the folder containing the flow. None if not associated with a folder\\\",\\n    )\\n    is_component: bool | None = Field(None, description=\\\"Flag indicating whether the flow is a component\\\")\\n    endpoint_name: str | None = Field(None, description=\\\"The name of the endpoint associated with this flow\\\")\\n    description: str | None = Field(None, description=\\\"A description of the flow\\\")\\n    data: dict | None = Field(None, description=\\\"The data of the component, if is_component is True\\\")\\n    access_type: AccessTypeEnum | None = Field(None, description=\\\"The access type of the flow\\\")\\n    tags: list[str] | None = Field(None, description=\\\"The tags of the flow\\\")\\n    mcp_enabled: bool | None = Field(None, description=\\\"Flag indicating whether the flow is exposed in the MCP server\\\")\\n    flow_type: FlowType | None = Field(None, description=\\\"Whether the flow is a plain workflow or an agent\\\")\\n    a2a_enabled: bool | None = Field(None, description=\\\"Flag indicating whether the flow is exposed as an A2A agent\\\")\\n    a2a_card_overrides: dict | None = Field(None, description=\\\"User overrides for the served A2A agent card\\\")\\n    action_name: str | None = Field(None, description=\\\"The name of the action associated with the flow\\\")\\n    action_description: str | None = Field(None, description=\\\"The description of the action associated with the flow\\\")\\n\\n    @field_validator(\\\"data\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_header(cls, value: dict, info: ValidationInfo):\\n        if not info.data[\\\"is_component\\\"]:\\n            return None\\n        return value\\n\\n\\nclass FlowUpdate(SQLModel):\\n    name: str | None = None\\n    description: str | None = None\\n    data: dict | None = None\\n    folder_id: UUID | None = None\\n    workspace_id: UUID | None = None\\n    endpoint_name: str | None = None\\n    mcp_enabled: bool | None = None\\n    locked: bool | None = None\\n    action_name: str | None = None\\n    action_description: str | None = None\\n    access_type: AccessTypeEnum | None = None\\n    flow_type: FlowType | None = None\\n    a2a_enabled: bool | None = None\\n    a2a_card_overrides: dict | None = None\\n    fs_path: str | None = None\\n\\n    @field_validator(\\\"endpoint_name\\\")\\n    @classmethod\\n    def validate_endpoint_name(cls, v):\\n        return _validate_endpoint_name_value(v)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"21e8ac66329a394a7811eac1af9a00721385918aef8c6d490dab5e2e96bde0f8\",\"content\":\"from enum import Enum\\n\\n\\nclass Tags(str, Enum):\\n    CHATBOTS = \\\"chatbots\\\"\\n    AGENTS = \\\"agents\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c16e3df10383862581325f755453593dcdb2625b5789998e00a3a8421f2d7275\",\"content\":\"from langflow.utils.version import get_version_info\\n\\nfrom .model import Flow\\n\\n\\ndef get_webhook_component_in_flow(flow_data: dict):\\n    \\\"\\\"\\\"Get webhook component in flow data.\\\"\\\"\\\"\\n    if \\\"nodes\\\" in flow_data:\\n        for node in flow_data.get(\\\"nodes\\\", []):\\n            if \\\"Webhook\\\" in node.get(\\\"id\\\"):\\n                return node\\n    return None\\n\\n\\ndef get_all_webhook_components_in_flow(flow_data: dict | None):\\n    \\\"\\\"\\\"Get all webhook components in flow data.\\\"\\\"\\\"\\n    if not flow_data:\\n        return []\\n    return [node for node in flow_data.get(\\\"nodes\\\", []) if \\\"Webhook\\\" in node.get(\\\"id\\\")]\\n\\n\\ndef get_components_versions(flow: Flow):\\n    versions: dict[str, str] = {}\\n    if flow.data is None:\\n        return versions\\n    nodes = flow.data.get(\\\"nodes\\\", [])\\n    for node in nodes:\\n        data = node.get(\\\"data\\\", {})\\n        data_node = data.get(\\\"node\\\", {})\\n        if \\\"lf_version\\\" in data_node:\\n            versions[node[\\\"id\\\"]] = data_node[\\\"lf_version\\\"]\\n    return versions\\n\\n\\ndef get_outdated_components(flow: Flow):\\n    component_versions = get_components_versions(flow)\\n    lf_version = get_version_info()[\\\"version\\\"]\\n    outdated_components = []\\n    for key, value in component_versions.items():\\n        if value != lf_version:\\n            outdated_components.append(key)\\n    return outdated_components\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"52d2074ff07ec8d30fcc129179f56904a10b2cc43160c3dc8fe54071c7b33e1f\",\"content\":\"from .exceptions import (\\n    FlowVersionConflictError,\\n    FlowVersionDeployedError,\\n    FlowVersionError,\\n    FlowVersionNotFoundError,\\n    FlowVersionSerializationError,\\n)\\nfrom .model import FlowVersion, FlowVersionCreate, FlowVersionListResponse, FlowVersionRead, FlowVersionReadWithData\\n\\n__all__ = [\\n    \\\"FlowVersion\\\",\\n    \\\"FlowVersionConflictError\\\",\\n    \\\"FlowVersionCreate\\\",\\n    \\\"FlowVersionDeployedError\\\",\\n    \\\"FlowVersionError\\\",\\n    \\\"FlowVersionListResponse\\\",\\n    \\\"FlowVersionNotFoundError\\\",\\n    \\\"FlowVersionRead\\\",\\n    \\\"FlowVersionReadWithData\\\",\\n    \\\"FlowVersionSerializationError\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d43f89431d7f8077f559b1d8709b7b73f81895a9218dd573507f78d7f17cc37\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log import logger\\nfrom sqlalchemy.exc import IntegrityError, SQLAlchemyError\\nfrom sqlmodel import col, delete, func, select, update\\n\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.flow_version.exceptions import (\\n    FlowVersionConflictError,\\n    FlowVersionDeployedError,\\n    FlowVersionNotFoundError,\\n)\\nfrom langflow.services.database.models.flow_version.model import (\\n    FlowVersion,\\n)\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.deps import get_settings_service\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\nMAX_VERSION_RETRIES = 3\\nMAX_VERSION_ID_FILTER_SIZE = 50\\n\\n\\nasync def get_next_version_number(session: AsyncSession, flow_id: UUID) -> int:\\n    result = await session.exec(select(func.max(FlowVersion.version_number)).where(FlowVersion.flow_id == flow_id))\\n    current_max = result.one()\\n    return (current_max or 0) + 1\\n\\n\\nasync def create_flow_version_entry(\\n    session: AsyncSession,\\n    flow_id: UUID,\\n    user_id: UUID,\\n    data: dict | None,\\n    description: str | None = None,\\n) -> FlowVersion:\\n    \\\"\\\"\\\"Create a version entry with retry on version number collision.\\n\\n    NOTE: This function does NOT verify that user_id owns the flow.\\n    Callers are responsible for checking ownership before calling this.\\n    \\\"\\\"\\\"\\n    entry: FlowVersion | None = None\\n    for attempt in range(MAX_VERSION_RETRIES):\\n        version_number = await get_next_version_number(session, flow_id)\\n        entry = FlowVersion(\\n            flow_id=flow_id,\\n            user_id=user_id,\\n            data=data,\\n            description=description,\\n            version_number=version_number,\\n        )\\n        try:\\n            async with session.begin_nested():\\n                session.add(entry)\\n                await session.flush()\\n                await session.refresh(entry)\\n            break\\n        except IntegrityError as exc:\\n            if \\\"unique_flow_version_number\\\" not in str(exc).lower():\\n                raise  # Not a version collision \u2014 don't retry\\n            if attempt == MAX_VERSION_RETRIES - 1:\\n                msg = (\\n                    f\\\"Failed to create version entry for flow {flow_id} after \\\"\\n                    f\\\"{MAX_VERSION_RETRIES} retries due to version number conflicts\\\"\\n                )\\n                raise FlowVersionConflictError(msg) from exc\\n            await logger.awarning(\\n                \\\"Version number collision for flow %s (attempt %d/%d), retrying\\\",\\n                flow_id,\\n                attempt + 1,\\n                MAX_VERSION_RETRIES,\\n            )\\n            entry = None\\n            continue\\n\\n    if entry is None:\\n        msg = (\\n            f\\\"Failed to create version entry for flow {flow_id} after \\\"\\n            f\\\"{MAX_VERSION_RETRIES} retries due to version number conflicts\\\"\\n        )\\n        raise FlowVersionConflictError(msg)\\n\\n    # Prune oldest non-deployed entries beyond the configured limit.\\n    # Versions attached to deployments are excluded from pruning to avoid\\n    # orphaning provider-side snapshots. This means the actual count can\\n    # exceed max_entries when many versions are deployed \u2014 acceptable\\n    # because deployed versions are actively in use.\\n    # NOTE: Concurrent snapshot requests for the same flow could both insert\\n    # before either prunes, temporarily exceeding the limit by one or more\\n    # entries. This is acceptable \u2014 the excess self-corrects on the next\\n    # snapshot.\\n    try:\\n        max_entries = get_settings_service().settings.max_flow_version_entries_per_flow\\n        # Count a version as \\\"deployed\\\" only when the attachment still points to\\n        # a live deployment row. This prevents orphaned attachments from\\n        # blocking versions from being deleted.\\n        deployed_version_ids = (\\n            select(FlowVersionDeploymentAttachment.flow_version_id)\\n            .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n            .where(\\n                FlowVersionDeploymentAttachment.user_id == user_id,\\n                Deployment.user_id == user_id,\\n                col(FlowVersionDeploymentAttachment.flow_version_id).in_(\\n                    select(FlowVersion.id).where(FlowVersion.flow_id == flow_id)\\n                ),\\n            )\\n            .distinct()\\n        )\\n        version_ids_to_prune = (\\n            await session.exec(\\n                select(FlowVersion.id)\\n                .where(\\n                    FlowVersion.flow_id == flow_id,\\n                    col(FlowVersion.id).not_in(deployed_version_ids),\\n                )\\n                .order_by(col(FlowVersion.version_number).desc())\\n                .offset(max_entries)\\n            )\\n        ).all()\\n        if version_ids_to_prune:\\n            # Delete attachment children first so the row is fully reaped under\\n            # SQLite foreign_keys=OFF (no DB-level cascade). A version reaches\\n            # this branch only when no attachment of it points to a live\\n            # deployment, but stale orphan-deployment attachments may still\\n            # exist; without this explicit delete those rows would survive the\\n            # FlowVersion delete as doubly-orphaned and no cleanup helper\\n            # catches that shape.\\n            await session.exec(\\n                delete(FlowVersionDeploymentAttachment).where(\\n                    col(FlowVersionDeploymentAttachment.flow_version_id).in_(version_ids_to_prune)\\n                )\\n            )\\n            result = await session.exec(delete(FlowVersion).where(col(FlowVersion.id).in_(version_ids_to_prune)))\\n            if hasattr(result, \\\"rowcount\\\") and result.rowcount:  # type: ignore[union-attr]\\n                await logger.adebug(\\\"Pruned %d old version entries for flow %s\\\", result.rowcount, flow_id)  # type: ignore[union-attr]\\n    except SQLAlchemyError:\\n        # Pruning is best-effort: we don't fail the snapshot because pruning broke.\\n        # Logged at error level because repeated failures cause unbounded table growth\\n        # and may need operational attention.\\n        await logger.aerror(\\n            \\\"Failed to prune old version entries for flow %s \u2014 version table may exceed configured limit\\\",\\n            flow_id,\\n            exc_info=True,\\n        )\\n\\n    return entry\\n\\n\\nasync def get_flow_version_list_simple(\\n    session: AsyncSession,\\n    flow_id: UUID,\\n    user_id: UUID,\\n    limit: int = 50,\\n    offset: int = 0,\\n) -> list[tuple[FlowVersion, bool]]:\\n    \\\"\\\"\\\"Return flow versions without deployment awareness.\\n\\n    Used when no deployment provider is configured, avoiding unnecessary\\n    joins against the (empty) attachment table.  The boolean second\\n    element is always ``False``.\\n    \\\"\\\"\\\"\\n    stmt = (\\n        select(FlowVersion)\\n        .where(FlowVersion.flow_id == flow_id, FlowVersion.user_id == user_id)\\n        .order_by(col(FlowVersion.version_number).desc())\\n        .offset(offset)\\n        .limit(limit)\\n    )\\n    rows = (await session.exec(stmt)).all()\\n    return [(version, False) for version in rows]\\n\\n\\nasync def get_flow_versions_with_provider_status(\\n    session: AsyncSession,\\n    flow_id: UUID,\\n    user_id: UUID,\\n    *,\\n    provider_account_id: UUID,\\n    limit: int = 50,\\n    offset: int = 0,\\n) -> list[tuple[FlowVersion, bool]]:\\n    \\\"\\\"\\\"Return flow versions with deployment status scoped to a provider account.\\\"\\\"\\\"\\n    # Deployment status is derived from live parent joins so stale attachment\\n    # rows (missing deployment parent) do not leak into API status.\\n    deployed_subquery = (\\n        select(FlowVersionDeploymentAttachment.flow_version_id)\\n        .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            Deployment.user_id == user_id,\\n            Deployment.deployment_provider_account_id == provider_account_id,\\n            col(FlowVersionDeploymentAttachment.flow_version_id).in_(\\n                select(FlowVersion.id).where(FlowVersion.flow_id == flow_id)\\n            ),\\n        )\\n        .distinct()\\n        .subquery()\\n    )\\n    stmt = (\\n        select(\\n            FlowVersion,\\n            deployed_subquery.c.flow_version_id.isnot(None).label(\\\"is_deployed\\\"),\\n        )\\n        .outerjoin(deployed_subquery, deployed_subquery.c.flow_version_id == FlowVersion.id)\\n        .where(FlowVersion.flow_id == flow_id, FlowVersion.user_id == user_id)\\n    )\\n    stmt = stmt.order_by(col(FlowVersion.version_number).desc()).offset(offset).limit(limit)\\n    rows = (await session.exec(stmt)).all()\\n    return [(version, bool(is_deployed)) for version, is_deployed in rows]\\n\\n\\nasync def get_flow_version_entry(\\n    session: AsyncSession,\\n    version_id: UUID,\\n    user_id: UUID,\\n) -> FlowVersion | None:\\n    result = await session.exec(select(FlowVersion).where(FlowVersion.id == version_id, FlowVersion.user_id == user_id))\\n    return result.first()\\n\\n\\nasync def get_flow_version_entries_by_ids(\\n    session: AsyncSession,\\n    version_ids: list[UUID],\\n    user_id: UUID,\\n) -> dict[UUID, FlowVersion]:\\n    \\\"\\\"\\\"Get flow-version entries for a user using a single query.\\n\\n    Returns a mapping of ``version_id -> FlowVersion`` for all found ids.\\n    Missing ids are omitted from the returned mapping.\\n    \\\"\\\"\\\"\\n    if not version_ids:\\n        return {}\\n    if len(version_ids) > MAX_VERSION_ID_FILTER_SIZE:\\n        msg = f\\\"version_ids supports at most {MAX_VERSION_ID_FILTER_SIZE} values.\\\"\\n        raise ValueError(msg)\\n\\n    stmt = select(FlowVersion).where(\\n        col(FlowVersion.id).in_(version_ids),\\n        FlowVersion.user_id == user_id,\\n    )\\n    rows = (await session.exec(stmt)).all()\\n    return {row.id: row for row in rows}\\n\\n\\nasync def get_flow_version_entry_or_raise(\\n    session: AsyncSession,\\n    version_id: UUID,\\n    user_id: UUID,\\n    flow_id: UUID | None = None,\\n) -> FlowVersion:\\n    \\\"\\\"\\\"Get a version entry or raise FlowVersionNotFoundError.\\n\\n    If flow_id is provided, also verifies the entry belongs to that flow.\\n    \\\"\\\"\\\"\\n    entry = await get_flow_version_entry(session, version_id, user_id)\\n    if not entry or (flow_id is not None and entry.flow_id != flow_id):\\n        msg = f\\\"Version entry {version_id} not found\\\"\\n        raise FlowVersionNotFoundError(msg)\\n    return entry\\n\\n\\nasync def is_flow_version_deployed(\\n    session: AsyncSession,\\n    flow_version_id: UUID,\\n    user_id: UUID | None = None,\\n) -> bool:\\n    \\\"\\\"\\\"Return True if the flow version is attached to at least one deployment.\\\"\\\"\\\"\\n    return await has_deployment_attachments(session, flow_version_id, user_id=user_id)\\n\\n\\nasync def has_deployment_attachments(\\n    session: AsyncSession,\\n    flow_version_id: UUID,\\n    user_id: UUID | None = None,\\n) -> bool:\\n    \\\"\\\"\\\"Check whether a flow version has live deployment attachments.\\n\\n    Returns True when at least one attachment row points to an existing\\n    deployment.  When no live attachments are found, orphan attachment rows\\n    (whose deployment parent was deleted without cascading) are pruned as a\\n    side-effect so subsequent calls and delete guards do not keep\\n    re-processing stale records.\\n\\n    Callers that only need a pure read should use a direct ``select`` with\\n    an inner join on ``Deployment`` instead.\\n    \\\"\\\"\\\"\\n    # First check only \\\"live\\\" attachments (attachment + existing deployment).\\n    live_stmt = (\\n        select(func.count(FlowVersionDeploymentAttachment.id))\\n        .join(\\n            Deployment,\\n            Deployment.id == FlowVersionDeploymentAttachment.deployment_id,\\n        )\\n        .where(\\n            FlowVersionDeploymentAttachment.flow_version_id == flow_version_id,\\n        )\\n    )\\n    if user_id is not None:\\n        live_stmt = live_stmt.where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            Deployment.user_id == user_id,\\n        )\\n    live_count = (await session.exec(live_stmt)).one()\\n    if int(live_count or 0) > 0:\\n        return True\\n\\n    # If no live attachments remain, opportunistically clean orphan rows so\\n    # repeated delete/version checks don't keep re-processing stale records.\\n    stale_attachment_ids_stmt = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .outerjoin(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.flow_version_id == flow_version_id,\\n            Deployment.id.is_(None),\\n        )\\n    )\\n    if user_id is not None:\\n        stale_attachment_ids_stmt = stale_attachment_ids_stmt.where(FlowVersionDeploymentAttachment.user_id == user_id)\\n    stale_attachment_ids = (await session.exec(stale_attachment_ids_stmt)).all()\\n    if stale_attachment_ids:\\n        await session.exec(\\n            delete(FlowVersionDeploymentAttachment).where(\\n                col(FlowVersionDeploymentAttachment.id).in_(stale_attachment_ids)\\n            )\\n        )\\n        await logger.ainfo(\\n            \\\"Pruned %d orphan attachment(s) for flow_version %s\\\",\\n            len(stale_attachment_ids),\\n            flow_version_id,\\n        )\\n    return False\\n\\n\\nasync def lock_flow_version_entry(\\n    session: AsyncSession,\\n    version_id: UUID,\\n    user_id: UUID | None = None,\\n    *,\\n    key_share: bool = False,\\n) -> bool:\\n    \\\"\\\"\\\"Lock a version until transaction end; return whether it still exists.\\n\\n    PostgreSQL attachments use key-share locks so they can run concurrently\\n    while still excluding version deletion, which keeps the exclusive lock.\\n    \\\"\\\"\\\"\\n    conditions = [FlowVersion.id == version_id]\\n    if user_id is not None:\\n        conditions.append(FlowVersion.user_id == user_id)\\n    dialect = session.get_bind().dialect.name\\n    if dialect == \\\"sqlite\\\":\\n        # SQLite ignores FOR UPDATE. A no-op write takes its transaction-wide\\n        # writer lock before either caller checks or changes attachments.\\n        result = await session.exec(\\n            update(FlowVersion)\\n            .where(*conditions)\\n            .values(id=FlowVersion.id)\\n            .execution_options(synchronize_session=False)\\n        )\\n        return result.rowcount != 0\\n    stmt = select(FlowVersion.id).where(*conditions).with_for_update()\\n    if dialect == \\\"postgresql\\\" and key_share:\\n        stmt = stmt.with_for_update(read=True, key_share=True)\\n    return (await session.exec(stmt)).first() is not None\\n\\n\\nasync def delete_flow_version_entry(\\n    session: AsyncSession,\\n    version_id: UUID,\\n    user_id: UUID,\\n) -> None:\\n    # Serialize the deployment guard and delete with attachment creation.\\n    if not await lock_flow_version_entry(session, version_id, user_id):\\n        msg = f\\\"Version entry {version_id} not found\\\"\\n        raise FlowVersionNotFoundError(msg)\\n\\n    if await has_deployment_attachments(session, version_id, user_id=user_id):\\n        msg = (\\n            f\\\"Version entry {version_id} is attached to one or more deployments \\\"\\n            f\\\"and cannot be deleted. Remove its deployment attachment rows first.\\\"\\n        )\\n        raise FlowVersionDeployedError(msg)\\n\\n    # The entry can disappear after the preflight reads under concurrent DELETEs.\\n    result = await session.exec(delete(FlowVersion).where(FlowVersion.id == version_id, FlowVersion.user_id == user_id))\\n    if result.rowcount == 0:\\n        msg = f\\\"Version entry {version_id} not found\\\"\\n        raise FlowVersionNotFoundError(msg)\\n    await session.flush()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fba83571a705cd558d5dd174acdd6a20d7c8325d456cc770a59db1328e52ff2c\",\"content\":\"\\\"\\\"\\\"Domain exceptions for the flow-history module.\\n\\nThese are raised by the CRUD layer and translated to HTTP responses at the API boundary.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n\\nclass FlowVersionError(Exception):\\n    \\\"\\\"\\\"Base exception for flow-version domain errors.\\\"\\\"\\\"\\n\\n\\nclass FlowVersionSerializationError(FlowVersionError):\\n    \\\"\\\"\\\"Raised when flow data cannot be serialized.\\\"\\\"\\\"\\n\\n\\nclass FlowVersionConflictError(FlowVersionError):\\n    \\\"\\\"\\\"Raised when version number conflicts exhaust all retries.\\\"\\\"\\\"\\n\\n\\nclass FlowVersionNotFoundError(FlowVersionError):\\n    \\\"\\\"\\\"Raised when a version entry is not found.\\\"\\\"\\\"\\n\\n\\nclass FlowVersionDeployedError(FlowVersionError):\\n    \\\"\\\"\\\"Raised when an operation targets a flow version attached to a deployment.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a681630f1b55d40ec5f166fe46d9bd8600b2d1857fd95171efdb80e53be99ae7\",\"content\":\"from __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import BaseModel, computed_field, field_serializer\\nfrom pydantic import Field as PydanticField\\nfrom sqlalchemy import CheckConstraint, Column, DateTime, ForeignKey, UniqueConstraint, func\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import JSON, Field, SQLModel\\n\\n# Final name of the ``version_number >= 1`` CHECK. It is wrapped in ``conv()`` below so Alembic's\\n# ``ck_%(table_name)s_%(constraint_name)s`` convention (installed on SQLModel.metadata by\\n# alembic/env.py) renders the same name whether the table is created by\\n# ``SQLModel.metadata.create_all`` or by the migration's ``op.create_table``.\\nVERSION_NUMBER_CHECK_NAME = \\\"ck_flow_version_version_number_positive\\\"\\n\\n\\nclass FlowVersion(SQLModel, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"flow_version\\\"\\n    __mapper_args__ = {\\\"confirm_deleted_rows\\\": False}\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    flow_id: UUID = Field(\\n        sa_column=Column(ForeignKey(\\\"flow.id\\\", ondelete=\\\"CASCADE\\\"), index=True, nullable=False),\\n    )\\n    user_id: UUID | None = Field(\\n        sa_column=Column(ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), index=True, nullable=True),\\n    )\\n    data: dict | None = Field(default=None, sa_column=Column(JSON))\\n    version_number: int = Field(nullable=False, ge=1)\\n    description: str | None = Field(default=None, nullable=True, max_length=500)\\n    created_at: datetime = Field(\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=False, index=True),\\n    )\\n\\n    # The UniqueConstraint on (flow_id, version_number) creates an implicit composite\\n    # btree index that also covers ORDER BY version_number DESC queries filtered by\\n    # flow_id. No additional index is needed for the list/prune queries.\\n    __table_args__ = (\\n        UniqueConstraint(\\\"flow_id\\\", \\\"version_number\\\", name=\\\"unique_flow_version_number\\\"),\\n        CheckConstraint(\\\"version_number >= 1\\\", name=conv(VERSION_NUMBER_CHECK_NAME)),\\n    )\\n\\n\\nclass FlowVersionRead(BaseModel):\\n    \\\"\\\"\\\"Schema for listing flow versions \u2014 excludes data for performance.\\\"\\\"\\\"\\n\\n    id: UUID\\n    flow_id: UUID\\n    user_id: UUID | None\\n    version_number: int = PydanticField(ge=1)\\n    description: str | None\\n    created_at: datetime\\n    is_deployed: bool | None = PydanticField(\\n        default=None,\\n        description=(\\n            \\\"True when this version is attached to at least one deployment. \\\"\\n            \\\"Omitted unless deployment_provider_id is provided as a query parameter.\\\"\\n        ),\\n    )\\n\\n    @computed_field  # type: ignore[prop-decorator]\\n    @property\\n    def version_tag(self) -> str:\\n        return f\\\"v{self.version_number}\\\"\\n\\n    @field_serializer(\\\"created_at\\\")\\n    def serialize_datetime(self, value: datetime) -> str:\\n        value = value.replace(microsecond=0)\\n        if value.tzinfo is None:\\n            value = value.replace(tzinfo=timezone.utc)\\n        return value.isoformat()\\n\\n\\nclass FlowVersionReadWithData(FlowVersionRead):\\n    \\\"\\\"\\\"Schema for a single flow version \u2014 includes full data.\\\"\\\"\\\"\\n\\n    data: dict | None\\n\\n\\nclass FlowVersionCreate(BaseModel):\\n    \\\"\\\"\\\"Schema for creating a flow version \u2014 user only provides description.\\\"\\\"\\\"\\n\\n    description: str | None = Field(default=None, max_length=500)\\n\\n\\nclass FlowVersionListResponse(BaseModel):\\n    \\\"\\\"\\\"Wrapper for the list endpoint \u2014 includes flow versions and the configured max.\\\"\\\"\\\"\\n\\n    entries: list[FlowVersionRead]\\n    max_entries: int = PydanticField(ge=1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version_deployment_attachment/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"50c683d9930c7af36001f091d445e94f6cd60df437ceddd5750e3a72a56bf5c6\",\"content\":\"from .model import FlowVersionDeploymentAttachment\\n\\n__all__ = [\\\"FlowVersionDeploymentAttachment\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version_deployment_attachment/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb33e1de556011e6c20d6f450605df1d5134fcfcdfbeafe4fd2ffa609f863a83\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport sqlalchemy as sa\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy import and_, column, values\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import col, delete, func, select, update\\n\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_attachment_project_match\\nfrom langflow.services.database.models.flow_version.crud import lock_flow_version_entry\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.database.utils import require_non_empty\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.api.v1.mappers.deployments.contracts import ProviderSnapshotBinding\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n    from langflow.services.database.models.flow_version_deployment_attachment.schema import (\\n        DeploymentAttachmentKeyBatch,\\n    )\\n\\n_SNAPSHOT_ID_ERROR = \\\"provider_snapshot_id must not be empty\\\"\\n\\n\\nclass AttachmentConflictError(ValueError):\\n    \\\"\\\"\\\"Base exception for flow-version attachment conflicts.\\\"\\\"\\\"\\n\\n\\nclass SnapshotFlowVersionConflictError(AttachmentConflictError):\\n    \\\"\\\"\\\"Raised when one provider snapshot is linked to multiple flow versions.\\\"\\\"\\\"\\n\\n\\nclass DeploymentAttachmentConflictError(AttachmentConflictError):\\n    \\\"\\\"\\\"Raised when a deployment attachment violates DB uniqueness constraints.\\\"\\\"\\\"\\n\\n\\nasync def _check_snapshot_flow_version_conflict(\\n    db: AsyncSession,\\n    *,\\n    provider_snapshot_id: str | None,\\n    flow_version_id: UUID,\\n) -> None:\\n    \\\"\\\"\\\"Ensure a provider_snapshot_id is only ever linked to one flow version.\\n\\n    A tool can appear in multiple deployments, but every row with the same\\n    provider_snapshot_id must point to the same flow_version_id.  For example:\\n\\n        (FV=1, tool=A, deploy=X)  \u2713  \u2014 first use of tool A\\n        (FV=1, tool=A, deploy=Y)  \u2713  \u2014 same FV, different deployment, OK\\n        (FV=2, tool=A, deploy=Z)  \u2717  \u2014 different FV for tool A, rejected\\n\\n    This cannot be expressed as a DB unique constraint, so we enforce it here.\\n\\n    Concurrency note: this is a read-before-write guard with no DB-level lock\\n    or uniqueness guarantee on provider_snapshot_id. Concurrent transactions\\n    can still both pass this check before either commit.\\n    \\\"\\\"\\\"\\n    if not provider_snapshot_id:\\n        return\\n    stmt = (\\n        select(FlowVersionDeploymentAttachment.flow_version_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.provider_snapshot_id == provider_snapshot_id,\\n            FlowVersionDeploymentAttachment.flow_version_id != flow_version_id,\\n        )\\n        .limit(1)\\n    )\\n    conflict = (await db.exec(stmt)).first()\\n    if conflict is not None:\\n        logger.info(\\n            \\\"Snapshot flow-version conflict detected for provider_snapshot_id=%s (requested=%s existing=%s).\\\",\\n            provider_snapshot_id,\\n            flow_version_id,\\n            conflict,\\n        )\\n        msg = (\\n            f\\\"Tool '{provider_snapshot_id}' is already attached to a different flow version. \\\"\\n            f\\\"Each tool can only be linked to one flow version.\\\"\\n        )\\n        raise SnapshotFlowVersionConflictError(msg)\\n\\n\\nasync def create_deployment_attachment(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_version_id: UUID,\\n    deployment_id: UUID,\\n    provider_snapshot_id: str,\\n) -> FlowVersionDeploymentAttachment:\\n    # Keep the parent alive through the attachment insert and transaction commit.\\n    # PostgreSQL attachments can share this lock; version deletion takes an\\n    # exclusive lock before its deployment guard and waits for attachments.\\n    if not await lock_flow_version_entry(db, flow_version_id, key_share=True):\\n        msg = f\\\"Version entry {flow_version_id} no longer exists; attachment cannot be created\\\"\\n        raise DeploymentAttachmentConflictError(msg)\\n    await ensure_attachment_project_match(\\n        db,\\n        flow_version_id=flow_version_id,\\n        deployment_id=deployment_id,\\n    )\\n    await _check_snapshot_flow_version_conflict(\\n        db,\\n        provider_snapshot_id=provider_snapshot_id,\\n        flow_version_id=flow_version_id,\\n    )\\n    row = FlowVersionDeploymentAttachment(\\n        user_id=user_id,\\n        flow_version_id=flow_version_id,\\n        deployment_id=deployment_id,\\n        provider_snapshot_id=require_non_empty(provider_snapshot_id, _SNAPSHOT_ID_ERROR),\\n    )\\n    db.add(row)\\n    try:\\n        await db.flush()\\n    except IntegrityError as exc:\\n        # Note: rollback handled by asyncsession\\n        logger.warning(\\n            \\\"Duplicate or invalid attachment: flow_version=%s deployment=%s \u2014 %s\\\",\\n            flow_version_id,\\n            deployment_id,\\n            exc,\\n        )\\n        msg = (\\n            f\\\"Attachment conflicts with an existing record (flow_version={flow_version_id}, deployment={deployment_id})\\\"\\n        )\\n        raise DeploymentAttachmentConflictError(msg) from exc\\n    await db.refresh(row)\\n    return row\\n\\n\\nasync def get_deployment_attachment(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_version_id: UUID,\\n    deployment_id: UUID,\\n) -> FlowVersionDeploymentAttachment | None:\\n    stmt = select(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.user_id == user_id,\\n        FlowVersionDeploymentAttachment.flow_version_id == flow_version_id,\\n        FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n    )\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def list_deployment_attachments(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID,\\n    flow_ids: list[UUID] | None = None,\\n) -> list[FlowVersionDeploymentAttachment]:\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    stmt = (\\n        select(FlowVersionDeploymentAttachment)\\n        # join with flow version to filter out orphaned attachments\\n        .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n        )\\n    )\\n    if flow_ids:\\n        stmt = stmt.where(col(FlowVersion.flow_id).in_(flow_ids))\\n    stmt = stmt.order_by(FlowVersionDeploymentAttachment.created_at)\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def list_deployment_attachments_with_versions(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID,\\n    offset: int,\\n    limit: int,\\n    flow_ids: list[UUID] | None = None,\\n) -> list[tuple[FlowVersionDeploymentAttachment, FlowVersion, str | None]]:\\n    \\\"\\\"\\\"Return paginated attachment rows joined with version metadata and flow name.\\\"\\\"\\\"\\n    from langflow.services.database.models.flow.model import Flow\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    if limit <= 0:\\n        return []\\n\\n    stmt = (\\n        select(FlowVersionDeploymentAttachment, FlowVersion, col(Flow.name).label(\\\"flow_name\\\"))\\n        .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n        .join(Flow, Flow.id == FlowVersion.flow_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n        )\\n    )\\n    if flow_ids:\\n        stmt = stmt.where(col(FlowVersion.flow_id).in_(flow_ids))\\n    stmt = (\\n        stmt.order_by(\\n            col(FlowVersionDeploymentAttachment.created_at).desc(),\\n            col(FlowVersionDeploymentAttachment.updated_at).desc(),\\n        )\\n        .offset(offset)\\n        .limit(limit)\\n    )\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def list_deployment_attachments_for_flow_version_ids(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID,\\n    flow_version_ids: list[UUID],\\n) -> list[FlowVersionDeploymentAttachment]:\\n    if not flow_version_ids:\\n        return []\\n    stmt = select(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.user_id == user_id,\\n        FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n        col(FlowVersionDeploymentAttachment.flow_version_id).in_(flow_version_ids),\\n    )\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def delete_deployment_attachment(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_version_id: UUID,\\n    deployment_id: UUID,\\n) -> int:\\n    stmt = delete(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.user_id == user_id,\\n        FlowVersionDeploymentAttachment.flow_version_id == flow_version_id,\\n        FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n    )\\n    result = await db.exec(stmt)\\n    return int(result.rowcount or 0)\\n\\n\\nasync def update_deployment_attachment_provider_snapshot_id(\\n    db: AsyncSession,\\n    *,\\n    attachment: FlowVersionDeploymentAttachment,\\n    provider_snapshot_id: str,\\n) -> FlowVersionDeploymentAttachment:\\n    provider_snapshot_id = require_non_empty(provider_snapshot_id, _SNAPSHOT_ID_ERROR)\\n    await _check_snapshot_flow_version_conflict(\\n        db,\\n        provider_snapshot_id=provider_snapshot_id,\\n        flow_version_id=attachment.flow_version_id,\\n    )\\n    attachment.provider_snapshot_id = provider_snapshot_id\\n    db.add(attachment)\\n    await db.flush()\\n    await db.refresh(attachment)\\n    return attachment\\n\\n\\nasync def delete_deployment_attachments_by_deployment_id(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID,\\n) -> int:\\n    stmt = delete(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.user_id == user_id,\\n        FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n    )\\n    result = await db.exec(stmt)\\n    return int(result.rowcount or 0)\\n\\n\\nasync def delete_deployment_attachments_by_keys(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    attachment_key_batch: DeploymentAttachmentKeyBatch,\\n) -> int:\\n    key_tuples = attachment_key_batch.as_tuples()\\n    if not key_tuples:\\n        return 0\\n\\n    stale_keys_cte = (\\n        values(\\n            column(\\\"deployment_id\\\", sa.Uuid()),\\n            column(\\\"flow_version_id\\\", sa.Uuid()),\\n        )\\n        .data(key_tuples)\\n        .cte(\\\"stale_keys\\\")\\n    )\\n\\n    stale_attachment_ids = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .join(\\n            stale_keys_cte,\\n            and_(\\n                FlowVersionDeploymentAttachment.deployment_id == stale_keys_cte.c.deployment_id,\\n                FlowVersionDeploymentAttachment.flow_version_id == stale_keys_cte.c.flow_version_id,\\n            ),\\n        )\\n        .where(FlowVersionDeploymentAttachment.user_id == user_id)\\n    )\\n\\n    stmt = delete(FlowVersionDeploymentAttachment).where(\\n        col(FlowVersionDeploymentAttachment.id).in_(stale_attachment_ids)\\n    )\\n    result = await db.exec(stmt)\\n    return int(result.rowcount or 0)\\n\\n\\nasync def list_attachments_by_deployment_ids(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_ids: list[UUID],\\n) -> list[FlowVersionDeploymentAttachment]:\\n    if not deployment_ids:\\n        return []\\n    stmt = (\\n        select(FlowVersionDeploymentAttachment)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n        )\\n        .order_by(FlowVersionDeploymentAttachment.created_at)\\n    )\\n    return list((await db.exec(stmt)).all())\\n\\n\\nasync def list_attachments_for_flow_with_provider_info(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_ids: list[UUID],\\n) -> list[tuple[FlowVersionDeploymentAttachment, UUID, str]]:\\n    \\\"\\\"\\\"Return attachments for all versions of a flow, with provider context.\\n\\n    Each tuple contains:\\n      - the attachment row\\n      - the deployment's ``deployment_provider_account_id``\\n      - the provider account's ``provider_key``\\n\\n    This avoids N+1 queries when the caller needs to group attachments by\\n    provider for sync operations.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    if not flow_ids:\\n        return []\\n\\n    stmt = (\\n        select(\\n            FlowVersionDeploymentAttachment,\\n            Deployment.deployment_provider_account_id,\\n            DeploymentProviderAccount.provider_key,\\n        )\\n        .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .join(DeploymentProviderAccount, DeploymentProviderAccount.id == Deployment.deployment_provider_account_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.flow_version_id.in_(\\n                select(FlowVersion.id).where(FlowVersion.flow_id.in_(flow_ids))\\n            ),\\n        )\\n        .order_by(FlowVersionDeploymentAttachment.created_at)\\n    )\\n    rows = (await db.exec(stmt)).all()\\n    return [(attachment, provider_account_id, provider_key) for attachment, provider_account_id, provider_key in rows]\\n\\n\\nasync def delete_unbound_attachments(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    provider_account_id: UUID,\\n    deployment_ids: list[UUID],\\n    bindings: list[ProviderSnapshotBinding],\\n) -> int:\\n    \\\"\\\"\\\"Delete stale attachments for an explicit deployment subset.\\n\\n    Scope contract:\\n    - ``deployment_ids`` defines the target deployment set. Deletions are\\n      always constrained to this set.\\n    - ``bindings`` is the provider-observed snapshot view for the same scope\\n      and is keyed by ``(resource_key, snapshot_id)``.\\n\\n    Why ``deployment_ids`` is required:\\n    - ``bindings`` comes from the provider snapshot view, not from the local\\n      target set. It is not a complete scope declaration.\\n    - A targeted deployment can be absent from ``bindings`` when the provider\\n      returns no snapshots for it; in that case, all local attachments for that\\n      deployment are stale and should be deleted.\\n    - If scope is derived only from provider-scoped bindings (without explicit\\n      ``deployment_ids``), it under-deletes: deployments with zero provider\\n      bindings are skipped.\\n    Provider scoping:\\n    - ``provider_account_id`` scopes ``resource_key`` matching to one provider\\n      account namespace.\\n    - Any ``deployment_ids`` not owned by ``provider_account_id`` are ignored\\n      by the joined predicates (dropped from the effective target set).\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.model import Deployment\\n\\n    if not deployment_ids:\\n        return 0\\n\\n    if not bindings:\\n        # all local db attachments are stale\\n        scoped_attachment_ids = (\\n            select(FlowVersionDeploymentAttachment.id)\\n            .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n            .where(\\n                FlowVersionDeploymentAttachment.user_id == user_id,\\n                col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n                Deployment.deployment_provider_account_id == provider_account_id,\\n            )\\n        )\\n        stmt = delete(FlowVersionDeploymentAttachment).where(\\n            col(FlowVersionDeploymentAttachment.id).in_(scoped_attachment_ids),\\n        )\\n        result = await db.exec(stmt)\\n        return int(result.rowcount or 0)\\n\\n    deduped_bindings = list(dict.fromkeys((binding.resource_key, binding.snapshot_id) for binding in bindings))\\n    provider_bindings_cte = (\\n        values(\\n            column(\\\"resource_key\\\", sa.String()),\\n            column(\\\"snapshot_id\\\", sa.String()),\\n        )\\n        .data(deduped_bindings)\\n        .cte(\\\"provider_bindings\\\")\\n    )\\n\\n    stale_attachment_ids = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .outerjoin(\\n            provider_bindings_cte,\\n            and_(\\n                Deployment.resource_key == provider_bindings_cte.c.resource_key,\\n                FlowVersionDeploymentAttachment.provider_snapshot_id == provider_bindings_cte.c.snapshot_id,\\n            ),\\n        )\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n            Deployment.deployment_provider_account_id == provider_account_id,\\n            provider_bindings_cte.c.resource_key.is_(None),  # No provider binding match => stale local attachment\\n        )\\n    )\\n\\n    stmt = delete(FlowVersionDeploymentAttachment).where(\\n        col(FlowVersionDeploymentAttachment.id).in_(stale_attachment_ids)\\n    )\\n    result = await db.exec(stmt)\\n    return int(result.rowcount or 0)\\n\\n\\nasync def list_attachments_for_flow_with_deployment_info(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_id: UUID,\\n) -> list[tuple[FlowVersionDeploymentAttachment, str, str, str]]:\\n    \\\"\\\"\\\"Return deployed attachments for all versions of a flow, with deployment context.\\n\\n    Each tuple contains:\\n      - the attachment row\\n      - the deployment's ``display_name``\\n      - the deployment's ``deployment_type`` value\\n      - the provider account's ``provider_key``\\n\\n    Results are ordered by ``updated_at`` descending so the most recent\\n    attachment per deployment comes first.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    stmt = (\\n        select(\\n            FlowVersionDeploymentAttachment,\\n            Deployment.display_name,\\n            Deployment.deployment_type,\\n            DeploymentProviderAccount.provider_key,\\n        )\\n        .join(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .join(DeploymentProviderAccount, DeploymentProviderAccount.id == Deployment.deployment_provider_account_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersionDeploymentAttachment.flow_version_id).in_(\\n                select(FlowVersion.id).where(FlowVersion.flow_id == flow_id)\\n            ),\\n        )\\n        .order_by(FlowVersionDeploymentAttachment.updated_at.desc())  # type: ignore[union-attr]\\n    )\\n    rows = (await db.exec(stmt)).all()\\n    return [(att, name, dtype.value, pkey) for att, name, dtype, pkey in rows]\\n\\n\\nasync def get_attachment_by_provider_snapshot_id(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    provider_snapshot_id: str,\\n) -> FlowVersionDeploymentAttachment | None:\\n    \\\"\\\"\\\"Look up an attachment by its provider_snapshot_id (owner-scoped).\\n\\n    Returns at most one row matching ``(user_id, provider_snapshot_id)``.\\n    Callers that need cross-user resolution (a non-owner reaching a shared\\n    deployment's snapshot) must use :func:`list_attachments_by_provider_snapshot_id`\\n    instead: ``provider_snapshot_id`` is only indexed, not unique, so a\\n    bare share-aware lookup that calls ``.first()`` can pick the wrong row\\n    when the same snapshot is attached to multiple deployments.\\n    \\\"\\\"\\\"\\n    stmt = select(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.user_id == user_id,\\n        FlowVersionDeploymentAttachment.provider_snapshot_id == provider_snapshot_id,\\n    )\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def list_attachments_by_provider_snapshot_id(\\n    db: AsyncSession,\\n    *,\\n    provider_snapshot_id: str,\\n) -> list[FlowVersionDeploymentAttachment]:\\n    \\\"\\\"\\\"Return every attachment row sharing ``provider_snapshot_id``.\\n\\n    The DB only enforces ``UNIQUE(flow_version_id, deployment_id)``;\\n    ``provider_snapshot_id`` is indexed but not unique because a single\\n    provider snapshot can be attached to multiple deployments (see\\n    :func:`update_flow_version_by_provider_snapshot_id`). Share-aware\\n    callers (cross-user deployment access) iterate this list, authorize\\n    each candidate's deployment, and proceed only when exactly one\\n    authorized match remains \u2014 that way a duplicate `provider_snapshot_id`\\n    does not yield a false 404 or silently pick the wrong row.\\n    \\\"\\\"\\\"\\n    stmt = select(FlowVersionDeploymentAttachment).where(\\n        FlowVersionDeploymentAttachment.provider_snapshot_id == provider_snapshot_id,\\n    )\\n    return list(await db.exec(stmt))\\n\\n\\nasync def update_flow_version_by_provider_snapshot_id(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    provider_snapshot_id: str,\\n    flow_version_id: UUID,\\n) -> int:\\n    \\\"\\\"\\\"Update all attachment rows that share a provider_snapshot_id.\\n\\n    A single provider snapshot can be attached to multiple deployments, so\\n    route handlers must update every matching row together.\\n\\n    Concurrency note: this is a set-based UPDATE without an explicit lock/read\\n    phase. If concurrent writers touch the same snapshot id, last commit wins.\\n    \\\"\\\"\\\"\\n    stmt = (\\n        update(FlowVersionDeploymentAttachment)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.provider_snapshot_id == provider_snapshot_id,\\n        )\\n        .values(flow_version_id=flow_version_id)\\n    )\\n    result = await db.exec(stmt)\\n    return int(result.rowcount or 0)\\n\\n\\nasync def count_attachments_by_deployment_ids(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_ids: list[UUID],\\n) -> dict[UUID, int]:\\n    \\\"\\\"\\\"Return distinct flow-version attachment counts keyed by deployment id.\\n\\n    Returns a dictionary mapping each deployment id to the number of rows in\\n    FlowVersionDeploymentAttachment with that deployment id.\\n    \\\"\\\"\\\"\\n    if not deployment_ids:\\n        return {}\\n\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    stmt = (\\n        select(\\n            FlowVersionDeploymentAttachment.deployment_id,\\n            func.count(func.distinct(FlowVersionDeploymentAttachment.flow_version_id)),\\n        )\\n        # Count only attachments whose flow_version parent still exists.\\n        .join(\\n            FlowVersion,\\n            FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n        )\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersionDeploymentAttachment.deployment_id).in_(deployment_ids),\\n        )\\n        .group_by(FlowVersionDeploymentAttachment.deployment_id)\\n    )\\n    rows = (await db.exec(stmt)).all()\\n    counts_by_id = {deployment_id: int(count) for deployment_id, count in rows}\\n    return {deployment_id: counts_by_id.get(deployment_id, 0) for deployment_id in deployment_ids}\\n\\n\\nasync def count_deployment_attachments(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    deployment_id: UUID,\\n    flow_ids: list[UUID] | None = None,\\n) -> int:\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    stmt = (\\n        select(func.count())\\n        .select_from(FlowVersionDeploymentAttachment)\\n        # Keep count aligned with \\\"live\\\" flow-version links only.\\n        .join(\\n            FlowVersion,\\n            FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n        )\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            FlowVersionDeploymentAttachment.deployment_id == deployment_id,\\n        )\\n    )\\n    if flow_ids:\\n        stmt = stmt.where(col(FlowVersion.flow_id).in_(flow_ids))\\n    total = (await db.exec(stmt)).one()\\n    return int(total or 0)\\n\\n\\nasync def delete_orphan_attachments_for_flow_ids(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    flow_ids: list[UUID],\\n) -> int:\\n    \\\"\\\"\\\"Delete attachment rows whose deployment parent is missing for the given flows.\\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    if not flow_ids:\\n        return 0\\n\\n    # Scope to the requested flows, then select rows whose deployment parent\\n    # is missing so we can safely prune stale attachment records.\\n    stale_attachment_ids = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n        .outerjoin(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            col(FlowVersion.flow_id).in_(flow_ids),\\n            Deployment.id.is_(None),\\n        )\\n    )\\n    result = await db.exec(\\n        delete(FlowVersionDeploymentAttachment).where(col(FlowVersionDeploymentAttachment.id).in_(stale_attachment_ids))\\n    )\\n    return int(result.rowcount or 0)\\n\\n\\nasync def delete_orphan_attachments_for_project(\\n    db: AsyncSession,\\n    *,\\n    user_id: UUID,\\n    project_id: UUID,\\n) -> int:\\n    \\\"\\\"\\\"Delete attachment rows with missing deployment parent for one project scope.\\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.flow.model import Flow\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n\\n    # Project-scoped variant used before project guard retries/sync.\\n    stale_attachment_ids = (\\n        select(FlowVersionDeploymentAttachment.id)\\n        .join(FlowVersion, FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id)\\n        .join(Flow, Flow.id == FlowVersion.flow_id)\\n        .outerjoin(Deployment, Deployment.id == FlowVersionDeploymentAttachment.deployment_id)\\n        .where(\\n            FlowVersionDeploymentAttachment.user_id == user_id,\\n            Flow.user_id == user_id,\\n            Flow.folder_id == project_id,\\n            Deployment.id.is_(None),\\n        )\\n    )\\n    result = await db.exec(\\n        delete(FlowVersionDeploymentAttachment).where(col(FlowVersionDeploymentAttachment.id).in_(stale_attachment_ids))\\n    )\\n    return int(result.rowcount or 0)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version_deployment_attachment/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1e6f22eba6b3a7d282e22318e1a94487de12169e3adbf99daf807915e7bc08a9\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import ValidationInfo, field_validator\\nfrom sqlalchemy import ForeignKey, UniqueConstraint\\nfrom sqlalchemy.orm import validates\\nfrom sqlmodel import Column, DateTime, Field, SQLModel, func\\n\\nfrom langflow.services.database.utils import validate_non_empty_string\\n\\nif TYPE_CHECKING:\\n    from datetime import datetime\\n\\n\\nclass FlowVersionDeploymentAttachment(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Tracks which flow versions are attached to which deployments.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"flow_version_deployment_attachment\\\"\\n    __table_args__ = (UniqueConstraint(\\\"flow_version_id\\\", \\\"deployment_id\\\", name=\\\"uq_flow_version_deployment\\\"),)\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUID = Field(sa_column=Column(ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), index=True, nullable=False))\\n    flow_version_id: UUID = Field(\\n        sa_column=Column(ForeignKey(\\\"flow_version.id\\\", ondelete=\\\"CASCADE\\\"), index=True, nullable=False),\\n    )\\n    deployment_id: UUID = Field(\\n        sa_column=Column(ForeignKey(\\\"deployment.id\\\", ondelete=\\\"CASCADE\\\"), index=True, nullable=False),\\n    )\\n    provider_snapshot_id: str | None = Field(\\n        ...,\\n        index=True,\\n        # DB column is nullable for migration compatibility; app-side writes\\n        # are validated/normalized at CRUD callsites.\\n        description=(\\n            \\\"Opaque provider-assigned identifier for the materialized snapshot \\\"\\n            \\\"(e.g. a wxO tool ID, a K8s ConfigMap name, an S3 key). \\\"\\n            \\\"Links this Langflow flow version to its provider-side resource.\\\"\\n        ),\\n    )\\n    created_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=False),\\n    )\\n    updated_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False),\\n    )\\n\\n    # Primary enforcement is in CRUD helpers (require_non_empty at write boundary).\\n    # The field_validator is best used for .model_validate calls.\\n    # The validates decorator is best used for direct ORM object attribute writes.\\n    @field_validator(\\\"provider_snapshot_id\\\")\\n    @classmethod\\n    def validate_provider_snapshot_id_field(cls, v: str | None, info: ValidationInfo) -> str:\\n        if v is None:\\n            msg = f\\\"{info.field_name} must not be empty\\\"\\n            raise ValueError(msg)\\n        return validate_non_empty_string(v, info)\\n\\n    @validates(\\\"provider_snapshot_id\\\")\\n    def validate_provider_snapshot_id_assignment(self, _key: str, value: str | None) -> str:\\n        \\\"\\\"\\\"Safety net for direct ORM writes that bypass CRUD helpers.\\n\\n        CRUD paths normalize input first to provide deterministic API-layer\\n        behavior, but this validator still protects ad-hoc model assignment\\n        and other SQLAlchemy write paths from persisting blank/None values.\\n        \\\"\\\"\\\"\\n        if value is None:\\n            msg = \\\"provider_snapshot_id must not be empty\\\"\\n            raise ValueError(msg)\\n        stripped = value.strip()\\n        if not stripped:\\n            msg = \\\"provider_snapshot_id must not be empty\\\"\\n            raise ValueError(msg)\\n        return stripped\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/flow_version_deployment_attachment/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2733d12cfb3cdd1fffdcf68fcb8504ce1c6adca271b4d388ae3b7c1c3c33d579\",\"content\":\"from __future__ import annotations\\n\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, model_validator\\n\\n\\nclass DeploymentAttachmentKey(BaseModel):\\n    deployment_id: UUID\\n    flow_version_id: UUID\\n\\n\\nclass DeploymentAttachmentKeyBatch(BaseModel):\\n    keys: list[DeploymentAttachmentKey] = Field(default_factory=list)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def dedupe_keys(self) -> DeploymentAttachmentKeyBatch:\\n        seen: set[tuple[UUID, UUID]] = set()\\n        deduped: list[DeploymentAttachmentKey] = []\\n        for key in self.keys:\\n            key_tuple = (key.deployment_id, key.flow_version_id)\\n            if key_tuple in seen:\\n                continue\\n            seen.add(key_tuple)\\n            deduped.append(key)\\n        self.keys = deduped\\n        return self\\n\\n    def as_tuples(self) -> list[tuple[UUID, UUID]]:\\n        return [(key.deployment_id, key.flow_version_id) for key in self.keys]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/folder/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"137cc66987bcbf641357c508c0712beb98982b6d50a4cead64438e6e777c3fa7\",\"content\":\"from .model import Folder, FolderCreate, FolderRead, FolderUpdate\\n\\n__all__ = [\\\"Folder\\\", \\\"FolderCreate\\\", \\\"FolderRead\\\", \\\"FolderUpdate\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/folder/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b56288aef9569c1902d81d137e354287ad2d8d78b3eb2b968c47df79d17e6cda\",\"content\":\"import os\\n\\nDEFAULT_FOLDER_DESCRIPTION = \\\"Manage your own flows. Download and upload projects.\\\"\\n# Use DEFAULT_FOLDER_NAME env var, defaulting to \\\"Starter Project\\\" if not set\\nDEFAULT_FOLDER_NAME = os.getenv(\\\"DEFAULT_FOLDER_NAME\\\", \\\"Starter Project\\\")\\n\\n# Legacy folder names that may exist from previous installations\\nLEGACY_FOLDER_NAMES = [\\\"My Collection\\\", \\\"Starter Project\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/folder/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ea7a1d4c0da63a0ae36f8b08b86412860761731ae998249b4a7f26114ea4662\",\"content\":\"from typing import Optional\\nfrom uuid import UUID, uuid4\\n\\nfrom sqlalchemy import Text, UniqueConstraint\\nfrom sqlmodel import JSON, Column, Field, Relationship, SQLModel\\n\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.database.models.user.model import User\\n\\n\\nclass FolderBase(SQLModel):\\n    name: str = Field(index=True)\\n    description: str | None = Field(default=None, sa_column=Column(Text))\\n    auth_settings: dict | None = Field(\\n        default=None,\\n        sa_column=Column(JSON, nullable=True),\\n        description=\\\"Authentication settings for the folder/project\\\",\\n    )\\n\\n\\nclass Folder(FolderBase, table=True):  # type: ignore[call-arg]\\n    id: UUID | None = Field(default_factory=uuid4, primary_key=True)\\n    parent_id: UUID | None = Field(default=None, foreign_key=\\\"folder.id\\\")\\n\\n    parent: Optional[\\\"Folder\\\"] = Relationship(\\n        back_populates=\\\"children\\\",\\n        sa_relationship_kwargs={\\\"remote_side\\\": \\\"Folder.id\\\"},\\n    )\\n    children: list[\\\"Folder\\\"] = Relationship(back_populates=\\\"parent\\\")\\n    user_id: UUID | None = Field(default=None, foreign_key=\\\"user.id\\\")\\n    workspace_id: UUID | None = Field(default=None, nullable=True, index=True)\\n    user: User = Relationship(back_populates=\\\"folders\\\")\\n    flows: list[Flow] = Relationship(\\n        back_populates=\\\"folder\\\", sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete, delete-orphan\\\"}\\n    )\\n    deployments: list[Deployment] = Relationship(\\n        back_populates=\\\"folder\\\", sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete, delete-orphan\\\"}\\n    )\\n\\n    __table_args__ = (UniqueConstraint(\\\"user_id\\\", \\\"name\\\", name=\\\"unique_folder_name\\\"),)\\n\\n\\nclass FolderCreate(FolderBase):\\n    components_list: list[UUID] | None = None\\n    flows_list: list[UUID] | None = None\\n\\n\\nclass FolderRead(FolderBase):\\n    id: UUID\\n    parent_id: UUID | None = Field()\\n\\n\\nclass FolderListRead(FolderRead):\\n    owner_username: str | None = None\\n    is_owner: bool\\n\\n\\nclass FolderReadWithFlows(FolderBase):\\n    id: UUID\\n    parent_id: UUID | None = Field()\\n    flows: list[FlowRead] = Field(default=[])\\n\\n\\nclass FolderUpdate(SQLModel):\\n    name: str | None = None\\n    description: str | None = None\\n    parent_id: UUID | None = None\\n    components: list[UUID] = Field(default_factory=list)\\n    flows: list[UUID] = Field(default_factory=list)\\n    auth_settings: dict | None = None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/folder/pagination_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01b2648ea7754e316e2b51bf1d86a9766b6203780159305a1b07fe2a266023c3\",\"content\":\"from fastapi_pagination import Page\\n\\nfrom langflow.helpers.base_model import BaseModel\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.database.models.folder.model import FolderRead\\n\\n\\nclass FolderWithPaginatedFlows(BaseModel):\\n    folder: FolderRead\\n    flows: Page[FlowRead]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/folder/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"86bb0123b9f74c946e2d4632ff75c2cc37757dd7d8c74cae201805b41ebfdfb5\",\"content\":\"from uuid import UUID\\n\\nfrom sqlmodel import and_, select, update\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.initial_setup.setup import get_or_create_default_folder\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_flow_moves_allowed\\nfrom langflow.services.database.models.flow.model import Flow\\n\\nfrom .constants import DEFAULT_FOLDER_DESCRIPTION, DEFAULT_FOLDER_NAME\\nfrom .model import Folder\\n\\n\\nasync def create_default_folder_if_it_doesnt_exist(session: AsyncSession, user_id: UUID):\\n    stmt = select(Folder).where(Folder.user_id == user_id)\\n    folder = (await session.exec(stmt)).first()\\n    if not folder:\\n        folder = Folder(\\n            name=DEFAULT_FOLDER_NAME,\\n            user_id=user_id,\\n            description=DEFAULT_FOLDER_DESCRIPTION,\\n        )\\n        session.add(folder)\\n        await session.flush()\\n        await session.refresh(folder)\\n        flow_folder_pairs = [\\n            (flow_id, old_folder_id)\\n            for flow_id, old_folder_id in (\\n                await session.exec(\\n                    select(Flow.id, Flow.folder_id).where(\\n                        and_(\\n                            Flow.folder_id.is_(None),\\n                            Flow.user_id == user_id,\\n                        )\\n                    ),\\n                )\\n            ).all()\\n        ]\\n        await ensure_flow_moves_allowed(\\n            db=session,\\n            flow_folder_pairs=flow_folder_pairs,\\n            new_folder_id=folder.id,\\n        )\\n        await session.exec(\\n            update(Flow)\\n            .where(\\n                and_(\\n                    Flow.folder_id.is_(None),\\n                    Flow.user_id == user_id,\\n                )\\n            )\\n            .values(folder_id=folder.id, workspace_id=folder.workspace_id)\\n        )\\n    return folder\\n\\n\\nasync def get_default_folder_id(session: AsyncSession, user_id: UUID):\\n    folder = (\\n        await session.exec(select(Folder).where(Folder.name == DEFAULT_FOLDER_NAME, Folder.user_id == user_id))\\n    ).first()\\n    if not folder:\\n        folder = await get_or_create_default_folder(session, user_id)\\n    return folder.id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/ingestion_run/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f1845bba9e9b644bcc7b69bfb96ea42e0a9b5aaf0c63908c6e45768a401aa52\",\"content\":\"from langflow.services.database.models.ingestion_run.model import IngestionRun, IngestionRunStatus\\n\\n__all__ = [\\\"IngestionRun\\\", \\\"IngestionRunStatus\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/ingestion_run/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"176252f012e720a1708885ece89e9592dd47595225b4f7b433b152ec999096d3\",\"content\":\"\\\"\\\"\\\"Persistent record of a single KB ingestion run.\\n\\nOne row per invocation of ``KBIngestionHelper.perform_ingestion``.\\nCaptures the aggregate counters and per-item outcomes produced by a\\n``KBIngestionSource`` so the Phase 2 visibility UI can drill into a run\\nwithout re-walking the vector store.\\n\\nDesign notes:\\n\\n* ``job_id`` links back to the existing ``job`` table (one-to-one).\\n  Nullable so component-path ingestions (which don't go through the\\n  job service today) can still record a run.\\n* ``source_config`` stores source-specific configuration *minus*\\n  credentials \u2014 cloud connectors in Phase 3 should reference variables\\n  by name, not embed secret values here.\\n* ``items`` is a JSON array of per-file outcomes. Chosen over a\\n  separate ``ingestion_run_item`` table because the typical run size\\n  (tens to hundreds of files) fits comfortably in a single row, and\\n  Phase 2's drill-down reads the full list anyway. If future phases\\n  need sharded per-item queries, we expand (Phase 1+N) by adding a\\n  dedicated table in a later EXPAND migration.\\n* ``status`` is a Python-side string so we don't need a second enum\\n  migration when new outcomes are added; the allow-list is enforced in\\n  the application layer.\\n\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import JSON, BigInteger, CheckConstraint, Column, DateTime, ForeignKey, func\\nfrom sqlalchemy.dialects.postgresql import JSONB\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\n\\n# JSONB on Postgres (binary, dedup, GIN-indexable on the ``items``\\n# column), JSON elsewhere. Matches the variant used in migration\\n# ``72df732be86b``.\\nJsonVariant = JSON().with_variant(JSONB(), \\\"postgresql\\\")\\n\\n# Status allow-list \u2014 mirrors ``IngestionRunStatus``. Keep in sync\\n# with migration ``72df732be86b``.\\n_RUN_STATUS_VALUES = (\\\"pending\\\", \\\"running\\\", \\\"succeeded\\\", \\\"partial\\\", \\\"failed\\\", \\\"cancelled\\\")\\n\\n\\nclass IngestionRunStatus(str, Enum):\\n    \\\"\\\"\\\"Run-level outcome visible to the UI.\\n\\n    Kept distinct from ``JobStatus`` \u2014 job status describes scheduling\\n    (queued/in_progress/completed/etc.), while run status describes the\\n    ingestion *outcome* (did every file land?).\\n    \\\"\\\"\\\"\\n\\n    PENDING = \\\"pending\\\"\\n    RUNNING = \\\"running\\\"\\n    SUCCEEDED = \\\"succeeded\\\"\\n    PARTIAL = \\\"partial\\\"  # some items failed but run completed\\n    FAILED = \\\"failed\\\"\\n    CANCELLED = \\\"cancelled\\\"\\n\\n\\nclass IngestionRunBase(SQLModel):\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    job_id: UUID | None = Field(default=None, index=True, nullable=True)\\n    # ``kb_name`` is the legacy pointer (kept through an\\n    # expand-contract transition); ``kb_id`` is the new FK.\\n    kb_name: str = Field(index=True, nullable=False)\\n    # ``kb_id`` is the FK; ``ON DELETE SET NULL`` is set at the DB\\n    # layer so KB deletion does not orphan run history \u2014 rows remain\\n    # visible with a null kb_id. The physical FK constraint is\\n    # created by migration ``e728126476a8``; this ``sa_column`` makes\\n    # the ORM aware of it so relationships resolve correctly.\\n    kb_id: UUID | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"knowledge_base.id\\\", ondelete=\\\"SET NULL\\\"),\\n            index=True,\\n            nullable=True,\\n        ),\\n    )\\n    user_id: UUID | None = Field(default=None, index=True, nullable=True)\\n\\n    source_type: str = Field(index=True, nullable=False)\\n    source_config: dict[str, Any] = Field(\\n        default_factory=dict,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    status: str = Field(default=IngestionRunStatus.PENDING.value, index=True, nullable=False)\\n    error_message: str | None = Field(default=None, nullable=True)\\n\\n    total_items: int = Field(default=0, nullable=False)\\n    succeeded: int = Field(default=0, nullable=False)\\n    failed: int = Field(default=0, nullable=False)\\n    skipped: int = Field(default=0, nullable=False)\\n    # BigInteger: cumulative byte count of an ingestion run can\\n    # exceed the int32 ~2GB cap when ingesting large cloud blobs.\\n    # Matches ``knowledge_base.size_bytes``.\\n    total_bytes: int = Field(\\n        default=0,\\n        sa_column=Column(BigInteger, nullable=False, server_default=\\\"0\\\"),\\n    )\\n    chunks_created: int = Field(default=0, nullable=False)\\n\\n    items: list[dict[str, Any]] = Field(\\n        default_factory=list,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    # User-supplied run-level metadata (tags, categories, custom fields).\\n    # Persisted here so the run-history UI can render the tags applied to\\n    # the batch without scanning chunk-level ``source_metadata`` blobs.\\n    # Per-file overrides are NOT stored here \u2014 they live on each chunk's\\n    # ``source_metadata`` and on the per-item entries in ``items``.\\n    user_metadata: dict[str, Any] = Field(\\n        default_factory=dict,\\n        sa_column=Column(JsonVariant, nullable=False, server_default=\\\"{}\\\"),\\n    )\\n\\n    # ``server_default=func.now()`` keeps ``started_at`` populated on\\n    # raw-SQL inserts. Indexed because list endpoints order by this\\n    # column \u2014 without the index, large run histories sequential-scan.\\n    started_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False, server_default=func.now(), index=True),\\n    )\\n    finished_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), nullable=True),\\n    )\\n\\n\\nclass IngestionRun(IngestionRunBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"ingestion_run\\\"\\n    __table_args__ = (\\n        CheckConstraint(\\n            \\\"status IN (\\\" + \\\", \\\".join(f\\\"'{v}'\\\" for v in _RUN_STATUS_VALUES) + \\\")\\\",\\n            name=conv(\\\"ck_ingestion_run_status\\\"),\\n        ),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/jobs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e2774e184a4233a846d3d0f0421c2aeb1cf1bebc077ab80a2c8a8d2436696301\",\"content\":\"from .model import ExecutionSignal, Job, JobCheckpoint, JobEvent, SignalType\\n\\n__all__ = [\\\"ExecutionSignal\\\", \\\"Job\\\", \\\"JobCheckpoint\\\", \\\"JobEvent\\\", \\\"SignalType\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/jobs/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cbc8ccf72ce6254aab758bdfec6080230eebc1649b4756ecd811e8192b31dbb1\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n    from datetime import datetime\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom sqlalchemy import update\\nfrom sqlmodel import col, or_, select\\n\\nfrom langflow.services.database.models.jobs.model import Job, JobStatus\\n\\n\\nasync def get_jobs_by_flow_id(db: AsyncSession, flow_id: UUID, page: int = 1, size: int = 10) -> list[Job]:\\n    \\\"\\\"\\\"Get jobs by flow ID with pagination.\\n\\n    Args:\\n        db: Async database session\\n        flow_id: The flow ID to filter jobs by\\n        page: Page number (1-indexed)\\n        size: Number of jobs per page\\n\\n    Returns:\\n        List of Job objects for the specified flow\\n    \\\"\\\"\\\"\\n    statement = (\\n        select(Job)\\n        .where(Job.flow_id == flow_id)\\n        .order_by(col(Job.created_timestamp).desc())\\n        .offset((page - 1) * size)\\n        .limit(size)\\n    )\\n\\n    result = await db.exec(statement)\\n    return list(result.all())\\n\\n\\nasync def get_job_by_job_id(db: AsyncSession, job_id: UUID, user_id: UUID | None = None) -> Job | None:\\n    \\\"\\\"\\\"Get a single job by its UUID.\\n\\n    Args:\\n        db: Async database session\\n        job_id: The job ID to fetch\\n        user_id: When provided, restricts the result to jobs owned by this user\\n            or legacy jobs with no owner (user_id IS NULL).\\n\\n    Returns:\\n        Job object or None if not found (or not accessible by the given user)\\n    \\\"\\\"\\\"\\n    statement = select(Job).where(Job.job_id == job_id)\\n    if user_id is not None:\\n        statement = statement.where(or_(Job.user_id == user_id, col(Job.user_id).is_(None)))\\n    result = await db.exec(statement)\\n    return result.first()\\n\\n\\nasync def update_job_status(\\n    db: AsyncSession,\\n    job_id: UUID,\\n    status: JobStatus,\\n    *,\\n    finished_timestamp: datetime | None = None,\\n) -> Job | None:\\n    \\\"\\\"\\\"Update the status of a job.\\n\\n    Args:\\n        db: Async database session\\n        job_id: The job ID to update\\n        status: The new status value\\n        finished_timestamp: Optional timestamp to set atomically with the status\\n\\n    Returns:\\n        Updated Job object or None if not found\\n    \\\"\\\"\\\"\\n    values = {\\\"status\\\": status}\\n    if finished_timestamp is not None:\\n        values[\\\"finished_timestamp\\\"] = finished_timestamp\\n\\n    result = await db.exec(\\n        update(Job).where(Job.job_id == job_id).values(**values).execution_options(synchronize_session=False)\\n    )\\n    if result.rowcount == 0:\\n        return None\\n    return await get_job_by_job_id(db, job_id)\\n\\n\\nasync def get_latest_jobs_by_asset_ids(db: AsyncSession, asset_ids: Sequence[UUID]) -> dict[UUID, Job]:\\n    \\\"\\\"\\\"Get the latest job for each asset ID in a single query.\\n\\n    Args:\\n        db: Async database session\\n        asset_ids: List of asset IDs to fetch jobs for\\n\\n    Returns:\\n        Dictionary mapping asset_id to the latest Job object\\n    \\\"\\\"\\\"\\n    if not asset_ids:\\n        return {}\\n\\n    # Query all jobs for the given asset IDs, ordered by created_timestamp descending\\n    statement = select(Job).where(col(Job.asset_id).in_(asset_ids)).order_by(col(Job.created_timestamp).desc())\\n\\n    result = await db.exec(statement)\\n    all_jobs = result.all()\\n\\n    # Build a dictionary with the latest job per asset_id\\n    latest_jobs: dict[UUID, Job] = {}\\n    for job in all_jobs:\\n        if job.asset_id and job.asset_id not in latest_jobs:\\n            latest_jobs[job.asset_id] = job\\n\\n    return latest_jobs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/jobs/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bce206a2e15475c20f938f4367d1f3ddd4e82398ee75a48069cab0fc3a1cc44e\",\"content\":\"from datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nfrom sqlalchemy import JSON, Column, DateTime, Integer, String, Text, UniqueConstraint\\nfrom sqlalchemy import Enum as SQLEnum\\nfrom sqlalchemy.dialects.postgresql import JSONB\\nfrom sqlmodel import Field, SQLModel\\n\\n# JSONB on Postgres (GIN-indexable), JSON elsewhere \u2014 same variant as other JSON columns.\\nJsonVariant = JSON().with_variant(JSONB(), \\\"postgresql\\\")\\n\\n\\nclass JobStatus(str, Enum):\\n    QUEUED = \\\"queued\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    COMPLETED = \\\"completed\\\"\\n    FAILED = \\\"failed\\\"\\n    CANCELLED = \\\"cancelled\\\"\\n    TIMED_OUT = \\\"timed_out\\\"\\n    SUSPENDED = \\\"suspended\\\"\\n\\n\\nclass JobType(str, Enum):\\n    \\\"\\\"\\\"Enum to specify type of job.\\n\\n    WORKFLOW: for workflow execution\\n    INGESTION: for knowledge base ingestion\\n    EVALUATION: for evaluation of workflows.\\n\\n    Can be extended in future for other types of jobs.\\n    \\\"\\\"\\\"\\n\\n    WORKFLOW = \\\"workflow\\\"\\n    INGESTION = \\\"ingestion\\\"\\n    EVALUATION = \\\"evaluation\\\"\\n\\n\\nclass JobBase(SQLModel):\\n    job_id: UUID = Field(primary_key=True, index=True)\\n    flow_id: UUID = Field(index=True)\\n    status: JobStatus = Field(\\n        default=JobStatus.QUEUED,\\n        sa_column=Column(\\n            SQLEnum(JobStatus, name=\\\"job_status_enum\\\", values_callable=lambda obj: [item.value for item in obj]),\\n            nullable=False,\\n            index=False,\\n        ),\\n    )\\n    created_timestamp: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n    finished_timestamp: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), nullable=True),\\n    )\\n    type: JobType | None = Field(\\n        default=JobType.WORKFLOW,\\n        sa_column=Column(\\n            SQLEnum(JobType, name=\\\"job_type_enum\\\", values_callable=lambda obj: [item.value for item in obj]),\\n            nullable=True,\\n            index=True,\\n        ),\\n    )\\n    user_id: UUID | None = Field(index=True, nullable=True)\\n    asset_id: UUID | None = Field(index=True, nullable=True)\\n    asset_type: str | None = Field(\\n        index=False, nullable=True\\n    )  # Polymorphic: records if job is related to an entity like a KB, workflow, etc.\\n    dedupe_key: str | None = Field(\\n        index=True, nullable=True\\n    )  # Optional idempotency key to prevent duplicate jobs for the same asset and operation.\\n\\n    # Free-form per-JobType progress/outcome data; nullable so old rows read without backfill.\\n    job_metadata: dict[str, Any] | None = Field(\\n        default=None,\\n        sa_column=Column(JsonVariant, nullable=True),\\n    )\\n\\n    # Durable terminal payloads: result on COMPLETED, error on FAILED/TIMED_OUT; both nullable.\\n    result: dict[str, Any] | None = Field(\\n        default=None,\\n        sa_column=Column(JsonVariant, nullable=True),\\n    )\\n    error: dict[str, Any] | None = Field(\\n        default=None,\\n        sa_column=Column(JsonVariant, nullable=True),\\n    )\\n\\n\\nclass Job(JobBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"job\\\"\\n\\n\\nclass JobEvent(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Durable event log for a background job.\\n\\n    ``seq`` is the per-job monotonic cursor used as the SSE Last-Event-ID.\\n    UNIQUE(job_id, seq) enforces gap-free ordering and lets append_event\\n    detect collisions.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"job_events\\\"\\n    __table_args__ = (UniqueConstraint(\\\"job_id\\\", \\\"seq\\\", name=\\\"uq_job_events_job_id_seq\\\"),)\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True, index=True)\\n    job_id: UUID = Field(index=True, nullable=False)\\n    seq: int = Field(sa_column=Column(Integer, nullable=False))\\n    event_type: str = Field(sa_column=Column(String, nullable=False))\\n    payload: dict[str, Any] | None = Field(\\n        default=None,\\n        sa_column=Column(JsonVariant, nullable=True),\\n    )\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n\\n\\nclass SignalType(str, Enum):\\n    \\\"\\\"\\\"Cooperative control signals delivered to a running job.\\\"\\\"\\\"\\n\\n    STOP = \\\"stop\\\"\\n    PAUSE = \\\"pause\\\"\\n    RESUME = \\\"resume\\\"\\n\\n\\nclass ExecutionSignal(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"A control signal row for a job.\\n\\n    The runner polls unconsumed rows at vertex boundaries and stamps\\n    ``consumed_at`` once acted upon.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"execution_signals\\\"\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True, index=True)\\n    job_id: UUID = Field(index=True, nullable=False)\\n    signal_type: SignalType = Field(\\n        sa_column=Column(\\n            SQLEnum(\\n                SignalType,\\n                name=\\\"execution_signal_type_enum\\\",\\n                values_callable=lambda obj: [item.value for item in obj],\\n            ),\\n            nullable=False,\\n        ),\\n    )\\n    data: dict[str, Any] | None = Field(\\n        default=None,\\n        sa_column=Column(JsonVariant, nullable=True),\\n    )\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n    consumed_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), nullable=True),\\n    )\\n\\n\\nclass JobCheckpoint(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"A durable suspend/resume checkpoint blob for a job.\\n\\n    ``blob`` is opaque, already-serialized text the persistence layer never\\n    parses: graph checkpoints store JSON, the agent saver (LE-1447) stores\\n    base64(msgpack). ``kind`` discriminates them; UNIQUE(job_id, kind) keeps a\\n    single live checkpoint per job per kind (save upserts).\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"job_checkpoints\\\"\\n    __table_args__ = (UniqueConstraint(\\\"job_id\\\", \\\"kind\\\", name=\\\"uq_job_checkpoints_job_id_kind\\\"),)\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    job_id: UUID = Field(index=True, nullable=False)\\n    kind: str = Field(sa_column=Column(String, nullable=False))\\n    blob: str = Field(sa_column=Column(Text, nullable=False))\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/knowledge_base/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0e70b92bdbfe88b361efed2135e4a07160d49d6135bd611115faab2f90d56b33\",\"content\":\"from langflow.services.database.models.knowledge_base.model import (\\n    KnowledgeBaseRecord,\\n    KnowledgeBaseStatus,\\n)\\n\\n__all__ = [\\\"KnowledgeBaseRecord\\\", \\\"KnowledgeBaseStatus\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/knowledge_base/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f69aebc331e65b0594bce4bc4f836a4e4d9ce5eae4a0ef5ebaa0971d6648ada9\",\"content\":\"\\\"\\\"\\\"Persistent KB identity + configuration.\\n\\nOne row per Knowledge Base, and the sole source of truth. It replaced the\\n``embedding_metadata.json`` + ``schema.json`` sidecars, which are no longer\\nwritten or read: a KB exists because this row exists, not because a directory\\ndoes. Directories left by a version that predates the row are adopted only by\\nthe explicit ``langflow reconcile-kb-from-disk`` command.\\n\\nCached statistics (chunk / word / character counts, on-disk size,\\nfile-extension list) live alongside the config so list endpoints can\\nanswer without touching the vector store. The truth remains in the vector\\nstore; these columns are refreshed at the end of each ingestion run via\\n``KBAnalysisHelper.update_text_metrics_via_backend``.\\n\\nNotable columns:\\n\\n* ``backend_type`` / ``backend_config`` \u2014 where this KB's vectors live.\\n  The authoritative routing for every read and write. Note that both\\n  Chroma modes store ``\\\"chroma\\\"``; ``backend_config[\\\"mode\\\"] == \\\"cloud\\\"``\\n  is the discriminator, so use ``is_local_chroma`` rather than comparing\\n  ``backend_type`` alone.\\n* ``model_selection`` \u2014 the full unified-models dict captured at\\n  create time. Single source of truth for embedding config; the\\n  ``get_embedding_provider`` / ``get_embedding_model`` helpers in\\n  ``langflow.api.utils.knowledge_base_service`` read provider / model\\n  name out of it for display, and retrieval + ingestion reconstruct\\n  the embedding function from it without re-resolving the catalog.\\n* ``column_config`` \u2014 column roles (vectorize / identifier) from the\\n  tabular ingestion component. JSON array.\\n\\nUnique constraint on ``(user_id, name)`` \u2014 the guard against duplicate KBs,\\nand what makes ``{user}/{kb_name}`` a safe local-Chroma directory layout.\\n\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import JSON, BigInteger, CheckConstraint, Column, DateTime, ForeignKey, UniqueConstraint, func\\nfrom sqlalchemy.dialects.postgresql import JSONB\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\n\\n# JSONB on Postgres for GIN indexability + binary storage; JSON on\\n# SQLite. The migration uses the identical variant so the ORM and DDL\\n# produce matching columns.\\nJsonVariant = JSON().with_variant(JSONB(), \\\"postgresql\\\")\\n\\n# Status allow-list mirrors ``KnowledgeBaseStatus`` below \u2014 keep both\\n# in sync with migration ``15fe9304bca7``.\\n_KB_STATUS_VALUES = (\\\"creating\\\", \\\"ready\\\", \\\"ingesting\\\", \\\"failed\\\")\\n\\n\\nclass KnowledgeBaseStatus(str, Enum):\\n    \\\"\\\"\\\"Lifecycle state visible to the UI.\\\"\\\"\\\"\\n\\n    CREATING = \\\"creating\\\"\\n    READY = \\\"ready\\\"\\n    INGESTING = \\\"ingesting\\\"\\n    FAILED = \\\"failed\\\"\\n\\n\\nclass KnowledgeBaseRecordBase(SQLModel):\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    name: str = Field(index=True, nullable=False)\\n    # FK with ``ON DELETE CASCADE``: deleting a user deletes their KBs\\n    # at the DB layer, preventing orphan rows from surviving a raw\\n    # ``DELETE FROM user``.\\n    user_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"),\\n            index=True,\\n            nullable=False,\\n        ),\\n    )\\n\\n    # ``model_selection`` is the canonical source of truth for embedding\\n    # config. The legacy flat columns (``embedding_provider`` /\\n    # ``embedding_model``) were removed in favor of the\\n    # ``get_embedding_provider`` / ``get_embedding_model`` helpers in\\n    # ``langflow.api.utils.knowledge_base_service`` that read from this\\n    # dict. The API response shape still surfaces the flat fields as a\\n    # convenience view (derived via those helpers in\\n    # ``record_to_metadata_dict``).\\n    model_selection: dict[str, Any] = Field(\\n        default_factory=dict,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    chunk_size: int = Field(default=1000, nullable=False)\\n    chunk_overlap: int = Field(default=200, nullable=False)\\n    separator: str | None = Field(default=None, nullable=True)\\n    column_config: list[dict[str, Any]] = Field(\\n        default_factory=list,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    # Authoritative vector-store routing. See the module docstring on why\\n    # ``backend_type`` alone does not distinguish local Chroma from Chroma Cloud.\\n    backend_type: str = Field(default=\\\"chroma\\\", nullable=False)\\n    backend_config: dict[str, Any] = Field(\\n        default_factory=dict,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    # Cached aggregates refreshed after each ingestion run.\\n    chunks: int = Field(default=0, nullable=False)\\n    words: int = Field(default=0, nullable=False)\\n    characters: int = Field(default=0, nullable=False)\\n    size_bytes: int = Field(\\n        default=0,\\n        # BigInteger matches the migration: a cloud-backed KB with\\n        # millions of chunks can blow past int32's ~2GB cap.\\n        sa_column=Column(BigInteger, nullable=False, server_default=\\\"0\\\"),\\n    )\\n    source_types: list[str] = Field(\\n        default_factory=list,\\n        sa_column=Column(JsonVariant, nullable=False),\\n    )\\n\\n    status: str = Field(default=KnowledgeBaseStatus.READY.value, nullable=False, index=True)\\n    failure_reason: str | None = Field(default=None, nullable=True)\\n\\n    # ``server_default=func.now()`` keeps the column populated even\\n    # when rows are inserted via raw SQL (backfill, admin scripts).\\n    # The Python ``default_factory`` remains so ORM-level inserts get\\n    # a timezone-aware UTC value without a round-trip.\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False, server_default=func.now()),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False, server_default=func.now()),\\n    )\\n\\n\\nclass KnowledgeBaseRecord(KnowledgeBaseRecordBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"knowledge_base\\\"\\n    __table_args__ = (\\n        UniqueConstraint(\\\"user_id\\\", \\\"name\\\", name=\\\"uq_knowledge_base_user_name\\\"),\\n        CheckConstraint(\\n            \\\"status IN (\\\" + \\\", \\\".join(f\\\"'{v}'\\\" for v in _KB_STATUS_VALUES) + \\\")\\\",\\n            name=conv(\\\"ck_knowledge_base_status\\\"),\\n        ),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/mcp_server/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bfd1505075df88bd905cce9c9cd5dc1a57c56c84b9d55db1849ef8c56ed752af\",\"content\":\"from .model import MCPServer\\n\\n__all__ = [\\n    \\\"MCPServer\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/mcp_server/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3228e3bfb5069fafaf67e5b4b78bd19ddf1570683d3fbcf6c5b8e497d0e5d261\",\"content\":\"from datetime import datetime, timezone\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import ForeignKey\\nfrom sqlmodel import JSON, Column, Field, SQLModel, UniqueConstraint\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\n\\nclass MCPServer(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"A single MCP client server entry for a user.\\n\\n    Replaces the per-user ``_mcp_servers_<user_id>.json`` file: one row per\\n    server, keyed uniquely by ``(user_id, name)`` so concurrent edits to a user's\\n    server list cannot lose updates. The full ``mcpServers`` entry (command/args/\\n    env/headers/url plus any extra fields) is kept in the ``config`` JSON column;\\n    secret-bearing values inside it are encrypted at rest.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"mcp_server\\\"\\n    # (user_id, name) ordering: unique per user AND the composite index's leading\\n    # user_id column serves get_server_list's `WHERE user_id = ?` lookup.\\n    __table_args__ = (UniqueConstraint(\\\"user_id\\\", \\\"name\\\", name=\\\"uq_mcp_server_name_user\\\"),)\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUID = Field(sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False))\\n    name: str = Field(nullable=False)\\n    transport: str | None = Field(default=None)\\n    config: dict | None = Field(default=None, sa_column=Column(JSON))\\n    enabled: bool = Field(default=True)\\n    version: int = Field(default=1)\\n    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    updated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/memory_base/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3443b7a476add9da6d150b84ac4f23c6f9b83e8fab9700187581bd93ce4a0a86\",\"content\":\"from langflow.services.database.models.memory_base.model import (\\n    MemoryBase,\\n    MemoryBaseCreate,\\n    MemoryBaseRead,\\n    MemoryBaseSession,\\n    MemoryBaseSessionRead,\\n    MemoryBaseUpdate,\\n    MemoryBaseWorkflowRun,\\n    MessageIngestionRecord,\\n)\\n\\n__all__ = [\\n    \\\"MemoryBase\\\",\\n    \\\"MemoryBaseCreate\\\",\\n    \\\"MemoryBaseRead\\\",\\n    \\\"MemoryBaseSession\\\",\\n    \\\"MemoryBaseSessionRead\\\",\\n    \\\"MemoryBaseUpdate\\\",\\n    \\\"MemoryBaseWorkflowRun\\\",\\n    \\\"MessageIngestionRecord\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/memory_base/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"56bf69aaf0483ef7d4a8f82446f91a3b8612fc46f9619566bbd87d928cf396ed\",\"content\":\"from datetime import datetime, timezone\\nfrom uuid import UUID, uuid4\\n\\nimport sqlalchemy as sa\\nfrom pydantic import model_validator\\nfrom sqlalchemy import JSON, Column, DateTime, ForeignKey, Index, Text, UniqueConstraint\\nfrom sqlmodel import Field, Relationship, SQLModel\\n\\n\\nclass MemoryBaseBase(SQLModel):\\n    name: str = Field(index=False)\\n    flow_id: UUID = Field(index=True)\\n    user_id: UUID = Field(index=True)\\n    threshold: int = Field(default=50)\\n    auto_capture: bool = Field(default=True)\\n    embedding_model: str = Field(default=\\\"\\\")\\n    preprocessing: bool = Field(default=False)\\n    preproc_model: str | None = Field(default=None)\\n    preproc_instructions: str | None = Field(default=None)\\n    preproc_kill_phrase: str | None = Field(default=None)\\n\\n\\nclass MemoryBase(MemoryBaseBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"memory_base\\\"\\n    __table_args__ = (UniqueConstraint(\\\"user_id\\\", \\\"name\\\", name=\\\"uq_memory_base_user_name\\\"),)\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    # kb_name is auto-generated at creation time \u2014 not user-supplied\\n    kb_name: str = Field(default=\\\"\\\")\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n\\n    sessions: list[\\\"MemoryBaseSession\\\"] = Relationship(\\n        back_populates=\\\"memory_base\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete-orphan\\\"},\\n    )\\n\\n\\nclass MemoryBaseCreate(MemoryBaseBase):\\n    user_id: UUID | None = None  # Derived from auth token in the endpoint; not required in request body\\n\\n    # Vector-store selection for the Memory Base's backing KB. Declared on the\\n    # create payload rather than on ``MemoryBaseBase`` so no column is added to\\n    # the ``memory_base`` table: the values are persisted on the\\n    # ``knowledge_base`` row this Memory Base creates, which is what every read\\n    # path resolves against. ``None`` lets the server choose the deployment\\n    # default (pgvector when its fixed server environment variable is present).\\n    backend_type: str | None = None\\n    backend_config: dict = Field(default_factory=dict)\\n\\n    # Provider that serves ``embedding_model``, as selected by the caller.\\n    # Declared here rather than on ``MemoryBaseBase`` for the same reason as the\\n    # backend fields above: no column is added to the ``memory_base`` table\\n    # because the value is persisted in the backing ``knowledge_base`` row's\\n    # ``model_selection``, which every ingestion/retrieval path resolves against.\\n    # ``None`` falls back to name-based inference, which cannot see\\n    # live-discovered models (e.g. an OpenAI-Compatible endpoint's catalog).\\n    embedding_provider: str | None = None\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def preprocessing_defaults(self) -> \\\"MemoryBaseCreate\\\":\\n        if self.preprocessing and not self.preproc_model:\\n            msg = \\\"preproc_model is required when preprocessing is enabled\\\"\\n            raise ValueError(msg)\\n        # Default the kill phrase so callers that enable preprocessing without\\n        # supplying one still get the deterministic gate. Imported lazily so the\\n        # model module stays free of service-layer deps.\\n        if self.preprocessing and not self.preproc_kill_phrase:\\n            from langflow.services.memory_base.preprocessing import DEFAULT_KILL_PHRASE\\n\\n            self.preproc_kill_phrase = DEFAULT_KILL_PHRASE\\n        return self\\n\\n\\nclass MemoryBaseUpdate(SQLModel):\\n    name: str | None = None\\n    threshold: int | None = None\\n    auto_capture: bool | None = None\\n\\n\\nclass MemoryBaseRead(MemoryBaseBase):\\n    id: UUID\\n    kb_name: str\\n    created_at: datetime\\n    # Vector-store backend of the backing ``knowledge_base`` row (not columns on\\n    # the ``memory_base`` table). Populated by the API layer so the Memory Base\\n    # Control Center can surface it in the config dropdown. ``backend_config`` is\\n    # included so the UI can distinguish Chroma Local from Chroma Cloud (both use\\n    # ``backend_type=\\\"chroma\\\"``, discriminated by ``backend_config[\\\"mode\\\"]``); it\\n    # carries only variable names / routing flags, never secrets. Defaults suit a\\n    # Memory Base with no resolvable KB row.\\n    backend_type: str = \\\"chroma\\\"\\n    backend_config: dict = Field(default_factory=dict)\\n\\n\\nclass MemoryBaseSessionBase(SQLModel):\\n    \\\"\\\"\\\"Fields shared between the table class and response schemas.\\\"\\\"\\\"\\n\\n    session_id: str = Field(index=True)\\n    cursor_id: UUID | None = Field(default=None)\\n    total_processed: int = Field(default=0)\\n    last_sync_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), nullable=True),\\n    )\\n\\n\\nclass MemoryBaseSession(MemoryBaseSessionBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"memory_base_session\\\"\\n\\n    __table_args__ = (\\n        UniqueConstraint(\\\"memory_base_id\\\", \\\"session_id\\\", name=\\\"uq_memory_base_session\\\"),\\n        Index(\\\"ix_memory_base_session_lookup\\\", \\\"memory_base_id\\\", \\\"session_id\\\"),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n\\n    # FK defined via sa_column so Alembic sees the same shape as the migration:\\n    # inline ForeignKey on the column with ondelete=\\\"CASCADE\\\".\\n    # This matches the pattern used by the File model (ForeignKey on sa_column).\\n    memory_base_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"memory_base.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n            index=True,\\n        )\\n    )\\n\\n    memory_base: MemoryBase = Relationship(back_populates=\\\"sessions\\\")\\n\\n\\nclass MemoryBaseSessionRead(MemoryBaseSessionBase):\\n    id: UUID\\n    memory_base_id: UUID  # Explicit \u2014 not in base to keep base free of DB-layer FK\\n    pending_count: int = Field(default=0)\\n\\n\\nclass MemoryBaseWorkflowRun(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Tracks WORKFLOW job runs per (memory_base, session) for threshold-based ingestion.\\n\\n    One row per WORKFLOW job, per session, per memory base.\\n    - ``workflow_job_id``: the WORKFLOW job that produced this run (SET NULL on job deletion).\\n    - ``ingestion_job_id``: set only after the ingestion job that processed this run completes\\n      successfully. NULL means the run is still pending (not yet counted toward an ingestion).\\n\\n    Count pending = COUNT(*) WHERE ingestion_job_id IS NULL for a given (memory_base_id, session_id).\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"memory_base_workflow_run\\\"\\n    __table_args__ = (\\n        UniqueConstraint(\\\"memory_base_id\\\", \\\"session_id\\\", \\\"workflow_job_id\\\", name=\\\"uq_mbwr_mb_session_wf_job\\\"),\\n        Index(\\\"ix_mbwr_mb_session\\\", \\\"memory_base_id\\\", \\\"session_id\\\"),\\n        Index(\\\"ix_mbwr_ingestion_job_id\\\", \\\"ingestion_job_id\\\"),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    memory_base_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"memory_base.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n        )\\n    )\\n    session_id: str = Field(sa_column=Column(sa.String(), nullable=False))\\n    workflow_job_id: UUID | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"job.job_id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n    ingestion_job_id: UUID | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"job.job_id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n    recorded_at: datetime = Field(sa_column=Column(DateTime(timezone=True), nullable=False))\\n\\n\\nclass MessageIngestionRecord(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"M-N join table recording which messages were ingested into which Memory Base by which job.\\n\\n    One record per (message, session, memory_base) \u2014 enforced by the unique constraint.\\n    Records are written only after a confirmed successful Chroma write (write-on-success).\\n    On regenerate, all records for the memory_base are deleted atomically alongside the\\n    cursor reset so that re-ingestion starts clean.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"message_ingestion_record\\\"\\n    __table_args__ = (\\n        UniqueConstraint(\\\"message_id\\\", \\\"session_id\\\", \\\"memory_base_id\\\", name=\\\"uq_mir_message_session_mb\\\"),\\n        Index(\\\"ix_mir_message_id\\\", \\\"message_id\\\"),\\n        Index(\\\"ix_mir_job_id\\\", \\\"job_id\\\"),\\n        Index(\\\"ix_mir_memory_base_session\\\", \\\"memory_base_id\\\", \\\"session_id\\\"),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n\\n    message_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"message.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n        )\\n    )\\n    memory_base_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"memory_base.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n        )\\n    )\\n    job_id: UUID | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"job.job_id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n    # Denormalized from MessageTable.session_id \u2014 immutable, avoids JOIN on the hot query path\\n    session_id: str = Field(sa_column=Column(sa.String(), nullable=False))\\n    ingested_at: datetime = Field(sa_column=Column(DateTime(timezone=True), nullable=False))\\n\\n\\nclass MemoryBasePreprocessingOutput(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"One row per preprocessing batch \u2014 captures the LLM-distilled output before KB write.\\n\\n    Status flow:\\n      - ``processed``  \u2014 LLM produced output; Chroma write pending. Cursor NOT advanced.\\n                         The next ingestion job for this session reuses this row and\\n                         retries only the Chroma write (no LLM re-invocation).\\n      - ``ingested``   \u2014 Chroma write confirmed; cursor advanced; visible in get-messages view.\\n      - ``skipped``    \u2014 LLM emitted the kill phrase; no Chroma write, no output_text,\\n                         but cursor advances so the same batch is not re-evaluated.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"memory_base_preprocessing_output\\\"\\n    __table_args__ = (\\n        Index(\\n            \\\"ix_mbpo_pending\\\",\\n            \\\"memory_base_id\\\",\\n            \\\"session_id\\\",\\n            \\\"status\\\",\\n            \\\"created_at\\\",\\n        ),\\n        Index(\\n            \\\"ix_mbpo_listing\\\",\\n            \\\"memory_base_id\\\",\\n            \\\"session_id\\\",\\n            \\\"created_at\\\",\\n        ),\\n        Index(\\\"ix_mbpo_job_id\\\", \\\"job_id\\\"),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    memory_base_id: UUID = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"memory_base.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n        )\\n    )\\n    # Denormalized \u2014 immutable for the row's lifetime\\n    session_id: str = Field(sa_column=Column(sa.String(), nullable=False))\\n    job_id: UUID | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"job.job_id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n    status: str = Field(sa_column=Column(sa.String(), nullable=False))\\n    output_text: str | None = Field(default=None, sa_column=Column(Text(), nullable=True))\\n    # Canonical batch identity \u2014 JSON list of message UUIDs as strings.\\n    source_message_ids: list = Field(default_factory=list, sa_column=Column(JSON(), nullable=False))\\n    model_used: str = Field(sa_column=Column(sa.String(), nullable=False))\\n    created_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/message/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f2095bd3faf4e602078284a1e3e45bea9ec8cf5c5ea8e0561733210059bcb1f6\",\"content\":\"from .model import MessageCreate, MessageRead, MessageTable, MessageUpdate\\n\\n__all__ = [\\\"MessageCreate\\\", \\\"MessageRead\\\", \\\"MessageTable\\\", \\\"MessageUpdate\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/message/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1c5ee18bc7051797328b9e24d499738234659811a427ab1a4083c5be7c8546d2\",\"content\":\"from uuid import UUID\\n\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom sqlalchemy import delete\\nfrom sqlmodel import col, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.message.model import MessageTable, MessageUpdate\\nfrom langflow.services.deps import session_scope\\n\\n\\ndef _messages_for_user_stmt(user_id: UUID):\\n    # Centralized ownership filter used by read/update flows in monitor API.\\n    # Joining through Flow is the source of truth for message ownership.\\n    # MessageTable itself does not store user_id directly.\\n    return select(MessageTable).join(Flow, MessageTable.flow_id == Flow.id).where(Flow.user_id == user_id)\\n\\n\\nasync def get_message_for_user(session: AsyncSession, user_id: UUID, message_id: UUID) -> MessageTable | None:\\n    # Single-message lookup constrained by owner.\\n    stmt = _messages_for_user_stmt(user_id).where(MessageTable.id == message_id)\\n    return (await session.exec(stmt)).first()\\n\\n\\nasync def get_messages_for_user_by_session(session: AsyncSession, user_id: UUID, session_id: str) -> list[MessageTable]:\\n    # Bulk lookup by session, still constrained by owner.\\n    stmt = _messages_for_user_stmt(user_id).where(MessageTable.session_id == session_id)\\n    return (await session.exec(stmt)).all()\\n\\n\\nasync def get_message_ids_for_user(session: AsyncSession, user_id: UUID, message_ids: list[UUID]) -> list[UUID]:\\n    if not message_ids:\\n        return []\\n\\n    stmt = (\\n        select(MessageTable.id)\\n        .join(Flow, MessageTable.flow_id == Flow.id)\\n        .where(col(MessageTable.id).in_(message_ids))\\n        .where(Flow.user_id == user_id)\\n    )\\n    return (await session.exec(stmt)).all()\\n\\n\\nasync def get_message_ids_for_user_by_session(session: AsyncSession, user_id: UUID, session_id: str) -> list[UUID]:\\n    stmt = (\\n        select(MessageTable.id)\\n        .join(Flow, MessageTable.flow_id == Flow.id)\\n        .where(col(MessageTable.session_id) == session_id)\\n        .where(Flow.user_id == user_id)\\n    )\\n    return (await session.exec(stmt)).all()\\n\\n\\nasync def delete_messages_for_user(session: AsyncSession, user_id: UUID, message_ids: list[UUID]) -> None:\\n    # Select owned IDs first so mixed payloads only affect caller-owned rows.\\n    # This prevents a direct delete(MessageTable.id.in_(...)) from ever touching\\n    # records the caller should not control.\\n    owned_message_ids = await get_message_ids_for_user(session, user_id, message_ids)\\n    if not owned_message_ids:\\n        # No owned targets: keep delete endpoint behavior as idempotent no-op.\\n        return\\n\\n    await session.exec(\\n        delete(MessageTable)\\n        .where(col(MessageTable.id).in_(owned_message_ids))\\n        .execution_options(synchronize_session=\\\"fetch\\\")\\n    )\\n\\n\\nasync def delete_messages_for_user_by_session(session: AsyncSession, user_id: UUID, session_id: str) -> None:\\n    # Same ownership-first strategy for bulk delete by session_id.\\n    # Session IDs are not globally trusted identifiers; ownership must be checked.\\n    owned_message_ids = await get_message_ids_for_user_by_session(session, user_id, session_id)\\n    if not owned_message_ids:\\n        # Returning without delete preserves 204 semantics without cross-tenant impact.\\n        return\\n\\n    await session.exec(\\n        delete(MessageTable)\\n        .where(col(MessageTable.id).in_(owned_message_ids))\\n        .execution_options(synchronize_session=\\\"fetch\\\")\\n    )\\n\\n\\nasync def _update_message(message_id: UUID | str, message: MessageUpdate | dict):\\n    if not isinstance(message, MessageUpdate):\\n        message = MessageUpdate(**message)\\n    async with session_scope() as session:\\n        db_message = await session.get(MessageTable, message_id)\\n        if not db_message:\\n            msg = \\\"Message not found\\\"\\n            raise ValueError(msg)\\n        message_dict = message.model_dump(exclude_unset=True, exclude_none=True)\\n        db_message.sqlmodel_update(message_dict)\\n        session.add(db_message)\\n        await session.flush()\\n        await session.refresh(db_message)\\n        return db_message\\n\\n\\ndef update_message(message_id: UUID | str, message: MessageUpdate | dict):\\n    \\\"\\\"\\\"DEPRECATED - Kept for backward compatibility. Do not use.\\\"\\\"\\\"\\n    return run_until_complete(_update_message(message_id, message))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/message/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"624904b62f7b83848832daa0301dfcea62ecc3a94c13109f1a54d31ba76851a1\",\"content\":\"import json\\nimport math\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Annotated\\nfrom uuid import UUID, uuid4\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom fastapi.encoders import jsonable_encoder\\nfrom lfx.schema.legacy_render import render_v1_content_blocks\\nfrom pydantic import ConfigDict, field_serializer, field_validator\\nfrom sqlalchemy import Index, Text, text\\nfrom sqlmodel import JSON, Column, Field, SQLModel\\n\\nfrom langflow.schema.content_block import ContentType\\nfrom langflow.schema.properties import Properties\\nfrom langflow.schema.validators import TF_WITH_TZ_AND_MICROSECONDS, str_to_timestamp, str_to_timestamp_validator\\n\\nif TYPE_CHECKING:\\n    from langflow.schema.message import Message\\n\\n# Columns a caller may order messages by. A tenant-supplied order_by is passed to\\n# getattr(MessageTable, order_by); validating against this allowlist prevents an arbitrary\\n# attribute name from raising a 500 error-oracle (or reaching a non-column attribute). Shared by\\n# the monitor endpoints and the langflow.memory query helper so they validate identically.\\nALLOWED_MESSAGE_ORDER_FIELDS = frozenset({\\\"timestamp\\\", \\\"sender\\\", \\\"sender_name\\\", \\\"session_id\\\", \\\"text\\\"})\\n\\n\\nclass MessageBase(SQLModel):\\n    timestamp: Annotated[datetime, str_to_timestamp_validator] = Field(\\n        default_factory=lambda: datetime.now(timezone.utc)\\n    )\\n    sender: str\\n    sender_name: str\\n    session_id: str\\n    context_id: str | None = Field(default=None)\\n    text: str = Field(sa_column=Column(Text))\\n    files: list[str] = Field(default_factory=list)\\n    error: bool = Field(default=False)\\n    edit: bool = Field(default=False)\\n\\n    properties: Properties = Field(default_factory=Properties)\\n    category: str = Field(default=\\\"message\\\")\\n    content_blocks: list[ContentType] = Field(default_factory=list)\\n    session_metadata: dict | None = Field(default=None)\\n\\n    @field_serializer(\\\"timestamp\\\")\\n    def serialize_timestamp(self, value):\\n        if isinstance(value, datetime):\\n            if value.tzinfo is None:\\n                value = value.replace(tzinfo=timezone.utc)\\n            return value.strftime(TF_WITH_TZ_AND_MICROSECONDS)\\n\\n        if isinstance(value, str):\\n            dt = str_to_timestamp(value)  # unified, UTC-normalized\\n            return dt.strftime(TF_WITH_TZ_AND_MICROSECONDS)\\n\\n        return value\\n\\n    @field_validator(\\\"files\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_files(cls, value):\\n        return value or []\\n\\n    @field_validator(\\\"session_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_session_id(cls, value):\\n        if isinstance(value, UUID):\\n            return str(value)\\n        return value\\n\\n    @classmethod\\n    def from_message(\\n        cls,\\n        message: \\\"Message\\\",\\n        flow_id: str | UUID | None = None,\\n        run_id: str | UUID | None = None,\\n        user_id: str | UUID | None = None,\\n    ):\\n        # ``message.text`` is now a computed_field over content_blocks. The\\n        # \\\"content present\\\" signal is: ``data[\\\"text\\\"]`` explicitly set\\n        # (covers ``text=\\\"\\\"`` from ChatInput), a pending text stream\\n        # (iterator), or any ``content_blocks`` entries (covers tool-call /\\n        # media-only agent messages whose ``content_blocks`` carry the\\n        # whole payload).\\n        no_content = message.data.get(\\\"text\\\") is None and message.text_stream is None and not message.content_blocks\\n        if no_content or not message.sender or not message.sender_name:\\n            msg = \\\"The message does not have the required fields (text, sender, sender_name).\\\"\\n            raise ValueError(msg)\\n\\n        if message.files:\\n            image_paths = []\\n            for file in message.files:\\n                if hasattr(file, \\\"path\\\") and hasattr(file, \\\"url\\\") and file.path:\\n                    session_id = message.session_id\\n                    if session_id and str(session_id) in file.path:\\n                        parts = file.path.split(str(session_id))\\n                        if len(parts) > 1:\\n                            image_paths.append(f\\\"{session_id}{parts[1]}\\\")\\n                        else:\\n                            image_paths.append(file.path)\\n                    else:\\n                        image_paths.append(file.path)\\n                elif isinstance(file, str):\\n                    image_paths.append(file)\\n\\n            if image_paths:\\n                message.files = image_paths\\n\\n        if isinstance(message.timestamp, str):\\n            # Convert timestamp string in format \\\"YYYY-MM-DD HH:MM:SS.ffffff UTC\\\" to datetime\\n            try:\\n                timestamp = datetime.strptime(message.timestamp, TF_WITH_TZ_AND_MICROSECONDS).replace(\\n                    tzinfo=timezone.utc\\n                )\\n            except ValueError:\\n                # Fallback for ISO format if the above fails; astimezone preserves offset if present\\n                parsed = datetime.fromisoformat(message.timestamp)\\n                timestamp = parsed.astimezone(timezone.utc) if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)\\n        else:\\n            timestamp = message.timestamp\\n\\n        if not flow_id and message.flow_id:\\n            flow_id = message.flow_id\\n        if not run_id and getattr(message, \\\"run_id\\\", None):\\n            run_id = message.run_id\\n\\n        message_text = \\\"\\\" if not isinstance(message.text, str) else message.text\\n\\n        properties = (\\n            message.properties.model_dump_json()\\n            if hasattr(message.properties, \\\"model_dump_json\\\")\\n            else message.properties\\n        )\\n\\n        content_blocks = []\\n        for content_block in message.content_blocks or []:\\n            content = content_block.model_dump_json() if hasattr(content_block, \\\"model_dump_json\\\") else content_block\\n            content_blocks.append(content)\\n\\n        if isinstance(flow_id, str):\\n            try:\\n                flow_id = UUID(flow_id)\\n            except ValueError as exc:\\n                msg = f\\\"Flow ID {flow_id} is not a valid UUID\\\"\\n                raise ValueError(msg) from exc\\n\\n        if isinstance(run_id, str):\\n            try:\\n                run_id = UUID(run_id)\\n            except ValueError as exc:\\n                msg = f\\\"Run ID {run_id} is not a valid UUID\\\"\\n                raise ValueError(msg) from exc\\n\\n        if isinstance(user_id, str):\\n            try:\\n                user_id = UUID(user_id)\\n            except ValueError as exc:\\n                msg = f\\\"User ID {user_id} is not a valid UUID\\\"\\n                raise ValueError(msg) from exc\\n\\n        return cls(\\n            sender=message.sender,\\n            sender_name=message.sender_name,\\n            text=message_text,\\n            session_id=message.session_id,\\n            context_id=message.context_id,\\n            files=message.files or [],\\n            timestamp=timestamp,\\n            flow_id=flow_id,\\n            run_id=run_id,\\n            user_id=user_id,\\n            properties=properties,\\n            category=message.category,\\n            content_blocks=content_blocks,\\n            session_metadata=getattr(message, \\\"session_metadata\\\", None),\\n        )\\n\\n\\nclass MessageTable(MessageBase, table=True):  # type: ignore[call-arg]\\n    model_config = ConfigDict(validate_assignment=True, arbitrary_types_allowed=True)\\n\\n    __tablename__ = \\\"message\\\"\\n    __table_args__ = (\\n        # Every history read filters by flow_id (the monitor endpoints) or by\\n        # session_id (chat memory) and orders by timestamp. Without these the\\n        # whole message table is scanned and sorted on each read, which is what\\n        # made a flow with a long history stall the API. ``id`` trails the sort\\n        # key because it is the paging tie-breaker; leaving it out makes the\\n        # planner sort the matched rows instead of walking the index in order.\\n        Index(\\\"ix_message_flow_id_timestamp_id\\\", \\\"flow_id\\\", \\\"timestamp\\\", \\\"id\\\"),\\n        Index(\\\"ix_message_session_id_timestamp_id\\\", \\\"session_id\\\", \\\"timestamp\\\", \\\"id\\\"),\\n        Index(\\n            \\\"ix_message_session_metadata_tenant\\\",\\n            text(\\\"(session_metadata->>'tenant_id')\\\"),\\n            postgresql_using=\\\"btree\\\",\\n        ),\\n        Index(\\n            \\\"ix_message_session_metadata_user\\\",\\n            text(\\\"(session_metadata->>'user_id')\\\"),\\n            postgresql_using=\\\"btree\\\",\\n        ),\\n    )\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    flow_id: UUID | None = Field(default=None)\\n    run_id: UUID | None = Field(default=None, index=True)\\n    # Owner of the message (the user that executed the flow). Scopes chat-history retrieval so a\\n    # reused session_id cannot disclose another user's messages on the authenticated run path.\\n    # Nullable for legacy rows / contexts with no owner concept.\\n    user_id: UUID | None = Field(default=None, index=True)\\n    is_output: bool = Field(default=False)\\n\\n    files: list[str] = Field(sa_column=Column(JSON))\\n    properties: dict | Properties = Field(  # type: ignore[assignment]\\n        default_factory=lambda: Properties().model_dump(),\\n        sa_column=Column(JSON),\\n    )\\n    category: str = Field(sa_column=Column(Text))\\n    content_blocks: list[dict | ContentType] = Field(  # type: ignore[assignment]\\n        default_factory=list,\\n        sa_column=Column(JSON),\\n    )\\n\\n    # Enterprise session metadata - flexible JSON column for client-provided context\\n    session_metadata: dict | None = Field(\\n        default=None,\\n        sa_column=Column(JSON),\\n        description=\\\"Session context data (e.g., user roles, custom tags, or analytics data).\\\",\\n    )\\n\\n    @field_validator(\\\"flow_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_id(cls, value):\\n        if value is None:\\n            return value\\n        if isinstance(value, str):\\n            return UUID(value)\\n        return value\\n\\n    @field_validator(\\\"user_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_user_id(cls, value):\\n        if value is None:\\n            return value\\n        if isinstance(value, str):\\n            return UUID(value)\\n        return value\\n\\n    @staticmethod\\n    def _sanitize_json(value):\\n        \\\"\\\"\\\"Coerce values into a JSON-safe shape before they reach the SQL UPDATE.\\n\\n        Replaces float NaN/Infinity with None to avoid PostgreSQL jsonb rejection,\\n        and resolves non-serializable Python objects (notably pandas DataFrame /\\n        lfx Table instances and numpy scalars) that can leak into ContentBlock\\n        fields when an upstream component output \u2014 e.g. the Memory Base\\n        ``retrieve_data`` Table \u2014 is captured by message tracking before the\\n        consumer (Parser) has converted it to text.\\n        \\\"\\\"\\\"\\n        # numpy scalars (np.float64, np.int64, np.bool_, ...) survive\\n        # ``jsonable_encoder`` when nested inside a DataFrame-derived dict\\n        # and would later be rejected by the jsonb encoder. Coerce them to\\n        # their Python-native counterparts so persistence succeeds. This must\\n        # come before the ``float`` / ``int`` / ``bool`` checks because numpy\\n        # scalars inherit from those Python types.\\n        if isinstance(value, np.generic):\\n            return MessageTable._sanitize_json(value.item())\\n\\n        if isinstance(value, bool):\\n            return value\\n\\n        if isinstance(value, float):\\n            if not math.isfinite(value):\\n                return None\\n            return value\\n\\n        if isinstance(value, dict):\\n            return {k: MessageTable._sanitize_json(v) for k, v in value.items()}\\n\\n        if isinstance(value, list):\\n            return [MessageTable._sanitize_json(v) for v in value]\\n\\n        if isinstance(value, pd.DataFrame):\\n            return [MessageTable._sanitize_json(record) for record in value.to_dict(orient=\\\"records\\\")]\\n\\n        if value is None or isinstance(value, str | int):\\n            return value\\n\\n        # Unknown type \u2014 coerce to a JSON-safe representation rather than\\n        # letting it propagate to the SQL UPDATE and fail persistence.\\n        try:\\n            encoded = jsonable_encoder(value)\\n        except (TypeError, ValueError):\\n            return str(value)\\n        if encoded is value:\\n            return str(value)\\n        return MessageTable._sanitize_json(encoded)\\n\\n    @field_validator(\\\"properties\\\", \\\"content_blocks\\\", \\\"session_metadata\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_properties_or_content_blocks(cls, value):\\n        if isinstance(value, list):\\n            value = [cls.validate_properties_or_content_blocks(item) for item in value]\\n        elif hasattr(value, \\\"model_dump\\\"):\\n            value = value.model_dump()\\n        elif isinstance(value, str):\\n            value = json.loads(value)\\n\\n        return cls._sanitize_json(value)\\n\\n    @field_serializer(\\\"properties\\\", \\\"content_blocks\\\", \\\"session_metadata\\\")\\n    @classmethod\\n    def serialize_properties_or_content_blocks(cls, value) -> dict | list[dict]:\\n        # Redundant sanitization here acts as a defensive measure for rows\\n        # already in the database that might contain NaN/Infinity values.\\n        if isinstance(value, list):\\n            value = [cls.serialize_properties_or_content_blocks(item) for item in value]\\n        elif hasattr(value, \\\"model_dump\\\"):\\n            value = value.model_dump()\\n        elif isinstance(value, str):\\n            value = json.loads(value)\\n\\n        return cls._sanitize_json(value)\\n\\n\\nclass MessageRead(MessageBase):\\n    id: UUID\\n    flow_id: UUID | None = None\\n    session_metadata: dict | None = None\\n    run_id: UUID | None = None\\n    # v1 read shape: hold content_blocks as legacy dicts and render the\\n    # release-1.11.0 shape, so editing/reading a stored message (new-shape rows\\n    # or pre-1.11.0 untagged rows) keeps the v1 wire shape and never trips the\\n    # new union validator (the union_tag_not_found 500 on PUT /messages/{id}).\\n    content_blocks: list[dict] = Field(default_factory=list)  # type: ignore[assignment]\\n\\n    @field_validator(\\\"content_blocks\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def render_legacy_content_blocks(cls, value):\\n        return render_v1_content_blocks(value) or []\\n\\n\\ndef _coerce_content_block_dicts(value):\\n    \\\"\\\"\\\"Normalize content_blocks items to plain dicts (request-parse path).\\n\\n    Accepts legacy/new dicts and ContentType model instances without forcing\\n    them through the new discriminated union, and stores them as-sent (no v1\\n    legacy projection: these are input models, not the v1 response).\\n    \\\"\\\"\\\"\\n    if isinstance(value, list):\\n        return [block.model_dump() if hasattr(block, \\\"model_dump\\\") else block for block in value]\\n    return value\\n\\n\\nclass MessageCreate(MessageBase):\\n    session_metadata: dict | None = None\\n    content_blocks: list[dict] = Field(default_factory=list)  # type: ignore[assignment]\\n\\n    @field_validator(\\\"content_blocks\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def coerce_content_blocks(cls, value):\\n        return _coerce_content_block_dicts(value) or []\\n\\n\\nclass MessageUpdate(SQLModel):\\n    text: str | None = None\\n    sender: str | None = None\\n    sender_name: str | None = None\\n    session_id: str | None = None\\n    context_id: str | None = None\\n    files: list[str] | None = None\\n    edit: bool | None = None\\n    error: bool | None = None\\n    properties: Properties | None = None\\n    session_metadata: dict | None = None\\n    category: str | None = None\\n    content_blocks: list[dict] | None = None\\n\\n    @field_validator(\\\"content_blocks\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def coerce_content_blocks(cls, value):\\n        return _coerce_content_block_dicts(value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/model_provider_policy/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"84ed3fef1fc02331867f7f49fdabd9e6ca8b904d9ab4b3b5bda05f070c74195c\",\"content\":\"from .model import MODEL_PROVIDER_POLICY_SINGLETON_ID, ModelProviderPolicy\\n\\n__all__ = [\\\"MODEL_PROVIDER_POLICY_SINGLETON_ID\\\", \\\"ModelProviderPolicy\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/model_provider_policy/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"351abd3035b5a04909ce2d63279ee784528de7aab85c4679917ee1fe50dca34a\",\"content\":\"import sqlalchemy as sa\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\n\\nMODEL_PROVIDER_POLICY_SINGLETON_ID = 1\\n\\n\\nclass ModelProviderPolicy(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Versioned singleton containing the install-wide provider ceiling.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"model_provider_policy\\\"\\n    __table_args__ = (\\n        sa.CheckConstraint(\\n            f\\\"id = {MODEL_PROVIDER_POLICY_SINGLETON_ID}\\\",\\n            name=conv(\\\"ck_model_provider_policy_singleton\\\"),\\n        ),\\n        sa.CheckConstraint(\\\"version >= 0\\\", name=conv(\\\"ck_model_provider_policy_version\\\")),\\n    )\\n\\n    id: int = Field(default=MODEL_PROVIDER_POLICY_SINGLETON_ID, primary_key=True)\\n    approved_provider_ids: list[str] = Field(default_factory=list, sa_column=sa.Column(sa.JSON, nullable=False))\\n    version: int = Field(default=0, nullable=False, ge=0)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/policy_bundle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"41cd77efdf95212fe4c84e86da38bb5fdc74fd21c96ab2e5812949fe0d53b712\",\"content\":\"from .model import (\\n    POLICY_BUNDLE_REASON_MAX_LENGTH,\\n    POLICY_BUNDLE_SINGLETON_ID,\\n    POLICY_BUNDLE_SOURCE_MAX_LENGTH,\\n    PolicyBundleActive,\\n    PolicyBundleRevision,\\n)\\n\\n__all__ = [\\n    \\\"POLICY_BUNDLE_REASON_MAX_LENGTH\\\",\\n    \\\"POLICY_BUNDLE_SINGLETON_ID\\\",\\n    \\\"POLICY_BUNDLE_SOURCE_MAX_LENGTH\\\",\\n    \\\"PolicyBundleActive\\\",\\n    \\\"PolicyBundleRevision\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/policy_bundle/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c57e4824bc58f2a4c84f2f29fe350778c8f1f3005cdd95ed5d280a1bd7660111\",\"content\":\"\\\"\\\"\\\"Immutable deployment policy bundle history and active revision pointer.\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\nPOLICY_BUNDLE_SINGLETON_ID = 1\\nPOLICY_BUNDLE_REASON_MAX_LENGTH = 1024\\nPOLICY_BUNDLE_SOURCE_MAX_LENGTH = 32\\n\\n\\ndef _utc_now() -> datetime:\\n    return datetime.now(timezone.utc)\\n\\n\\nclass PolicyBundleRevision(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"One immutable, complete deployment-governance policy revision.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"policy_bundle_revision\\\"\\n    __table_args__ = (\\n        sa.CheckConstraint(\\\"revision >= 1\\\", name=conv(\\\"ck_policy_bundle_revision_positive\\\")),\\n        sa.CheckConstraint(\\\"length(content_hash) = 64\\\", name=conv(\\\"ck_policy_bundle_revision_hash_length\\\")),\\n    )\\n\\n    revision: int = Field(primary_key=True, ge=1)\\n    initialized: bool = Field(default=True, sa_column=sa.Column(sa.Boolean(), nullable=False))\\n    approved_provider_ids: list[str] = Field(default_factory=list, sa_column=sa.Column(sa.JSON, nullable=False))\\n    blocked_component_keys: list[str] = Field(default_factory=list, sa_column=sa.Column(sa.JSON, nullable=False))\\n    blocked_template_keys: list[str] = Field(default_factory=list, sa_column=sa.Column(sa.JSON, nullable=False))\\n    # Nullable with a server default to match the EXPAND-phase migration:\\n    # revisions written before the column existed read back as \\\"blocks\\n    # nothing\\\" without a backfill. Writers always provide the value.\\n    blocked_model_keys: list[str] = Field(\\n        default_factory=list,\\n        sa_column=sa.Column(sa.JSON, nullable=True, server_default=sa.text(\\\"'[]'\\\")),\\n    )\\n    content_hash: str = Field(sa_column=sa.Column(sa.String(64), nullable=False))\\n    source: str = Field(\\n        default=\\\"api\\\",\\n        max_length=POLICY_BUNDLE_SOURCE_MAX_LENGTH,\\n        sa_column=sa.Column(sa.String(POLICY_BUNDLE_SOURCE_MAX_LENGTH), nullable=False),\\n    )\\n    created_by: UUIDstr | None = Field(\\n        default=None,\\n        # Immutable history keeps actor attribution even if the user row is\\n        # later deleted; authentication validates the actor before insertion.\\n        sa_column=sa.Column(sa.Uuid(), nullable=True),\\n    )\\n    created_at: datetime = Field(\\n        default_factory=_utc_now,\\n        sa_column=sa.Column(sa.DateTime(timezone=True), nullable=False, server_default=sa.func.now()),\\n    )\\n    reason: str | None = Field(\\n        default=None,\\n        max_length=POLICY_BUNDLE_REASON_MAX_LENGTH,\\n        sa_column=sa.Column(sa.String(POLICY_BUNDLE_REASON_MAX_LENGTH), nullable=True),\\n    )\\n    rollback_of_revision: int | None = Field(\\n        default=None,\\n        sa_column=sa.Column(\\n            sa.Integer(),\\n            sa.ForeignKey(\\\"policy_bundle_revision.revision\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n\\n\\nclass PolicyBundleActive(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Singleton pointer used to allocate and activate revisions with CAS.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"policy_bundle_active\\\"\\n    __table_args__ = (\\n        sa.CheckConstraint(\\n            f\\\"id = {POLICY_BUNDLE_SINGLETON_ID}\\\",\\n            name=conv(\\\"ck_policy_bundle_active_singleton\\\"),\\n        ),\\n        sa.CheckConstraint(\\\"revision >= 1\\\", name=conv(\\\"ck_policy_bundle_active_revision_positive\\\")),\\n    )\\n\\n    id: int = Field(default=POLICY_BUNDLE_SINGLETON_ID, primary_key=True)\\n    # Deliberately no FK: writers CAS this pointer before inserting the new\\n    # immutable revision in the same transaction. No reader can observe the\\n    # uncommitted pointer, and a failed insert rolls the CAS back atomically.\\n    revision: int = Field(nullable=False, ge=1)\\n    initialized: bool = Field(\\n        default=False,\\n        sa_column=sa.Column(sa.Boolean(), nullable=False, server_default=sa.false()),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=_utc_now,\\n        sa_column=sa.Column(\\n            sa.DateTime(timezone=True),\\n            nullable=False,\\n            server_default=sa.func.now(),\\n            onupdate=sa.func.now(),\\n        ),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/traces/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d592390d469e817a55e8d349e36b0414a1261793949975608a55f87a61c5986d\",\"content\":\"from .model import SpanTable, TraceTable\\n\\n__all__ = [\\\"SpanTable\\\", \\\"TraceTable\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/traces/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"27b1f279aa4563e56c3fd061463d19c9b1d4cc9e47005aaf2dbc924ca00f7122\",\"content\":\"from datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Any, Optional\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import BaseModel, ConfigDict, field_serializer, field_validator\\nfrom pydantic import Field as PydanticField\\nfrom pydantic.alias_generators import to_camel\\nfrom sqlalchemy import Enum as SQLEnum\\nfrom sqlalchemy import types as sa_types\\nfrom sqlmodel import JSON, Column, Field, Relationship, SQLModel, Text\\n\\nfrom langflow.serialization.serialization import serialize\\n\\n\\ndef _enum_values(enum_cls: type[Enum]) -> list[str]:\\n    \\\"\\\"\\\"Return the enum's string values so SQLAlchemy serializes them instead of the enum NAMEs.\\n\\n    The trace/span PostgreSQL enums (``spanstatus``, ``spantype``, ``spankind``) are defined\\n    in migration ``3478f0bd6ccb`` using the enum *values*. Without this callable, SQLAlchemy\\n    sends the enum *names* (e.g. ``\\\"OK\\\"`` instead of ``\\\"ok\\\"``) on insert, which PostgreSQL\\n    rejects with ``invalid input value for enum spanstatus: \\\"OK\\\"``.\\n    \\\"\\\"\\\"\\n    return [member.value for member in enum_cls]\\n\\n\\nclass _LegacyCaseEnum(sa_types.TypeDecorator):\\n    \\\"\\\"\\\"SQLAlchemy column type that normalises legacy uppercase enum names on read.\\n\\n    Before ``values_callable=_enum_values`` was added, SQLAlchemy stored enum\\n    *names* (e.g. ``'OK'``) rather than enum *values* (e.g. ``'ok'``).\\n    The result_processor introduced by that fix validates the raw DB string\\n    against the values list, so old rows with uppercase names raise\\n    ``LookupError``.\\n\\n    This decorator intercepts the raw DB string and tries a case-insensitive\\n    match against both enum values and enum names so old and new rows both\\n    round-trip cleanly.\\n\\n    ``result_processor`` is overridden so the impl (``SQLEnum``) processor\\n    does not run first. A plain :class:`TypeDecorator` runs the impl's\\n    ``result_processor`` *before* ``process_result_value``, and the\\n    impl's processor raises ``LookupError`` on legacy uppercase strings\\n    before our normalisation gets a chance to run. See\\n    https://github.com/langflow-ai/langflow/issues/13318.\\n    \\\"\\\"\\\"\\n\\n    impl = SQLEnum\\n    cache_ok = True\\n\\n    def __init__(self, enum_cls: type[Enum], *, name: str) -> None:\\n        self._enum_cls = enum_cls\\n        self._by_value: dict[str, Enum] = {m.value: m for m in enum_cls}\\n        self._by_name: dict[str, Enum] = {m.name: m for m in enum_cls}\\n        super().__init__(enum_cls, name=name, values_callable=_enum_values)\\n\\n    def result_processor(self, dialect, _coltype):\\n        \\\"\\\"\\\"Skip the impl's strict ``result_processor`` so legacy rows can be normalised.\\n\\n        The default ``TypeDecorator.result_processor`` chains\\n        ``impl.result_processor`` \u2192 ``process_result_value``. The impl is\\n        ``SQLEnum`` whose processor calls ``_object_value_for_elem`` and raises\\n        ``LookupError`` on any string not in the lowercase values list. Pre-v1.9.2\\n        rows persist the enum *names* (e.g. ``'OK'``) which fail that check\\n        before ``process_result_value`` can normalise them. We bypass the impl\\n        here and run only our own normalisation against the raw DB value.\\n        \\\"\\\"\\\"\\n\\n        def process(value):\\n            return self.process_result_value(value, dialect)\\n\\n        return process\\n\\n    def process_result_value(self, value: str | None, _dialect) -> Enum | None:\\n        if value is None:\\n            return None\\n        if isinstance(value, self._enum_cls):\\n            return value\\n        member = self._by_value.get(value) or self._by_name.get(value)\\n        if member is None:\\n            lower = value.lower()\\n            member = self._by_value.get(lower) or self._by_name.get(lower)\\n        if member is None:\\n            msg = f\\\"{value!r} is not a valid {self._enum_cls.__name__} value\\\"\\n            raise LookupError(msg)\\n        return member\\n\\n\\nclass SpanKind(str, Enum):\\n    \\\"\\\"\\\"OpenTelemetry SpanKind values.\\n\\n    Describes the relationship between the span, its parents, and its children\\n    in a distributed trace.\\n\\n    - INTERNAL: Default. Represents an internal operation within an application.\\n    - CLIENT: Represents a request made to some remote service.\\n    - SERVER: Represents a request received from a remote client.\\n    - PRODUCER: Represents the initiation of an asynchronous request.\\n    - CONSUMER: Represents the processing of an asynchronous message.\\n    \\\"\\\"\\\"\\n\\n    INTERNAL = \\\"INTERNAL\\\"\\n    CLIENT = \\\"CLIENT\\\"\\n    SERVER = \\\"SERVER\\\"\\n    PRODUCER = \\\"PRODUCER\\\"\\n    CONSUMER = \\\"CONSUMER\\\"\\n\\n\\nclass SpanType(str, Enum):\\n    \\\"\\\"\\\"Types of spans that can be recorded.\\\"\\\"\\\"\\n\\n    CHAIN = \\\"chain\\\"\\n    LLM = \\\"llm\\\"\\n    TOOL = \\\"tool\\\"\\n    RETRIEVER = \\\"retriever\\\"\\n    EMBEDDING = \\\"embedding\\\"\\n    PARSER = \\\"parser\\\"\\n    AGENT = \\\"agent\\\"\\n\\n\\nclass SpanStatus(str, Enum):\\n    \\\"\\\"\\\"OpenTelemetry status codes.\\n\\n    - UNSET: Default status, span has not ended yet\\n    - OK: Span completed successfully\\n    - ERROR: Span completed with an error\\n    \\\"\\\"\\\"\\n\\n    UNSET = \\\"unset\\\"\\n    OK = \\\"ok\\\"\\n    ERROR = \\\"error\\\"\\n\\n\\nclass TraceBase(SQLModel):\\n    \\\"\\\"\\\"Base model for traces.\\\"\\\"\\\"\\n\\n    name: str = Field(nullable=False, description=\\\"Name of the trace (usually flow name)\\\")\\n    status: SpanStatus = Field(\\n        default=SpanStatus.UNSET,\\n        sa_column=Column(\\n            _LegacyCaseEnum(SpanStatus, name=\\\"spanstatus\\\"),\\n            nullable=False,\\n        ),\\n        description=\\\"Overall trace status\\\",\\n    )\\n    start_time: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        description=\\\"When the trace started\\\",\\n    )\\n    end_time: datetime | None = Field(default=None, description=\\\"When the trace ended\\\")\\n    total_latency_ms: int = Field(default=0, description=\\\"Total execution time in milliseconds\\\")\\n    total_tokens: int = Field(default=0, description=\\\"Total tokens used across all LLM calls\\\")\\n    flow_id: UUID = Field(\\n        foreign_key=\\\"flow.id\\\",\\n        ondelete=\\\"CASCADE\\\",\\n        index=True,\\n        description=\\\"ID of the flow this trace belongs to\\\",\\n    )\\n    session_id: str | None = Field(\\n        default=None,\\n        nullable=True,\\n        index=True,\\n        description=\\\"Session ID for grouping traces\\\",\\n    )\\n\\n    model_config = ConfigDict(arbitrary_types_allowed=True)\\n\\n    @field_validator(\\\"flow_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_id(cls, value):\\n        if value is None:\\n            msg = \\\"flow_id is required and cannot be None\\\"\\n            raise ValueError(msg)\\n        if isinstance(value, str):\\n            value = UUID(value)\\n        return value\\n\\n\\nclass TraceTable(TraceBase, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Database table for storing execution traces.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"trace\\\"\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    spans: list[\\\"SpanTable\\\"] = Relationship(\\n        back_populates=\\\"trace\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete-orphan\\\"},\\n    )\\n\\n\\nclass SpanReadResponse(BaseModel):\\n    \\\"\\\"\\\"Response model for a single span, with nested children.\\n\\n    Serializes to camelCase JSON to match the frontend API contract.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(\\n        alias_generator=to_camel,\\n        populate_by_name=True,\\n        from_attributes=True,\\n    )\\n\\n    id: UUID\\n    name: str\\n    type: SpanType\\n    status: SpanStatus\\n    start_time: datetime | None\\n    end_time: datetime | None\\n    latency_ms: int\\n    inputs: dict[str, Any] | None\\n    outputs: dict[str, Any] | None\\n    error: str | None\\n    model_name: str | None\\n    token_usage: dict[str, Any] | None\\n    children: list[\\\"SpanReadResponse\\\"] = PydanticField(default_factory=list)\\n\\n\\nclass TraceRead(BaseModel):\\n    \\\"\\\"\\\"Response model for a single trace with its hierarchical span tree.\\n\\n    Serializes to camelCase JSON to match the frontend API contract.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(\\n        alias_generator=to_camel,\\n        populate_by_name=True,\\n        from_attributes=True,\\n    )\\n\\n    id: UUID\\n    name: str\\n    status: SpanStatus\\n    start_time: datetime | None\\n    end_time: datetime | None\\n    total_latency_ms: int\\n    total_tokens: int\\n    flow_id: UUID\\n    session_id: str\\n    input: dict[str, Any] | str | None = None\\n    output: dict[str, Any] | str | None = None\\n    spans: list[SpanReadResponse] = PydanticField(default_factory=list)\\n\\n\\nclass TraceSummaryRead(BaseModel):\\n    \\\"\\\"\\\"Lightweight trace model for list endpoint.\\n\\n    Serializes to camelCase JSON to match the frontend API contract.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(\\n        alias_generator=to_camel,\\n        populate_by_name=True,\\n        from_attributes=True,\\n    )\\n\\n    id: UUID\\n    name: str\\n    status: SpanStatus\\n    start_time: datetime | None\\n    total_latency_ms: int\\n    total_tokens: int\\n    flow_id: UUID\\n    session_id: str\\n    input: dict[str, Any] | str | None = None\\n    output: dict[str, Any] | str | None = None\\n\\n\\nclass TraceListResponse(BaseModel):\\n    \\\"\\\"\\\"Paginated list response for traces.\\\"\\\"\\\"\\n\\n    traces: list[TraceSummaryRead]\\n    total: int\\n    pages: int\\n\\n\\nclass TraceCreate(SQLModel):\\n    \\\"\\\"\\\"Create model for traces.\\\"\\\"\\\"\\n\\n    name: str\\n    flow_id: UUID\\n    session_id: str | None = None\\n\\n\\nclass SpanBase(SQLModel):\\n    \\\"\\\"\\\"Base model for spans (individual execution steps).\\\"\\\"\\\"\\n\\n    name: str = Field(nullable=False, description=\\\"Name of the span following OTel convention: '{operation} {model}'\\\")\\n    span_type: SpanType = Field(\\n        default=SpanType.CHAIN,\\n        sa_column=Column(\\n            _LegacyCaseEnum(SpanType, name=\\\"spantype\\\"),\\n            nullable=False,\\n        ),\\n        description=\\\"Type of operation\\\",\\n    )\\n    status: SpanStatus = Field(\\n        default=SpanStatus.UNSET,\\n        sa_column=Column(\\n            _LegacyCaseEnum(SpanStatus, name=\\\"spanstatus\\\"),\\n            nullable=False,\\n        ),\\n        description=\\\"Execution status\\\",\\n    )\\n    start_time: datetime = Field(\\n        default_factory=lambda: datetime.now(timezone.utc),\\n        description=\\\"When the span started\\\",\\n    )\\n    end_time: datetime | None = Field(default=None, description=\\\"When the span ended\\\")\\n    latency_ms: int = Field(default=0, description=\\\"Execution time in milliseconds\\\")\\n    inputs: dict[str, Any] | None = Field(default=None, sa_column=Column(JSON))\\n    outputs: dict[str, Any] | None = Field(default=None, sa_column=Column(JSON))\\n    error: str | None = Field(default=None, sa_column=Column(Text), description=\\\"Error message if failed\\\")\\n    span_kind: SpanKind = Field(\\n        default=SpanKind.INTERNAL,\\n        sa_column=Column(\\n            SQLEnum(SpanKind, name=\\\"spankind\\\", values_callable=_enum_values),\\n            nullable=False,\\n        ),\\n        description=\\\"OpenTelemetry SpanKind\\\",\\n    )\\n    # OTel-compliant extensible attributes\\n    attributes: dict[str, Any] = Field(\\n        default_factory=dict,\\n        sa_column=Column(JSON),\\n    )\\n\\n    model_config = ConfigDict(arbitrary_types_allowed=True)\\n\\n    @field_serializer(\\\"inputs\\\")\\n    def serialize_inputs(self, data) -> dict | None:\\n        if data is None:\\n            return None\\n        return serialize(data)\\n\\n    @field_serializer(\\\"outputs\\\")\\n    def serialize_outputs(self, data) -> dict | None:\\n        if data is None:\\n            return None\\n        return serialize(data)\\n\\n    @field_serializer(\\\"attributes\\\")\\n    def serialize_attributes(self, data):\\n        if data is None:\\n            return None\\n        return serialize(data)\\n\\n\\nclass SpanTable(SpanBase, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Database table for storing execution spans.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"span\\\"\\n\\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\\n    trace_id: UUID = Field(\\n        foreign_key=\\\"trace.id\\\",\\n        ondelete=\\\"CASCADE\\\",\\n        index=True,\\n        description=\\\"Parent trace ID\\\",\\n    )\\n    parent_span_id: UUID | None = Field(\\n        default=None,\\n        foreign_key=\\\"span.id\\\",\\n        index=True,\\n        description=\\\"Parent span ID for nested spans\\\",\\n    )\\n\\n    # Relationships\\n    trace: TraceTable = Relationship(back_populates=\\\"spans\\\")\\n    parent: Optional[\\\"SpanTable\\\"] = Relationship(\\n        back_populates=\\\"children\\\",\\n        sa_relationship_kwargs={\\\"remote_side\\\": \\\"SpanTable.id\\\"},\\n    )\\n    children: list[\\\"SpanTable\\\"] = Relationship(back_populates=\\\"parent\\\")\\n\\n\\nclass SpanCreate(SQLModel):\\n    \\\"\\\"\\\"Create model for spans.\\\"\\\"\\\"\\n\\n    name: str\\n    span_type: SpanType = SpanType.CHAIN\\n    trace_id: UUID\\n    parent_span_id: UUID | None = None\\n    inputs: dict[str, Any] | None = None\\n    # OTel attributes\\n    attributes: dict[str, Any] | None = None\\n\\n\\nclass SpanUpdate(SQLModel):\\n    \\\"\\\"\\\"Update model for completing spans.\\\"\\\"\\\"\\n\\n    status: SpanStatus | None = None\\n    end_time: datetime | None = None\\n    latency_ms: int | None = None\\n    outputs: dict[str, Any] | None = None\\n    error: str | None = None\\n    # OTel attribute\\n    attributes: dict[str, Any] | None = None\\n\\n\\n# SpanReadResponse and TraceRead reference each other via forward refs; rebuild resolves them at import time.\\nSpanReadResponse.model_rebuild()\\nTraceRead.model_rebuild()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/transactions/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ae06136473a4616ced9a23237b179fa1a338a3be9fb472ad255aa6bb3ab62af8\",\"content\":\"from .model import TransactionTable\\n\\n__all__ = [\\\"TransactionTable\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/transactions/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"deb745a2f36cfbd2f082ddebd60dd658008aa1c3bc07800a81a6d05b84f2d67f\",\"content\":\"from uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import col, delete, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.transactions.model import (\\n    TransactionBase,\\n    TransactionLogsResponse,\\n    TransactionReadResponse,\\n    TransactionTable,\\n)\\nfrom langflow.services.deps import get_settings_service\\n\\n\\nasync def get_transactions_by_flow_id(\\n    db: AsyncSession, flow_id: UUID, limit: int | None = 1000\\n) -> list[TransactionTable]:\\n    stmt = (\\n        select(TransactionTable)\\n        .where(TransactionTable.flow_id == flow_id)\\n        .order_by(col(TransactionTable.timestamp))\\n        .limit(limit)\\n    )\\n\\n    transactions = await db.exec(stmt)\\n    return list(transactions)\\n\\n\\nasync def log_transaction(db: AsyncSession, transaction: TransactionBase) -> TransactionTable | None:\\n    \\\"\\\"\\\"Log a transaction and maintain a maximum number of transactions in the database.\\n\\n    This function logs a new transaction into the database and ensures that the number of transactions\\n    does not exceed the maximum limit specified in the settings. If the number of transactions exceeds\\n    the limit, the oldest transactions are deleted to maintain the limit.\\n\\n    Args:\\n        db: Database session\\n        transaction: Transaction data to log\\n\\n    Returns:\\n        The created TransactionTable entry\\n\\n    Raises:\\n        IntegrityError: If there is a database integrity error\\n    \\\"\\\"\\\"\\n    if not transaction.flow_id:\\n        await logger.adebug(\\\"Transaction flow_id is None\\\")\\n        return None\\n    table = TransactionTable(**transaction.model_dump())\\n\\n    try:\\n        # Get max entries setting\\n        max_entries = get_settings_service().settings.max_transactions_to_keep\\n\\n        # Delete older entries in a single transaction\\n        delete_older = delete(TransactionTable).where(\\n            TransactionTable.flow_id == transaction.flow_id,\\n            col(TransactionTable.id).in_(\\n                select(TransactionTable.id)\\n                .where(TransactionTable.flow_id == transaction.flow_id)\\n                .order_by(col(TransactionTable.timestamp).desc())\\n                .offset(max_entries - 1)  # Keep newest max_entries-1 plus the one we're adding\\n            ),\\n        )\\n\\n        # Add new entry and execute delete in same transaction\\n        db.add(table)\\n        await db.exec(delete_older)\\n        await db.commit()\\n\\n    except Exception:\\n        await db.rollback()\\n        raise\\n    return table\\n\\n\\ndef transform_transaction_table(\\n    transaction: list[TransactionTable] | TransactionTable,\\n) -> list[TransactionReadResponse] | TransactionReadResponse:\\n    if isinstance(transaction, list):\\n        return [TransactionReadResponse.model_validate(t, from_attributes=True) for t in transaction]\\n    return TransactionReadResponse.model_validate(transaction, from_attributes=True)\\n\\n\\ndef transform_transaction_table_for_logs(\\n    transaction: list[TransactionTable] | TransactionTable,\\n) -> list[TransactionLogsResponse] | TransactionLogsResponse:\\n    \\\"\\\"\\\"Transform transaction data for logs view, excluding error and flow_id.\\\"\\\"\\\"\\n    if isinstance(transaction, list):\\n        return [TransactionLogsResponse.model_validate(t, from_attributes=True) for t in transaction]\\n    return TransactionLogsResponse.model_validate(transaction, from_attributes=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/transactions/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f0fc0d1d192e8892a5893d87f13638d40bd61b49a85b12e3b81a8a781ee36a5e\",\"content\":\"import re\\nfrom datetime import datetime, timezone\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import field_serializer, field_validator\\nfrom sqlmodel import JSON, Column, Field, SQLModel\\n\\nfrom langflow.serialization.serialization import get_max_items_length, get_max_text_length, serialize\\n\\n# Keys that should have their values masked for security\\n# Pattern uses fullmatch-style matching to avoid false positives like \\\"max_tokens\\\"\\n# Each pattern should match the entire key or a specific suffix\\nSENSITIVE_KEY_NAMES = frozenset(\\n    {\\n        \\\"api_key\\\",\\n        \\\"api-key\\\",\\n        \\\"apikey\\\",\\n        \\\"password\\\",\\n        \\\"passwd\\\",\\n        \\\"secret\\\",\\n        \\\"token\\\",\\n        \\\"auth_token\\\",\\n        \\\"access_token\\\",\\n        \\\"api_token\\\",\\n        \\\"bearer_token\\\",\\n        \\\"credential\\\",\\n        \\\"credentials\\\",\\n        \\\"auth\\\",\\n        \\\"authorization\\\",\\n        \\\"bearer\\\",\\n        \\\"private_key\\\",\\n        \\\"private-key\\\",\\n        \\\"access_key\\\",\\n        \\\"access-key\\\",\\n        \\\"openai_api_key\\\",\\n        \\\"anthropic_api_key\\\",\\n    }\\n)\\n\\n# Pattern for keys that end with sensitive suffixes\\nSENSITIVE_KEYS_PATTERN = re.compile(\\n    r\\\".*[_-]?(api[_-]?key|password|secret|token|credential|auth|bearer|private[_-]?key|access[_-]?key)$\\\",\\n    re.IGNORECASE,\\n)\\n\\n# Keys to completely exclude from logs\\nEXCLUDED_KEYS = frozenset({\\\"code\\\"})\\n\\n# Minimum length for partial masking (show first 4 and last 4 chars)\\nMIN_LENGTH_FOR_PARTIAL_MASK = 12\\n\\n\\ndef _mask_sensitive_value(value: str) -> str:\\n    \\\"\\\"\\\"Mask a sensitive string value, showing only first 4 and last 4 chars.\\\"\\\"\\\"\\n    if len(value) <= MIN_LENGTH_FOR_PARTIAL_MASK:\\n        return \\\"***REDACTED***\\\"\\n    return f\\\"{value[:4]}...{value[-4:]}\\\"\\n\\n\\ndef _is_sensitive_key(key: str) -> bool:\\n    \\\"\\\"\\\"Check if a key name is sensitive and should be masked.\\\"\\\"\\\"\\n    key_lower = key.lower()\\n    # Check exact match first (faster)\\n    if key_lower in SENSITIVE_KEY_NAMES:\\n        return True\\n    # Check pattern match for keys ending with sensitive suffixes\\n    return bool(SENSITIVE_KEYS_PATTERN.match(key_lower))\\n\\n\\ndef _sanitize_dict(data: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Recursively sanitize a dictionary, masking sensitive values.\\\"\\\"\\\"\\n    result: dict[str, Any] = {}\\n    for key, value in data.items():\\n        if key in EXCLUDED_KEYS:\\n            continue\\n        if _is_sensitive_key(key):\\n            if isinstance(value, str) and value:\\n                result[key] = _mask_sensitive_value(value)\\n            else:\\n                result[key] = \\\"***REDACTED***\\\"\\n        elif isinstance(value, dict):\\n            result[key] = _sanitize_dict(value)\\n        elif isinstance(value, list):\\n            result[key] = _sanitize_list(value)\\n        else:\\n            result[key] = value\\n    return result\\n\\n\\ndef _sanitize_list(data: list[Any]) -> list[Any]:\\n    \\\"\\\"\\\"Recursively sanitize a list.\\\"\\\"\\\"\\n    result: list[Any] = []\\n    for item in data:\\n        if isinstance(item, dict):\\n            result.append(_sanitize_dict(item))\\n        elif isinstance(item, list):\\n            result.append(_sanitize_list(item))\\n        else:\\n            result.append(item)\\n    return result\\n\\n\\ndef sanitize_data(data: dict[str, Any] | None) -> dict[str, Any] | None:\\n    \\\"\\\"\\\"Sanitize data by masking sensitive values and excluding certain keys.\\\"\\\"\\\"\\n    if data is None:\\n        return None\\n    if not isinstance(data, dict):\\n        return data\\n    return _sanitize_dict(data)\\n\\n\\nclass TransactionBase(SQLModel):\\n    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    vertex_id: str = Field(nullable=False)\\n    target_id: str | None = Field(default=None)\\n    inputs: dict | None = Field(default=None, sa_column=Column(JSON))\\n    outputs: dict | None = Field(default=None, sa_column=Column(JSON))\\n    status: str = Field(nullable=False)\\n    error: str | None = Field(default=None)\\n    flow_id: UUID = Field()\\n\\n    # Needed for Column(JSON)\\n    class Config:\\n        arbitrary_types_allowed = True\\n\\n    def __init__(self, **data):\\n        # Sanitize inputs and outputs to remove sensitive data before storing\\n        if \\\"inputs\\\" in data and isinstance(data[\\\"inputs\\\"], dict):\\n            data[\\\"inputs\\\"] = sanitize_data(data[\\\"inputs\\\"])\\n        if \\\"outputs\\\" in data and isinstance(data[\\\"outputs\\\"], dict):\\n            data[\\\"outputs\\\"] = sanitize_data(data[\\\"outputs\\\"])\\n        super().__init__(**data)\\n\\n    @field_validator(\\\"flow_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_id(cls, value):\\n        if value is None:\\n            return value\\n        if isinstance(value, str):\\n            value = UUID(value)\\n        return value\\n\\n    @field_serializer(\\\"inputs\\\")\\n    def serialize_inputs(self, data) -> dict:\\n        \\\"\\\"\\\"Serialize inputs, sanitizing sensitive data and enforcing size limits.\\\"\\\"\\\"\\n        sanitized = sanitize_data(data)\\n        return serialize(sanitized, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n    @field_serializer(\\\"outputs\\\")\\n    def serialize_outputs(self, data) -> dict:\\n        \\\"\\\"\\\"Serialize outputs, sanitizing sensitive data and enforcing size limits.\\\"\\\"\\\"\\n        sanitized = sanitize_data(data)\\n        return serialize(sanitized, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n\\nclass TransactionTable(TransactionBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"transaction\\\"\\n    id: UUID | None = Field(default_factory=uuid4, primary_key=True)\\n\\n\\nclass TransactionReadResponse(TransactionBase):\\n    model_config = {\\\"populate_by_name\\\": True, \\\"from_attributes\\\": True}\\n\\n    id: UUID = Field(alias=\\\"transaction_id\\\")\\n    flow_id: UUID\\n\\n\\nclass TransactionLogsResponse(SQLModel):\\n    \\\"\\\"\\\"Transaction response model for logs view - excludes error and flow_id fields.\\\"\\\"\\\"\\n\\n    model_config = {\\\"populate_by_name\\\": True, \\\"from_attributes\\\": True}\\n\\n    id: UUID\\n    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    vertex_id: str = Field(nullable=False)\\n    target_id: str | None = Field(default=None)\\n    inputs: dict | None = Field(default=None)\\n    outputs: dict | None = Field(default=None)\\n    status: str = Field(nullable=False)\\n\\n    @field_serializer(\\\"inputs\\\")\\n    def serialize_inputs(self, data) -> dict:\\n        \\\"\\\"\\\"Serialize inputs, sanitizing sensitive data and enforcing size limits.\\\"\\\"\\\"\\n        sanitized = sanitize_data(data)\\n        return serialize(sanitized, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n    @field_serializer(\\\"outputs\\\")\\n    def serialize_outputs(self, data) -> dict:\\n        \\\"\\\"\\\"Serialize outputs, sanitizing sensitive data and enforcing size limits.\\\"\\\"\\\"\\n        sanitized = sanitize_data(data)\\n        return serialize(sanitized, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/user/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fde9bd0f17a665077aa2629d59395562f0d9d0d522c76e1458eab9ca666cffea\",\"content\":\"from .model import User, UserCreate, UserRead, UserUpdate\\n\\n__all__ = [\\n    \\\"User\\\",\\n    \\\"UserCreate\\\",\\n    \\\"UserRead\\\",\\n    \\\"UserUpdate\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/user/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"830ba6c9f53d002e814f123e2748f415444afeace66ddeec17d74aeb2559bdd5\",\"content\":\"from datetime import datetime, timezone\\nfrom uuid import UUID\\n\\nfrom fastapi import HTTPException, status\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlalchemy.orm.attributes import flag_modified\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.user.model import User, UserUpdate\\n\\n\\nasync def get_user_by_username(db: AsyncSession, username: str) -> User | None:\\n    stmt = select(User).where(User.username == username)\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def get_user_by_id(db: AsyncSession, user_id: UUID) -> User | None:\\n    if isinstance(user_id, str):\\n        user_id = UUID(user_id)\\n    stmt = select(User).where(User.id == user_id)\\n    return (await db.exec(stmt)).first()\\n\\n\\nasync def update_user(user_db: User | None, user: UserUpdate, db: AsyncSession) -> User:\\n    if not user_db:\\n        raise HTTPException(status_code=404, detail=\\\"User not found\\\")\\n\\n    # user_db_by_username = get_user_by_username(db, user.username)\\n    # if user_db_by_username and user_db_by_username.id != user_id:\\n    #     raise HTTPException(status_code=409, detail=\\\"Username already exists\\\")\\n\\n    user_data = user.model_dump(exclude_unset=True)\\n    changed = False\\n    for attr, value in user_data.items():\\n        if hasattr(user_db, attr) and value is not None:\\n            setattr(user_db, attr, value)\\n            changed = True\\n\\n    if not changed:\\n        raise HTTPException(status_code=status.HTTP_304_NOT_MODIFIED, detail=\\\"Nothing to update\\\")\\n\\n    user_db.updated_at = datetime.now(timezone.utc)\\n    flag_modified(user_db, \\\"updated_at\\\")\\n\\n    try:\\n        await db.flush()\\n    except IntegrityError as e:\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    return user_db\\n\\n\\nasync def update_user_last_login_at(user_id: UUID, db: AsyncSession";
